\begin{multline}
	\label{q_new}
	q_{i+\ha}^{n+1} = q_{i+\ha}^* \ -\ \dt g\Bigg((\xi_{i+\ha,i-1}^L+\xi_{i+\ha,i-1}^R ) \eta_{i-1}^{n+1} + (\xi_{i+\ha,i}^L +\xi_{i+\ha,i}^R)\eta_{i}^{n+1} \\  
	 + (\xi_{i+\ha,i+1}^L +\xi_{i+\ha,i+1}^R)\eta_{i+1}^{n+1} + (\xi_{i+\ha,i+2}^L +\xi_{i+\ha,i+2}^R)\eta_{i+2}^{n+1}   \Bigg).    
\end{multline}

Now, these values of $q_{i+\ha}$ are replaced in \eqref{eta_1}, obtaining the elliptic equation for $\eta$
\begin{align}
    \nonumber
    & \eta_{i-2}^{n+1} \, \frac{\dt^2}{\dx}g\(\xi^L_{i-\ha,i-2} +\xi^R_{i-\ha,i-2} \) 
    \\ \nonumber
    + \, &\eta_{i-1}^{n+1} \, \frac{\dt^2}{\dx}g\( \xi^L_{i-\ha,i-1} + \xi^R_{i-\ha,i-1} - \xi^L_{i+\ha,i-1} - \xi^R_{i+\ha,i-1} \)  
    \\ \nonumber
    +\, &\eta_{i}^{n+1} \, \bigg( 1+ \frac{\dt^2}{\dx}g\( \xi^L_{i-\ha,i} + \xi^R_{i-\ha,i} - \xi^L_{i+\ha,i} - \xi^R_{i+\ha,i} \)  \bigg)
    \\ \nonumber
    + \, &\eta_{i+1}^{n+1} \, \frac{\dt^2}{\dx}g\( \xi^L_{i-\ha,i+1} + \xi^R_{i-\ha,i+1} - \xi^L_{i+\ha,i+1} - \xi^R_{i+\ha,i+1} \) 
    \\
    \label{elliptic_eta}
    + \, & \eta_{i+2}^{n+1} \, \frac{\dt^2}{\dx}g\(-\xi^L_{i+\ha,i+2} -\xi^R_{i+\ha,i+2} \) = \eta_i^*
\end{align}
where $\eta_{i}^*$ collects the explicit contributions
\begin{equation}
\label{eq:etaStar}
\eta_{i}^* = \eta_{i}^n - \frac{\dt}{\dx}\(q^{*}_{i+\ha} - q^*_{i-\ha}\). 	
\end{equation} 
Once $\eta_{i}^{n+1}$, $i=1,\dots,N$ has been computed, then $q_{i+1/2}^{n+1}$, $ i=0,\dots,N$, follows from equation \eqref{q_new}.

\subsubsection{Convective term computation} \label{Aux_h}
In this subsection, we detail how the convective term $\F_i^n$ in \eqref{q_1} is computed. First, the fact of using the staggered discretization makes it necessary to interpolate the height values at the interfaces $h_{i+1/2}$. To this aim, we consider a third-order upwind interpolation from $h_i$ as follows. We construct the quadratic polynomials $P_{i+1/2}^L$,$P_{i+1/2}^R$ such that
$$\dfrac{1}{\Delta x} \displaystyle \int_{I_j} P^L_{i+1/2}(x)=h_{j}, \quad 
j=i-1,i,i+1; \qquad \dfrac{1}{\Delta x} \displaystyle \int_{I_k} P^R_{i+1/2}(x)=h_{k}, \quad k=i,i+1,i+2.
$$
Now, the interpolated height $h_{i+1/2}$ is defined as the upwind value, i.e.,
\begin{equation*}
	h_{i+\ha} = \begin{cases}
		P_{i+\ha}^L(x_{i+\ha}) \quad {\rm if }\; q_{i+\ha}\ge0  ,     \\
		P_{i+\ha}^R(x_{i+\ha}) \quad {\rm if }\; q_{i+\ha}<0   .     
	\end{cases}
\end{equation*}
where
\begin{align*}
	P_{i+\ha}^L(x_{i+\ha}) &= h_{i-1} + \frac{3}{2}\(h_{i} - h_{i-1}\) + \frac{3}{8}\(h_{i+1} - 2h_{i} + h_{i-1} \), \\    
	P_{i+\ha}^R(x_{i+\ha}) &= h_{i} + \frac{1}{2}\(h_{i+1} - h_{i}\) - \frac{1}{8}\(h_{i+2} - 2h_{i+1} + h_{i} \).
\end{align*}

Once we have $h_{i+1/2},q_{i+1/2}$,  the term $\F_i^n$ is computed using the Rusanov flux, as
%\begin{equation}
%	\label{rusanov}
%	\F_i = \F\Bigl(U_{i}^{-};U_i^{+}\Bigr) = \frac{1}{2}\left( f(U_{i}^+) + f(U_i^-) \,-\, \alpha_i(U_i^+ - U_i^-)\right),
%\end{equation}
\begin{equation}
	\label{rusanov}
	\F_i = \F\Bigl(h_i^-,q_i^-,h_i^+,q_i^+\Bigr) = \frac{1}{2}\left( f(h_i^+,q_i^+) + f(h_i^-,q_i^-) \,-\, \alpha_i(q_i^+ - q_i^-)\right),\qquad i=1,...,N,
\end{equation}
where
\[
    f(h,q) \equiv \frac{q^2}{h}
\]
and  $h_{i}^{\pm},q_{i}^{\pm}$ are the reconstructed values from $h_{i+1/2},q_{i+1/2}$ by the usual third-order CWENO procedure \cite{levy1999central}, recalled in Appendix \ref{App_B},  and $\alpha_i=\max\{|u_{i}^-|,|u_{i}^+|\}$ an approximation of the maximum wave speed.

