with
\begin{equation}
    \label{ode_form_part}
    \widetilde{H}(U_E,U_I) = 
    \begin{bmatrix}
       0   & -D^1_x(q_I) \\ - D^3_x(q_E \, u_E) &  -gh_E D^2_x(\eta_I) 
    \end{bmatrix},
\end{equation}
where $D_x^k$ denote suitable discrete approximation of $\partial_x$. In our case, $D_{x}^1(q_I)$ is defined at each control volume $I_i$;  $(h_ED_x^2(\eta_I))$ and $D^3_x((qu)_E)$ are defined at each dual control volume $I_{i+1/2}$. Concretely, they are:
\label{page:D}
\begin{itemize}
  	\item $D_{x}^1(q_I) = \dfrac{q_{i+\ha} - q_{i-\ha}}{\dx}$, since $q_{i\pm\ha}$ are suitably defined on cell edges in terms of $q_I$. 
   	\item According to \eqref{q_new}, we have    		
   	\begin{multline*}
    		(h_ED_x^2(\eta_I)){i+\frac12} = (\xi_{i+\frac{1}{2},i-1}^L+\xi_{i+\frac{1}{2},i-1}^R ) \eta_{i-1} + (\xi_{i+\frac{1}{2},i}^L +\xi_{i+\frac{1}{2},i}^R)\eta_{i}  \\
    		+ (\xi_{i+\frac{1}{2},i+1}^L +\xi_{i+\frac{1}{2},i+1}^R)\eta_{i+1} + (\xi_{i+\frac{1}{2},i+2}^L +\xi_{i+\frac{1}{2},i+2}^R)\eta_{i+2},
   	\end{multline*} 
   	with coefficients $\xi$, defined by (\ref{eq:defxiL}) and (\ref{eq:defxiR}), in terms of the explicit variables $h_E$, and $\eta$ values in terms of the implicit variables $\eta_I$.
   	\item $D^3_x(q_E \, u_E)= \dfrac{\mathcal{F}_{i+1}-\mathcal{F}_{i}}{\dx}$, where $\mathcal{F}_{i}$ is the Rusanov flux defined by \eqref{rusanov} in terms of $U_E$. 
\end{itemize}  

With this notation, the semi-discrete in time first order semi-implicit scheme can be written as:
    \begin{equation}
    	\begin{cases}
    		\label{First order}
    		\eta^{n+1} = \eta^n - \dt D_x^1(q^{n+1}),\\
    		q^{n+1} = q^n - \dt D_x^3(q^nu^n) - \dt gh^nD_x^2(\eta^{n+1}).
    	\end{cases}
    \end{equation}

Then, in practice, the fully-discrete first order of the semi-implicit scheme for the SW equations can be written as follows:
\begin{align}
    \label{eta_1-3} & \eta_i^{n+1} = \eta_i^{n}  - \frac{\Delta t}{\Delta x}\Bigl(q_{i+\frac{1}{2}}^{n+1} - q_{i-\frac{1}{2}}^{n+1}\Bigr), \\
    \label{q_1-3} & q_{i+\frac{1}{2}}^{n+1} = q_{i+\frac{1}{2}}^{n} - \frac{\Delta t}{\Delta x}\Bigl(\mathcal{F}_{i+1}^{n}-\mathcal{F}_{i}^{n}\Bigr) -\Delta t g\Bigg((\xi_{i+\frac{1}{2},i-1}^{L,n}+\xi_{i+\frac{1}{2},i-1}^{R,n} ) \eta_{i-1}^{n+1} + (\xi_{i+\frac{1}{2},i}^{L,n} +\xi_{i+\frac{1}{2},i}^{R,n})\eta_{i}^{n+1} \nonumber \\  
	& \qquad + (\xi_{i+\frac{1}{2},i+1}^{L,n} +\xi_{i+\frac{1}{2},i+1}^{R,n})\eta_{i+1}^{n+1} + (\xi_{i+\frac{1}{2},i+2}^{L,n} +\xi_{i+\frac{1}{2},i+2}^{R,n})\eta_{i+2}^{n+1}   \Bigg).
\end{align}

With this in mind, we apply an IMEX (Implicit-Explicit) scheme to system \eqref{ode_form_semi}. Here we consider the IMEX SSP3(4,3,3) scheme defined by the double Butcher table \ref{tableau} (see \cite{PareschiRusso,Boscarino-Filbet}). Applying this method to the system, we find $U^{n+1}$ following Algorithm \ref{al:imex}. Notice that only steps 2, 4, 6 and 8 in this algorithm involve solving a five-diagonal linear system, while the rest of steps consist of collecting terms.\\

