Infine, mi pare che manchino i termini con $a^I_{\ell,j}$ con $j<\ell$ nelle ultime due righe della (C.4). Per il resto mi sembra che vada bene. Stesso discorso sulle sommatorie vale per la soluzione numerica. }
\end{comment}
\begin{align}
    \label{l-stages}
    & \eta_{E,i}^{(\ell)} = \eta_i^n \\
    & q_{E,i+\ha}^{(\ell)} = q_{i+\ha}^n -  \frac{\dt}{\dx}\sum_{j=1}^{\ell-1}a_{\ell,j}^E\Bigl(\F_{i+1}(U_E^{(j)}) - \F_{i}(U_E^{(j)})\Bigr) \\
    & \eta_{I,i}^{(\ell)} = \eta_i^n -  \frac{\dt}{\dx}\sum_{j=1}^\ell a_{\ell,j}^I\Bigl(q_{I,i+\ha}^{(j)} - q_{I,i-\ha}^{(j)}\Bigr) \\ 
    & q_{I,i+\ha}^{(\ell)} = q_{i+\ha}^n - \frac{\dt}{\dx}\sum_{j=1}^{\ell-1}a_{\ell,j}^I\Bigl(\F_{i+1}(U_E^{(j)}) - \F_{i}(U_E^{(j)})\Bigr) +  \\
    & \quad \qquad - g\dt\sum_{j=1}^\ell a_{\ell,j}^I \Bigl[ \Bigl(\xi_{E,i+\ha,i-1}^{L,(j)} - \xi_{E,i+\ha,i-1}^{R,(j)}\Bigr)\eta_{I,i-1}^{(j)} + \Bigl(\xi_{E,i+\ha,i}^{L,(j)} - \xi_{E,i+\ha,i}^{R,(j)}\Bigr)\eta_{I,i}^{(j)}  + \nonumber \\ 
    & \quad\qquad \qquad\qquad+ \Bigl(\xi_{E,i+\ha,i+1}^{L,(j)} - \xi_{E,i+\ha,i+1}^{R,(j)}\Bigr)\eta_{I,i+1}^{(j)} + \Bigl(\xi_{E,i+\ha,i+2}^{L,(j)} - \xi_{E,i+\ha,i+2}^{R,(j)}\Bigr)\eta_{I,i+2}^{(j)} \Bigr]\nonumber
\end{align}
for $\ell = 1,\ldots,s$, where $s$ is the total number of stages in the tableau. The subscript $_E$ in the $\xi$-coefficients denotes the explicit reconstruction of $h$, distinguishing it from the implicit discretization of $\partial_x\eta\,$.

Finally, the numerical solution is:
\begin{align}    
    & \eta^{n+1}_i = \eta_i^n - \frac{\dt}{\dx}\sum_{\ell = 1}^s b_\ell\Bigl(q_{I,i+\ha}^{(\ell)} - q_{I,i+\ha}^{(\ell)}\Bigr)  \\ 
    & q^{n+1}_{i+\ha} = q_{i+\ha}^n - \frac{\dt}{\dx}\sum_{\ell = 1}^s b_\ell\Bigl(\F_{i+1}(U_E^{(\ell)}) - \F_{i}(U_E^{(\ell)})\Bigr) + \label{num_sol_imex}\\
    & \quad\quad\; - g\dt\sum_{\ell = 1}^s b_\ell\Bigl[\Bigl(\xi_{E,i+\ha,i-1}^{L,(\ell)} - \xi_{E,i+\ha,i-1}^{R,(\ell)}\Bigr)\eta_{I,i-1}^{(\ell)} + \Bigl(\xi_{E,i+\ha,i}^{L,(\ell)} - \xi_{E,i+\ha,i}^{R,(\ell)}\Bigr)\eta_{I,i}^{(\ell)} \Bigr.  + \nonumber \\ 
    & \quad\qquad\qquad\qquad\quad + \Bigl.\Bigl(\xi_{E,i+\ha,i+1}^{L,(\ell)} - \xi_{E,i+\ha,i+1}^{R,(\ell)}\Bigr)\eta_{I,i+1}^{(\ell)} + \Bigl(\xi_{E,i+\ha,i+2}^{L,(\ell)} - \xi_{E,i+\ha,i+2}^{R,(\ell)}\Bigr)\eta_{I,i+2}^{(\ell)} \Bigr] \nonumber
\end{align}









