def dwave_exec(self, verbose=0):
    Hamiltonian, T = ...
    self.qs.add_evolution(Hamiltonian, T) # Hamiltonian embedding

    dwp = DWaveProvider(self.api_key) # initiate D-Wave machine
    ...
    dwp.compile(self.qs, self.shots)
    ...
    dwp.run()
    ... 

    self.raw_result = dwp.results()
    raw_samples = []
    for i in range(self.shots):
        raw_samples.append(QHD.spin_to_bitstring(self.raw_result[i]))

    return raw_samples
    \end{pythonnum}
