 \section{G-wavelets}\label{ap:wavelet}
In this section we are going to design wavelets on finite groups. We will start by recalling some notations, and refer to \cite[Chapt. 15]{terras_1999} for the basic results of Fourier analysis on finite groups needed in this section.

Let $G$ be a finite group with identity $\mathbf{1}$. For $x\in G$, its conjugacy class is $[x] = \{yxy^{-1} | y \in G\}$.


A representation of $G$ is an homomorphism $\pi: G \to GL(\mathcal{H}_\pi)$, where $\mathcal{H}_\pi$ is a vector space over $\CC$ of dimension $d_\pi$. The number $d_\pi$ is called the degree of the representation $\pi$. Note that from $\pi(xy)=\pi(x)\pi(y)$ for all $x,y \in G$, one can deduce $\pi(\mathbf{1})=I_{d_\pi}$, where $I_{d_\pi}$ is the $d_\pi$-dimensional identity matrix, and $\pi(x^{-1})=\pi(x)^{-1}$ for all $x\in G$ .
The character $\chi^{\pi}$ of a representation $\pi$ of a finite group $G$ is defined by $\chi^{\pi}(x)=Tr(\pi(x))$ for all $x\in G$. The characters are complex-valued functions defined on $G$ which are constant on conjugacy classes. Indeed, let $x \in G$, let $z \in [x]$, and let $y\in G$ be such that $z=yxy^{-1}$. Then
\begin{equation}\label{eugenio:1}
 \chi^\pi(z) = Tr(\pi(yxy^{-1})) = Tr(\pi(y) \pi(x) \pi(y^{-1})) = Tr(\pi(x)) = \chi^\pi(x).
\end{equation}

Complex valued functions with this property are called class functions (see e.g. \cite[Definition on p. 258]{terras_1999}). Precisely, $f:G\to \CC$ is a class function if for all $x,y \in G$,

\begin{equation}\label{eugenio:2}
f(yxy^{-1})=f(x).
\end{equation}
A representation $\pi$ of $G$ is unitary if $\pi(x)$ is a unitary matrix for all $x\in G$.

A representation $\pi$ of $G$ is irreducible if for all $x\in G$, the linear operator $\pi(x): \mathcal{H}_\pi \to \mathcal{H}_\pi$ does not have invariant subspaces other than the trivial ones. Two representations $\pi_1$ and $\pi_2$ of $G$ are said to be equivalent if there exits an invertible square matrix $T$ such that $\pi_1(x)=T^{-1}\pi_2(x)T$ for all $x\in G$.

\begin{definition}
For a finite group $G$, the dual $\widehat{G}$ is the set of irreducible unitary representations of $G$ up to unitary equivalence.
\end{definition}

It is known (see e.g. \cite[Chapt. 15, Theorem 3]{terras_1999}) that the number of elements of $\widehat{G}$ coincides with the number of conjugacy classes of $G$. Let us denote by $k$ this number, let us choose a system of inequivalent unitary irreducible representation so that we can identify $\widehat{G}=\{\pi^1, \ldots, \pi^k\}$, and for each $i=1,2, \ldots, k$, write $\chi^i$ for the character of $\pi^i.$ Denote by $\Cl_1, \ldots, \Cl_k$ the conjugacy classes of $G$, where $\Cl_1=[\mathbf{1}]=\{\mathbf{1}\}$. By \eqref{eugenio:1}, each $\chi^i$ is constant in each class $\Cl_r$, $1\leq r \leq k$, and we denote by $\chi^i_r$ the value of $\chi^i$ in the conjugacy class $\Cl_r$. The square matrix of size $k\times k$ formed with the elements $\chi^i_r$ is called the character table of $G$. Observe that if $d_i$ is the degree of $\pi^i \in \widehat{G}$, then $d_i=\chi^i_{1}$. There exist algorithms to calculate the character table of finite groups (see \cite{grove_1997}(Chapter 7), \cite{Burnside1911}, \cite{dixon_1967}, \cite{dixon_1970} and \cite{schneider_1990}).


A relevant unitary representation of $G$ is the left regular representation $L$. It is defined on the Hilbert space $L^2(G) = \{f:G \to \CC\}$, which is considered to be endowed with the inner product
\begin{equation}\label{eq:scalarprod}
    \langle f, g \rangle = \frac{1}{|G|} \sum_{x\in G} f(x)\overline{g(x)}, \quad f,g\in L^2(G),
\end{equation}
and the induced norm $\|f\|=(\langle f, f \rangle)^{1/2}$, by
$$
L(h)f(x) = f(h^{-1}x) \, ,  \quad \textnormal{for } f \in L^2(G) \textnormal{ and } x,h \in G.
$$
Recall that $L$ is equivalent to the direct sum of irreducibles (see e.g. \cite[Chapt. 15, Lemma 2]{terras_1999})
\begin{equation}\label{eq:directsum}
L(x) \approx \bigoplus_{r = 1}^k d_r \pi^r(x) \quad \forall \, x \in G
\end{equation}
where $d_r \pi^r$ indicates the direct product of $d_r$ copies of the representation $\pi^r$.

The convolution of $f, g \in L^2(G)$ is defined as
\begin{equation}\label{def:convolution}
f*g(x) =\frac{1}{|G|}\sum_{y\in G} f(y) L(y) g(x) = \frac{1}{|G|}\sum_{y\in G} f(y)g(y^{-1}x) = \frac{1}{|G|} \sum_{z\in G} f(xz^{-1})g(z), \quad f,g\in L^2(G).
\end{equation}

The convolution is in general noncommutative. But if $f\in L^2(G)$ is a class function (see \eqref{eugenio:2}) then, for all $g \in L^2(G)$ and all $x \in G$
\begin{equation}\label{eugenio:5}
    f*g(x) = \frac{1}{|G|} \sum_{z\in G} f(xz^{-1})g(z) = \frac{1}{|G|}\sum_{z\in G} g(z)f(x(z^{-1}x)x^{-1}) = \frac{1}{|G|}\sum_{z\in G} g(z)f(z^{-1}x) = g*f(x).
\end{equation}

The Fourier transform of $f\in L^2(G)$ is defined as the matrix valued function (see Chapters 3 and 5 of \cite{folland_1995} and Chapter 15 of \cite{terras_1999})
\[
\widehat{f}(\pi^r)=\frac{1}{|G|}\sum_{x\in G} f(x) \pi^r(x^{-1}), \quad \pi^r\in\widehat{G}.
\]
It factorizes convolutions in the following way: for $f, g \in L^2(G)$, it is easy to see that
\begin{equation}\label{eq:fourierfactor}
\widehat{f\ast g}(\pi^r) = \widehat{g}(\pi^r) \widehat{f}(\pi^r).
\end{equation}
Moreover, for finite groups one can write Plancherel's theorem as (see \cite[Chapt. 15, Theorem 2]{terras_1999}, but observe that here we are considering the normalized scalar product)
\begin{equation}\label{eq:Plancherel}
\|f\|^2_{L^2(G)} = \sum_{r = 1}^k\sum_{i,j=1}^{d_r} d_r \left|\left\langle f, \pi^r_{ij}\right\rangle\right|^{2} = \sum_{r = 1}^k\sum_{i,j=1}^{d_r} d_r \left|\widehat{f}(\pi^r)_{ij}\right|^{2}
\end{equation}
for any $f \in L^2(G)$, where $\pi^r_{ij} : G \to \CC$ is the $ij$-th element of the representation $\pi^r$.

\subsection{G-Wavelet transform} \label{G-wavelet transform}

The definition of the $G$-wavelets is inspired by the idea of \cite{hammond} (see Section \ref{conection}).
\begin{definition} \label{Def2-2}
Given a measure space $(\Omega,\mu)$, we call \emph{kernel} a family of functions $\gamma = \{\gamma_\omega: \{1,\ldots,k\} \to \CC\}_{\omega \in \Omega}$. The \textit{$G$-wavelet} associated to the kernel $\gamma_\omega$ is
\begin{equation}\label{def:2.1}
\psi_{\gamma_\omega}(x):=\sum_{r=1}^k d_r \gamma_\omega(r)\chi^r(x), \quad x\in G.
\end{equation} 
\end{definition}

Assume that for $\omega\in \Omega$, we have $\displaystyle B_\omega := \max_{1\leq r \leq k} |\gamma_\omega(r)| < \infty$. Then $\psi_{\gamma_\omega}
\in L^\infty(G)$. Indeed, since the trace of a unitary matrix is less than or equal to the dimension of the matrix,
\begin{equation} \label{eq:infinity}
	\|\psi_{\gamma_\omega}\|_\infty = \max_{x\in G} |\psi_{\gamma_\omega}(x)| \leq \sup_{x\in G} \sum_{r=1}^k d_r |\gamma_\omega(r)| |\chi^r(x)| \leq B_\omega \sum_{r=1}^k d_r^2 = B_\omega |G| < \infty\,, 
\end{equation}
where the have used that $\displaystyle \sum_{r=1}^k d_r^2 = |G|$ (see \cite[Chapt. 15, Lemma 2]{terras_1999}).

The $G$-wavelets given in \eqref{def:2.1} are class functions. This can be seen directly, using the property of the trace:
\begin{align*}
\psi_{\gamma_\omega}(h^{-1} x h) & = \sum_{r=1}^k d_r \gamma_\omega(r)\chi^r(h^{-1}x h) = \sum_{r=1}^k d_r \gamma_\omega(r) Tr(\pi^r(h^{-1})\pi^r(x)\pi^r(h))\\
& = \sum_{r=1}^k d_r \gamma_\omega(r) Tr(\pi^r(x)) = \sum_{r=1}^k d_r \gamma_\omega(r)\chi^r(x).
\end{align*}
We also have that the Fourier transform of a $G$-wavelet is a multiple, given by the defining kernel, of the identity operator on $L^2(G)$:
\begin{equation}\label{eq:FourierGwavelet}
\widehat{\psi_{\gamma_\omega}}(\pi^r) = \gamma_\omega(r) I_{d_r}.
\end{equation}
This can be obtained by direct computation of the matrix elements starting from \eqref{def:2.1}:
\begin{align*}
\widehat{\psi_{\gamma_\omega}}(\pi^r)_{i,j} & = \frac{1}{|G|}\sum_{x\in G}  \sum_{s=1}^k d_s \gamma_\omega(s)\chi^s(x) \pi^r(x^{-1})_{i,j}
= \frac{1}{|G|}  \sum_{s=1}^k d_s \gamma_\omega(s) \sum_{x\in G} Tr(\pi^s(x)) \pi^r(x^{-1})_{i,j}\\
& = \frac{1}{|G|}  \sum_{s=1}^k d_s \gamma_\omega(s) \sum_{l = 1}^{d_s} \sum_{x\in G} \pi^s(x)_{l,l} \pi^r(x^{-1})_{i,j} = \gamma_\omega(r) \delta_{i,j}
\end{align*}
where the last identity is Schur's orthogonality theorem (see e.g. \cite[Chapt. 15, Theorem 1]{terras_1999}).

We define the $G$-wavelet transform in terms of the left translates of a $G$-wavelet, as follows.
\begin{definition} \label{Wavelet-transform}
Given a kernel $\gamma$, we define the \textit{$G$-wavelet  transform} of $f\in L^2(G)$ by 
	\[
	W_{\gamma}f(\omega,h) :=  f\ast \psi_{\gamma_\omega}(h) = \frac{1}{|G|} \sum_{x \in G} f(x) \psi_{\gamma_\omega}(x^{-1}h), \quad \omega \in \Omega, h\in G.
	\]
\end{definition}

Since the wavelets are class functions, by \eqref{eugenio:5} we can write \begin{equation}\label{eq:Wconv}
		W_{\gamma}f(\omega,h) = f \ast \psi_{\gamma_\omega} (h) = \psi_{\gamma_\omega}  \ast f (h).
	\end{equation}


Assume that for $\omega\in \Omega$, we have $\displaystyle B_\omega := \max_{1\leq r \leq k} |\gamma_\omega(r)| < \infty$. By \eqref{eq:infinity} and the fact that $G$ is finite,
$\psi_{\gamma_\omega}\in L^\infty(G) \subset \ L^1(G).$ Hence, by Young's inequality and \eqref{eq:Wconv} we conclude that $W_{\gamma}f(\omega,\cdot)\in L^2(G).$

Moreover, using \eqref{eq:fourierfactor}, we have that 
	\[
	\widehat{W_{\gamma}f}(\omega,\cdot)(\pi^r) = \widehat{f}(\pi^r) \widehat{\psi_{\gamma_\omega}}(\pi^r).
	\]
	Using \eqref{eq:FourierGwavelet}, we immediately obtain the following result.
\begin{lemma}\label{lem:FourierW}
	Given a kernel $\gamma$ as in Definition \ref{Def2-2}, the \textit{$G$-wavelet transform} of $f\in L^2(G)$ satisfies
	\[
	\widehat{W_{\gamma}f}(\omega,\cdot)(\pi^r) = \gamma_\omega(r) \, \widehat{f}(\pi^r).
	\]
\end{lemma}

