\subsection{Properties} \label{Properties}
Let us first show that, if a Calder\'on type condition holds, we have a reconstruction formula for the introduced $G$-wavelet transform, analogous to that for the continuous wavelet transform.

In the sequel, for $f\in L^2(G)$ we write $f^\dagger(x) = \overline{f(x^{-1})}$ for the natural involution in $L^2(G)$. As in \eqref{eq:FourierGwavelet}, it can be proved that
	\begin{equation}\label{eq:FourierGwavelet-dagger}
		\widehat{\psi_{\gamma_\omega}^\dagger}(\pi^r) = \overline{\gamma_\omega(r)} I_{d_r}.
	\end{equation}

\begin{theorem}[Inverse formula]
If the kernel $\gamma = \{\gamma_\omega:\{1,\ldots, k\} \to \CC\}_{\omega\in \Omega}$ satisfies the condition
\begin{equation}\label{calderon}
\int_\Omega |\gamma_\omega(r)|^2 d\mu(\omega) = 1 \quad \forall \ r\in\{1,\ldots, k\},
\end{equation}
then for all $f\in L^2(G)$
\begin{equation}
f(x) = \frac{1}{|G|}\sum_{h\in G}\int_\Omega W_{\gamma}f(\omega,h)\, L(h)\psi_{\gamma_\omega}^\dagger(x) \, d\mu(\omega),
\end{equation}
for every $x\in G$.
\end{theorem}


\begin{proof}
By Definition \ref{Wavelet-transform} we can write
\begin{align*}
	\frac{1}{|G|}\sum_{h\in G}\int_\Omega W_{\gamma_\omega} f(h) \, L(h)\psi_{\gamma_\omega}^\dagger(x) \, d\mu(\omega) & = \frac{1}{|G|}\sum_{h\in G}\int_\Omega f\ast\psi_{\gamma_\omega}(h) \psi_{\gamma_\omega}^\dag (h^{-1}x)d\mu(\omega)\\
	& =\int_\Omega f\ast\psi_{\gamma_\omega}\ast\psi_{\gamma_\omega}^\dag(x)d\mu(\omega).
\end{align*}

By \eqref{eq:fourierfactor} and \eqref{eq:FourierGwavelet-dagger} we have that $\widehat{\psi_{\gamma_\omega}\ast\psi_{\gamma_\omega}^\dag}(\pi^r) = |\gamma_\omega(r)|^2 I_{d_r}$, so that, by the same argument leading from \eqref{def:2.1} to \eqref{eq:FourierGwavelet}, the second convolution reads
\[
\psi_{\gamma_\omega}\ast\psi_{\gamma_\omega}^\dag(x) = \sum_{r=1}^kd_r |\gamma_\omega(r)|^2 \chi^r(x) .
\]
Thus, using Calder\'on's condition \eqref{calderon}, and recalling \eqref{eq:directsum}, we get
\begin{align*}
\int_\Omega f\ast\psi_{\gamma_\omega}\ast\psi_{\gamma_\omega}^\dag(x)d\mu(\omega) & = \sum_{r=1}^k d_r \int_\Omega |\gamma_\omega(r)|^2d\mu(\omega) f*  \chi^r(x) = f \ast \left(\sum_{r=1}^k d_r \chi^r \right)(x)\\
& = f \ast Tr\left(\sum_{r=1}^k d_r \pi^r \right)(x) = f \ast Tr (L) (x) = f(x)
\end{align*}
where the last identity is due to the fact that the trace of the left regular representation is $|G|$ when computed in the identity, and zero otherwise.
\end{proof}

For any practical computation, $\Omega$ must be a finite number of scales $\Omega = \{0,\dots,J\}$. The natural question is how appropriated the $G$-wavelet set $\{\psi_{\gamma_j}| 0 \leq j \leq J\}$ will be for representing functions on the group. This question can be addressed by characterizing when the system of translates is a frame of $L^2(G)$, which is the content of the next theorem.
%\begin{theorem}\label{teo:2.3}
%Let $\{\gamma_j:\{1,\ldots, k\} \to \CC\}_{0 \leq j \leq J}$ and let
%\begin{align*}
%    A& = \min_{r \in \{1,\ldots,k\}}\left\{\sum_{j=0}^{J}  |\gamma_j(r)|^2 \right \} ,\\
%    B& = \max_{r \in \{1,\ldots,k\}}\left\{\sum_{j=0}^{J}  |\gamma_j(r)|^2 \right \}.
%\end{align*}
%If $A > 0$, the set $\{L(h)\psi_{\gamma_j} \,|\, 0\leq j \leq J, h\in G\}$ is a frame of $L^2(G)$ with constants $0<A\leq B < \infty$, i.e.
%\begin{equation}\label{eq:14}
%A\|f\|^2\leq \frac{1}{|G|}\sum_{h\in G} \sum_{j=0}^{J} |\langle f, L(h)\psi_{\gamma_j} \rangle|^2\leq B\|f\|^2 \quad \forall \  f\in L^2(G).
%\end{equation}
%
%\end{theorem}
\begin{theorem}\label{teo:2.3}
Let $\{\gamma_j:\{1,\ldots, k\} \to \CC\}_{0 \leq j \leq J}$ and denote by
\[
\mathscr{C}(r) = \sum_{j=0}^{J}  |\gamma_j(r)|^2 \, , \ r \in \{1,\dots,k\}.
\]
The following are equivalent
\begin{itemize}
\item[i)] The set $\{L(h)\psi_{\gamma_j} \,|\, 0\leq j \leq J, h\in G\}$ is a frame of $L^2(G)$ with constants $0<A\leq B < \infty$, i.e.
\begin{equation}\label{eq:14}
A\|f\|^2\leq \frac{1}{|G|}\sum_{h\in G} \sum_{j=0}^{J} |\langle f, L(h)\psi_{\gamma_j} \rangle|^2\leq B\|f\|^2 \quad \forall \  f\in L^2(G).
\end{equation}
\item[ii)] There exist two constants $0 < A \leq B < \infty$ such that
\begin{equation}\label{eq:Calderon}
A \leq \mathscr{C}(r) \leq B \quad \forall \ r  \in \{1,\dots,k\}.
\end{equation}
\end{itemize}
\end{theorem}
\begin{proof}
For all $h\in G$ and all $j\in\{0,1, \dots, J\}$ we have
\[
\langle f, L(h)\psi_{\gamma_j}\rangle = \frac{1}{|G|}\sum_{x\in G}  f(x) \overline{\psi_{\gamma_j}(h^{-1}x)} = \frac{1}{|G|}\sum_{x\in G}  f(x) \psi_{\gamma_j}^\dag(x^{-1}h) = f\ast \psi_{\gamma_j}^\dag(h)\,.
\]
By \eqref{eq:fourierfactor} and \eqref{eq:FourierGwavelet-dagger}, for any $\pi^r\in \widehat G$,
\[
\widehat {f\ast \psi_{\gamma_j}^\dag}(\pi^r) = \overline{\gamma_j(r)} \widehat f(\pi^r)\,.
\]

By Plancherel's identity \eqref{eq:Plancherel}, for all $j \in \{0,\dots,J\}$ we have
\[
\frac{1}{|G|}\sum_{h\in G} |\langle f, L(h)\psi_{\gamma_j}\rangle|^2 = \|f\ast \psi_{\gamma_j}^\dag\|_{L^2(G)}^2 = \sum_{r=1}^k\sum_{m,n=1}^{d_r}d_r |\gamma_j(r)|^2 |\widehat{f}(\pi^r)_{nm}|^2.
\]
Then
\begin{equation}\label{eq:CalderonFourier}
\frac{1}{|G|}\sum_{h\in G} \sum_{j=0}^{J} |\langle f, L(h)\psi_{\gamma_j}\rangle|^2
= \sum_{r=1}^k \left(  \sum_{j=0}^{J}  |\gamma_j(r)|^2\right)d_r \sum_{m,n=1}^{d_r} |\widehat{f}(\pi^r)_{nm}|^2 .
\end{equation}
We can now complete the proof by recalling that  Plancherel's identity \eqref{eq:Plancherel} reads
\begin{equation*}
\sum_{r=1}^k\sum_{m,n=1}^{d_r}d_r|(\widehat{f}(\pi^r))_{nm}|^2=\|f\|^2.
\end{equation*}
Indeed, if \eqref{eq:Calderon} holds, then one immediately obtains the frame condition \eqref{eq:14}. On the other hand, suppose that \eqref{eq:14} holds and suppose, by contradiction, that \eqref{eq:Calderon} is not true because $\mathscr{C}(r_0) < A$ for one $r_0 \in \{1, \dots, k\}$. Then, if we choose $f_0 \in L^2(G)$ to be such that $\widehat{f_0}(\pi^r) = \delta_{r,r_0}M$ for a nonzero $d_{r_0} \times d_{r_0}$ matrix $M$, we get that \eqref{eq:CalderonFourier} reads
\[
\frac{1}{|G|}\sum_{h\in G} |\langle f, L(h)\psi_{\gamma_j}\rangle|^2 = d_{r_0} \mathscr{C}(r_0) \sum_{m,n=1}^{d_r} |\widehat{f}(\pi^r)_{nm}|^2 < A d_{r_0} \sum_{m,n=1}^{d_r} |\widehat{f}(\pi^r)_{nm}|^2 = A \|f\|^2
\]
which contradicts \eqref{eq:14}. The other inequality can be treated similarly.
\end{proof}

\begin{remark}\label{remark2.7}
	The same result as in Theorem \ref{teo:2.3} holds if we consider the set $\{L(h)\psi_{\gamma_j}^\dag \,|\, 0\leq j \leq J, h\in G\}.$ In fact, 
	$
	\langle f, L(h)\psi_{\gamma_j}^\dag\rangle  = f\ast \psi_{\gamma_j}(h)\,.
	$
	and by \eqref{eq:fourierfactor} and \eqref{eq:FourierGwavelet}, for any $\pi^r\in \widehat G$,
	$
	\widehat {f\ast \psi_{\gamma_j}}(\pi^r) = \gamma_j(r) \widehat f(\pi^r)\,
	$
	so that the above proof goes unchanged to obtain
	$$
	A\|f\|^2\leq \frac{1}{|G|}\sum_{h\in G} \sum_{j=0}^{J} |\langle f, L(h)\psi_{\gamma_j}^\dag \rangle|^2 = \sum_{j=0}^J \|\psi_{\gamma_j}\ast f\|^2 \leq B\|f\|^2 \quad \forall \  f\in L^2(G).
	$$
\end{remark}

\subsection{Connection with Hammond et al. Wavelets}\label{conection}

In \cite{hammond} D.K. Hammond, P. Vandergheynst, and R. Givonval define and study wavelets on weighted connected finite graphs. Let $V$ be the set of vertices of the graph, denoted by $V=\{1,2, \dots N\}$, $E$  the set of edges of the graph and $w:E \to \mathbb R^+$ the weights. 

The adjacency matrix of the weighted graph is the $N\times N$ matrix $A=(a_{m,n})$ where 
\begin{equation*}
	a_{m,n}=\begin{cases}
		w(e), \text{ if } e\in E \ \text{connect vertices} \  m \  \text{and}\  n\\
		0, \text{ otherwise}.
	\end{cases}
\end{equation*}
For each vertex $m$ in $V$, denote by $d(m)$ the sum of the weights of all edges incident to $m$. Let $D$ be the matrix with diagonal entries $d(1), d(2), \dots, d(m)$, and 0 otherwise. The Laplacian of the weighted graph $\{V, E, w\}$ is the $N\times N$ matrix
\[
\mathcal L = D - A.
\]
The matrix $\mathcal L$ is real and symmetric. Therefore, it has a complete set of orthonormal eigenvectors, denoted by $\chi_\ell, \ell = 1, 2, \dots. N$, with associated eigenvalues $\lambda_l$, that is $\mathcal L \chi_\ell = \lambda_l \chi_\ell$. Moreover, $\lambda_1=0$ is an eigenvalue of multiplicity one and the remainder eigenvalues are all positive. (See \cite{hammond} for details.) 


For a kenel $g: \mathbb R^+ \to \mathbb R^+$ the \textit{spectral graph wavelets} with parameter $t\in \mathbb R^+$ and $n=1, 2, \dots, N$ are given in \cite{hammond} by
\begin{equation} \label{Eq:SGW}
	\psi_{t,n} (m) = \sum_{\ell=1}^N g(t\lambda_\ell) \chi_{\ell}(n) \chi_{\ell} (m)
\end{equation}


The purpose of this section is to show that if $G$ is a finite abelian group, the $G$-wavelets defined in \eqref{def:2.1} coincide with the spectral graph wavelets defined in \eqref{Eq:SGW} for appropriate kernels $\gamma_\omega$ and $g$. Observe that our results in Sections \eqref{G-wavelet transform} and \eqref{Properties} are valid for finite groups not necessarily abelian.

The connection between our wavelets and the spectral graph wavelets of  \cite{hammond} is provided by the Cayley graph of a group.


\begin{definition}
	Given a group $G$ and a symmetric set of generators $S$ of $G$ (meaning $S$ generates $G$ and $S$ is closed under taking inverses) , the Cayley graph $X =Cay(G, S)$ of $G$ is a graph whose vertices are the elements of $G$,  two elements $x$ and $y$ in $G$,
	are connected if there exists an element $s\in S$ such that
	$x = sy$ and all the weights of the edges are 1.
\end{definition}

For $G$ abelian group with $N$ elements, all unitary irreducible representations are unidimensional and they are equal to the characters of the group. We write
\[
\widehat G =\{ \chi^1, \chi^2, \dots, \chi^N \,. \}
\]


There is a connection between the characters of the abelian group and the eigenvalues and eigenvectors  of the Laplacian of the Cayley graph of the group, as the following theorem (due to Lovász \cite{Cayley}), shows.
\begin{theorem} Let $G$ be an abelian group of order $N$ with
	 characters $\chi^1, \chi^2, \ldots, \chi^N$. Let $S\subset G$ be a symmetric set of generators of $G$. Then the eigenvalues of the Laplacian of the  Cayley graph $X=Cay(G,S)$ of $G$ are given by
	\begin{equation}
		\lambda_i=|S|-\sum_{x\in S}\chi^i(x)
	\end{equation}
	Moreover, an eigenvector corresponding to $\lambda_i$ is $(\chi^i(x) : x \in G)^t$ (that is, the column vector whose $x$-entry is $\chi^i(x)$).
\end{theorem}

Given a kernel $g: \mathbb R^+ \to \mathbb R^+$, let $\gamma_t : \{1,2, \dots, N\} \to \mathbb R^+$ be given by $\gamma_t (\ell) = g(t\lambda_l)$ for $t\in \mathbb R^+.$ Then, for $x\in G$, equation \eqref{def:2.1} reads:
\begin{equation} \label{eq:connection}
	\psi_{\gamma_t}(x)=\sum_{\ell=1}^N g(t\lambda_\ell)\chi^l(x),
\end{equation}
which coincides with \eqref{Eq:SGW} when $n$ is the identity of the group. For any other $h\in G$, the wavelets
\[
\psi_{\gamma_t, h}(x) = \sum_{\ell=1}^N g(t\lambda_\ell) \chi^{\ell}(h) \chi^{\ell} (x)= \sum_{\ell=1}^N g(t\lambda_\ell) \chi^{\ell}(hx) = \psi_{\gamma_t}(hx)
\]
are all translations of the wavelet given by \eqref{eq:connection}.


\begin{example}
	Let $p$  be a prime number and let $G=(\ZZ_p^*, *)$ be the multiplicative group of integers mod ($p$) minus $0$. Let $x$ be a generator of $(\ZZ_p^*, *)$  and $\omega = e^{2\pi i /(p-1)}$. The character table of $G$ is
	$$
	\begin{array}{r|rrrrr} 
		 & 1 & x & x^2 & \cdots & x^{p-2} \\
		\hline \chi^0 & 1 & 1 & 1 &\cdots & 1 \\
		\hline \chi^1 & 1 & \omega & \omega^2 & \cdots & \omega^{p-2}\\
		\hline \chi^2 & 1 & \omega^2 & \omega^4 & \cdots & \omega^{p-3} \\
		\hline \vdots & \vdots & \vdots & \vdots & \cdots & \vdots\\
		\hline \chi^{p-2} & 1 & \omega^{p-2} & \omega^{p-3} & \cdots & \omega
	\end{array}
	$$
    The Cayley graph of $G$ with $S=\{x, x^{-1}\}$ is $C_{p-1}$, a cycle graph with $p-1$ vertexes. 
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.3\linewidth]{CayleyZp.png} \
        \caption{Representation of the Cayley graph of $(\ZZ_p^*, *)$}
        \label{fig:cayCp}
    \end{figure}
    The adjacency matrix of $C_{p-1}$ is
    \begin{equation*}
        \begin{pmatrix}
            0 & 1 & 0 & \ldots & 0 & 1\\
            1 & 0 & 1 & \ldots & 0 & 0\\
            0 & 1 & 0 & \ldots & 0 & 0\\
            \vdots&\vdots&\vdots& \ddots & \vdots&\vdots\\
            0 & 0 & 0 & \ldots & 0 & 1\\
            1 & 0 & 0 & \ldots & 1 & 0
            \end{pmatrix}
    \end{equation*}
    It is a circulant matrix and their eigenvectors are $(\chi^i(x) : x \in \ZZ_p^*)$. The wavelets associated to a kernel $\gamma_z: \{0,1, p-2\} \to \mathbb C, z\in \Omega$  are: 
\begin{equation}
    	\psi_{\gamma_z}(x^m)=\sum_{n=0}^{p-2} \gamma_z (n)\omega^{nm}.
    \end{equation}
\end{example}
