\begin{remark}
The scattering networks constructed in this section follows the original idea of S. Mallat in \cite{Mallat11} (see, also, Figure 1 in the Introduction). For this scattering transform to have good properties, the wavelets used must satisfy the equations that appear in Proposition 2.7 of \cite{Mallat11}.

The same idea is used by D. Zou and G. Lerman in \cite{zou} to construct scattering networks in weighted connected finite graphs. To prove good properties for their scattering transform, they use a scaling function $\phi$ and a wavelet $\psi$ that satisfy
	$$
	|\widehat{\phi}(2^J \omega)|^2 + \sum_{j>-J} |\widehat{\psi} (2^{-j}\omega)|^2 = 1\,, \quad \omega\in \mathbb R\,,
	$$
that can be achieved with the theory of Multiresolution Analysis (MRA).

While our $G$-scattering transform is also a cascade of modulus of convolutions, our wavelets are different from the ones in \cite{Mallat11} and \cite{zou}. In these works the scattering network depends only on the chosen wavelet and at each level $m\geq 1$ there are infinitely many paths selected from $\{(j_1, \dots, j_m): j_i \geq -J\}$. In our case, described above, our wavelets in \eqref{def:2.1} depend on $(J+1)k$ parameters $\{\gamma_j(r): 1\leq r\leq k\}_{0\leq j \leq J}$, where $k$ is the number of conjugacy classes of $G$, with the restriction \eqref{multir}. Therefore, G-wavelets are easy to construct and at each level $m\geq 1$ the number of features extracted is finite.
\end{remark}

Now we introduce a structural property of the scattering transform that will be needed in Chapter \ref{section b}, which states that, in the scattering networks, the propagated norm at the $m$-th layer splits into the propagated norm at the next layer plus the output energy at the current layer.

\begin{lemma}\label{lem:3.2.2}  Let $\{\gamma_j: \{1,\ldots, k\} \to  \CC\}_{0\leq j\leq J}$ be a kernel satisfying \eqref{multir}, and let $U[\cdot]$ and $S[\cdot]$ be the associated $G$-scattering propagator and the $G$-windowed scattering operator. Then for all $m \geq 0$
	\begin{equation}\label{eq:36}
		\sum_{p\in \Lambda_J^m}\|U[p]f\|^2 = \sum_{p\in \Lambda_J^{m+1}}\|U[p]f\|^2+\sum_{p\in \Lambda_J^{m}}\|S[p]f\|^2.
	\end{equation}
\end{lemma}
\begin{proof}
The case $m=0$ is a consequence of condition \eqref{multir} and  Remark \ref{remark2.7} with $A = B = 1$. Indeed,
\[
\|f\|^2 = \sum_{j=0}^{J}\|\psi_j *f\|^2 = \|\phi \ast f\|^2 + \sum_{j=1}^{J}\|\psi_j *f\|^2 = \|Q f\|^2 + \sum_{j=1}^{J}\|U[j]f\|^2.
\]
By repeating this argument replacing $f$ with $U[p]f$ we can obtain, for  any $p\in \Lambda_J^m$
\[
\|U[p]f\|^2 = \sum_{j=1}^{J}\|U[p+j]f\|^2 +\|S[p]f\|^2.
\]
Finally, we can conclude by summing the previous equation for $p\in \Lambda_J^m$:
\[
\sum_{p\in \Lambda_J^m}\|U[p]f\|^2 = \sum_{p\in \Lambda_J^m}\sum_{j=1}^{J}\|U[p+j]f\|^2 + \sum_{p\in \Lambda_J^m}\|S[p]f\|^2 = \sum_{p\in \Lambda_J^{m+1}}\|U[p]f\|^2 + \sum_{p\in \Lambda_J^m}\|S[p]f\|^2
\]
where the last identity is due to
\[
\Lambda_J^{m+1}=\bigcup_{p\in \Lambda_J^m}\bigcup_{j=1}^{J} p+j. \qedhere
\]
\end{proof}
\section{Properties of the $G$-scattering transform} \label{section b}
The number of paths over which scattering can be computed is theoretically infinite; however, under condition \eqref{multir}, the energy of the $G$-scattering transform is not expanding, as it is made precise in the following Lemma. This result is a consequence of the structural property of the scattering transform stated in Lemma \ref{lem:3.2.2}\,.
\begin{lemma} \label{lemma4-1-New} ({\bf Non expanding})
	Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be a kernel satisfying \eqref{multir}. Then, for $f\in L^2(G)$, 
	\begin{equation*}
			\|S[P_J]f\|_{2,J} \leq \|f\|\,.
	\end{equation*}
\end{lemma}
\begin{proof}
   From Lemma \ref{lem:3.2.2}, for all $M\in \mathbb N$
   \begin{align*}
   	\sum_{m=0}^M \sum_{p\in \Lambda_J^m}\|S[p]f\|^2 & = \sum_{m=0}^M \sum_{p\in \Lambda_J^m}\|U[p]f\|^2 - \sum_{m=0}^M \sum_{p\in \Lambda_J^{m+1}}\|U[p]f\|^2 \\
   	& = \|f\|^2 -  \sum_{p\in \Lambda_J^{M+1}}\|U[p]f\|^2 \leq \|f\|^2\,.
   \end{align*}
Taking the limit when $M$ goes to infinity we obtain the result.
\end{proof}

 \subsection{Stability}

We now prove that, under condition \eqref{multir}, if two sets of data $f, f' \in L^2(G)$ are closed in the $L^2(G)$ norm, then the $G$-scattering transforms of $f$ and $f'$ are also close in the $\ell_2 (P_J,L^2(G))$ norm. Observe that if the $G$-scattering transform were a linear operator (which is not), this will easily follow form Lemma \ref{lemma4-1-New}.
\begin{proposition} ({\bf Stability}) \label{prop Stability}
Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be a kernel satisfying \eqref{multir}. Then, the scattering transform is stable in the following sense: if $f, f' \in L^2(G)$, 
\begin{equation}
    \|S[P_J]f-S[P_J]f'\|_{2,J}\leq \|f-f'\|.
\end{equation}
\end{proposition}
\begin{proof}
Let $p\in \Lambda_J^m, m \geq 0.$ Apply 
%Lemma \ref{lem:3.2.2} with $m=1$ 
condition \eqref{multir} and  Remark \ref{remark2.7} with $A = B = 1$ to the function $U[p]f - U[p]f' \in L^2(G)$ to obtain
\begin{equation} \label{eq:new36}
    \|U[p]f-U[p]f'\|^2=\sum_{j=1}^{J}\|\psi_j*(U[p]f-U[p]f')\|^2 + \|\phi*(U[p]f-U[p]f')\|^2.
\end{equation}
By the triangle inequality, for $j=1,2, \dots, J,$
$$
|\psi_j*(U[p]f-U[p]f')| \geq |\psi_j*U[p]f|- |\psi_j*U[p]f'|\,.
$$   
Summing the equality \eqref{eq:new36} over $p\in \Lambda_J^m$ we obtain 
\begin{align*}
    &\sum_{p\in \Lambda_J^m}\|U[p]f-U[p]f'\|^2\\
    &=\sum_{p\in \Lambda_J^m}\left(\sum_{j=1}^J\|\psi_j * U[p]f-\psi_j*U[p]f'\|^2 + \|\phi*U[p]f-\phi*U[p]f'\|^2\right)\\
    &\geq \sum_{p\in \Lambda_J^m}\left(\sum_{j=1}^{J}\| |\psi_j*U[p]f|-|\psi_j*U[p]f'|\|^2 + \|\phi*U[p]f-\phi*U[p]f'\|^2\right)\\
    &= \sum_{p\in \Lambda_J^m}\sum_{j=1}^J \|U[p+j]f-U[p+j]f'\|^2+ \sum_{p\in \Lambda_J^m}\|S[p]f-S[p]f'\|^2\\
    &=\sum_{p\in \Lambda_J^{m+1}}\|U[p]f-U[p]f'\|^2+ \sum_{p\in \Lambda_J^m}\|S[p]f-S[p]f'\|^2.
\end{align*}
Summing the previous inequality over $0\leq m \leq M, M\in \mathbb N$, we get
$$
\sum_{m=0}^M \sum_{p\in \Lambda_J^m}\|U[p]f-U[p]f'\|^2 - \sum_{m=0}^{M} \sum_{p\in \Lambda_J^{m+1}}\|U[p]f-U[p]f'\|^2 \geq \sum_{m=0}^M \sum_{p\in \Lambda_J^m}\|S[p]f-S[p]f'\|^2.
$$
Canceling equal terms in the left hand side of this inequality we obtain
\begin{align*}
\sum_{m=0}^M \sum_{p\in \Lambda_J^m}\|S[p]f-S[p]f'\|^2 &\leq \|f - f'\|^2 - \sum_{p\in \Lambda_J^{M+1}}\|U[p]f-U[p]f'\|^2 \\
& \leq \|f - f'\|^2\,.
\end{align*}
Taking the limit when $M$ goes to infinity we deduce the result.
\end{proof}
\subsection{Energy preservation} \label{Subsec:4-2}
Equality in Lemma \ref{lemma4-1-New} cannot hold in general for a kernel $\gamma$ satisfying 
\eqref{multir}. For example, if $\gamma_0(r)=0$ for all $r=1,2, \dots, k$, so that \eqref{multir} becomes $\displaystyle \sum_{j=1}^J |\gamma_j(r)|^2 = 1, r=1,2, \dots, k$, then $\phi(x)=0$ for all $x\in G$. Therefore, $\phi*f \equiv 0$ for any $f\in L^2(G)$ and $ S[p]f \equiv 0$ for all $p\in P_J$. This leads to the following definition.
\begin{definition} \label{admissible1}
	A kernel $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ is called {\bf admissible} if in addition to \eqref{multir} it holds that
	\begin{equation} \label{admissible2}
		\beta_\gamma := \min_{1\leq r \leq k} |\gamma_0 (r)|^2 > 0\,.
	\end{equation}
\end{definition}
Under the admissibility condition \eqref{admissible2} it can be proved that the $G$-scattering transform, $S[P_J]: L^2(G) \to \ell_2(P_J, L^2(G))$ is inyective. In fact, if $f, f'\in L^2(G)$ and $S[P_J]f = S[P_J]f'$, in particular $\phi*f = \phi*f'$. Taking Fourier transforms in both sides and using \eqref{eq:FourierGwavelet} we obtain $\gamma_0 (r) \widehat f (\pi^r) = \gamma_0 (r) \widehat {f'} (\pi^r)$ for $r=1,2,\dots, k$. Since $\beta_\gamma >0$, $\gamma_0(r) \neq 0$ for $r=1,2,\dots, k$. Therefore, $\widehat f (\pi^r) = \widehat {f'} (\pi^r), r=1,2,\dots, k$. By the Fourier inversion formula (see \cite{terras_1999}, Chapter 15, Theorem 2), we conclude $f=f'$ in $L^2(G).$

We can quantify this inyectivity. In fact, by the definition of $\| \ \|_{2,J}$ for $f, f' \in L^2(G)$ we can write
	$$
	\|S[P_J]f - S[P_J]f'\|_{2,J}^2 \geq \| \phi*f - \phi*f'\|^2 = \| \phi*(f - f')\|^2\,.
	$$
We now use Plancherel identity \eqref{eq:Plancherel} twice and condition \eqref{admissible2} to obtain
$$
\|S[P_J]f - S[P_J]f'\|_{2,J}^2 \geq \sum_{r = 1}^k\sum_{i,j=1}^{d_r} d_r |\gamma_0(r)|^2 \left|(\widehat{f}-\widehat{f'})(\pi^r)_{ij}\right|^{2} \geq \beta_\gamma \|f - f'\|^2\,.
$$


More important, under the admissibility condition given in Definition \ref{admissible1}, we are able to prove that the $G$-scattering transform preserves energy, that is, equality holds in Lemma 
\ref{lemma4-1-New}. Before proving this, we show a result about the energy decay rate of the scattering propagator $U$ at each level $m\in \mathbb N$.
\begin{proposition} \label{pro-4-4-New}
	Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be an admissible kernel as given in Definition \ref{admissible1}. Then, for each $m=1,2,\dots$, the scattering propagator $U$ has norm decay rate $\alpha = 1-\beta_\gamma < 1$ at the $m$-th layer, meaning that for all $f\in L^2(G)$,
	\begin{equation} \label{eq:decay2}
		\sum_{p\in \Lambda_J^m} \|U[p]f\|^2 \leq \alpha \sum_{p\in \Lambda_J^{m-1}} \|U[p]f\|^2\,.
	\end{equation}
\end{proposition}
\begin{proof}
	For any path $p\in P_J$ and $f\in L^2(G)$, by definition of $S[p]f$ and Plancherel equality \eqref{eq:Plancherel} we can write
	\begin{equation*}
		\|S[p]f\|^2=\|\phi*U[p]f\|^2= \sum_{r=1}^k\sum_{i,j=1}^{d_r} d_r |\gamma_0(r)|^2  \left|\widehat{U[p]f}(\pi^r)_{i,j}\right|^2.
	\end{equation*}
Since $|\gamma_0(r)|^2 \geq \beta_\gamma$ for all $r=1,2,\dots,k$ we get
\begin{align*}
	\|S[p]f\|^2 &\geq \beta_\gamma {\sum_{r=1}^k\sum_{i,j=1}^{d_r} d_r\left| (\widehat{U[p]f}(\pi^r))_{i,j}\right|^2}\\
	&=\beta_\gamma \|U[p]f\|^2\,,
\end{align*}
where we have used again Plancherel equality \eqref{eq:Plancherel}. Summing the above inequality over all $p\in \Lambda_J^{m-1}$ we have
\begin{equation*}
	\sum_{p\in \Lambda_J^{m-1}} \|S[p]f\|^2 \geq \beta_\gamma \sum_{p\in \Lambda_J^{m-1}}\|U[p]f\|^2.
\end{equation*}
Using the structural property of the scattering network given in Lemma \ref{lem:3.2.2} we obtain
\begin{align*}
	\sum_{p\in \Lambda_J^{m}}\|U[p]f\|^2 &= \sum_{p\in \Lambda_J^{m-1}}\|U[p]f\|^2-\sum_{p\in \Lambda_J^{m-1}}\|S[p]f\|^2 \\
	&\leq (1-\beta_\gamma) \sum_{p\in \Lambda_J^{m-1}}\|U[p]f\|^2 = \alpha \sum_{p\in \Lambda_J^{m-1}}\|U[p]f\|^2\,. \qedhere
\end{align*}
\end{proof}


As a corollary we can prove that the energy carried out by the extracted features of the $G$-scattering transform at level $m, m\geq 1,$ decreases exponentially in the presence of the admissibility condition.
\begin{corollary} \label{corollary2}
Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be an admissible kernel as given in Definition \ref{admissible1}. Then, for each $m=1,2, \dots$ and each $f\in L^2(G)$,
$$
\sum_{p\in \Lambda_J^m} \|S[p]f\|^2 \leq \left(\max_{1\leq r \leq k} |\gamma_0(r)|^2\right) \alpha^m \|f\|^2\,,
$$
where $\alpha = 1 -\beta_\gamma <1$ and $\beta_\gamma$ is defined in \eqref{admissible2}.	
\end{corollary}
\begin{proof}
Since $S[p]f= \phi*f$ for each $p\in \Lambda_p^m$, by Plancherel equality \eqref{eq:Plancherel} and \eqref{eq:FourierGwavelet}
\begin{align*}
    \|S[p]f\|^2 &= \sum_{r=1}^k \sum_{i,j=1}^{d_r} d_r \left|\widehat {\phi*Uf}(\pi^r)_{i,j}\right|^2\\
    &= \sum_{r=1}^k \sum_{i,j=1}^{d_r} d_r |\gamma_0(r)|^2 \left|\widehat {Uf}(\pi^r)_{i,j}\right|^2\\
    &\leq \left(\max_{1\leq r \leq k} |\gamma_0(r)|^2\right) \|U[p]f\|^2\,.
\end{align*}
Summing over all $p\in \Lambda_J^m$ and using \eqref{eq:decay2} $m$ times, the result follows.
\end{proof}

\begin{theorem} ({\bf Energy preservation}) \label{th:energy}
	Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be an admissible kernel as given in Definition \ref{admissible1}. Then, for each $f\in L^2(G)$,
	$$
	\|S[P_J]f\|_{2,J} = \|f\|\,.
	$$
\end{theorem}
\begin{proof}
	By the structural property of the scattering network given in Lemma \ref{lem:3.2.2}, for all $M\in \mathbb N$,
	\begin{align} \label{eq:energy2}
		\sum_{m=0}^M \sum_{p\in \Lambda_J^m} \|S[p]f\|^2 &= \sum_{m=0}^M \sum_{p\in \Lambda_J^m} \|U[p]f\|^2 - \sum_{m=0}^M \sum_{p\in \Lambda_J^{m+1}} \|U[p]f\|^2 \nonumber \\ 
		&= \|f\|^2 -  \sum_{p\in \Lambda_J^{M+1}} \|U[p]f\|^2\,.
	\end{align}
    By Proposition \ref{pro-4-4-New}, since $\alpha = 1-\beta_\gamma < 1$,
    $$
    0\leq \lim_{M\to \infty} \sum_{p\in \Lambda_J^{M+1}} \|U[p]f\|^2 \leq \lim_{M\to \infty} \alpha^M \|f\|^2 = 0\,.
    $$
    Taking limits when $M\to \infty$ in \eqref{eq:energy2} we obtain the result.
\end{proof}


\subsection{Equivariance and approximate invariance} \label{Subsec:4-3}
Consider the left and right regular representations of the finite group $G$ on $L^2(G)$. These are
$$
L: G \to \mathcal U(L^2(G)), \quad L_gf(x) = f(g^{-1}x)
$$
and
$$
R: G \to \mathcal U(L^2(G)), \quad R_gf(x) = f(xg),
$$	
for $g,x \in G$ and $f\in L^2(G).$

For $\psi\in L^1(G)$ consider the convolution operator $C_\psi : L^2(G) \to L^2(G)$ given by $C_\psi (f) = \psi * f.$ This convolution operator is {\bf equivariant} (also termed {\bf covariant} in some literature) with respect to the right regular representation; that is, for $f\in L^2(G)$,
\begin{equation} \label{eq_right-cov}
	C_\psi (R_g f)= R_g C_\psi(f), \quad  g\in G\,.
\end{equation}
This follows inmediately from the definition of convolution given in \eqref{def:convolution}.

If $\psi\in L^1(G)$ is also a class function (see \eqref{eugenio:2}), $C_\psi$ is equivariant with respect to the left regular representation, that is, for $f\in L^2(G)$,
	\begin{equation} \label{eq_left-cov}
		C_\psi (L_g f)= L_g C_\psi(f), \quad  g\in G\,.
	\end{equation}
Indeed, since $\psi$ is a class function, for $x\in G$ use \eqref{eugenio:5} and \eqref{def:convolution} to write
$$
C_\psi(L_g f)(x) = \psi * L_g f(x) = L_g f * \psi  = \frac{1}{|G|} \sum_{y\in G} f(g^{-1}y)\psi(y^{-1}x)\,.
$$
With $y^{-1}x = z$,
$$
C_\psi (L_g f)(x) = \frac{1}{|G|} \sum_{y\in G} f(g^{-1}x z^{-1})\psi(z) = f*\psi (g^{-1}x) = \psi * f (g^{-1}x) = L_g C_\psi(f)\,,
$$
where we have used \eqref{def:convolution} and that $\psi$ is a class function.

It is easy to see that the modulus operator commutes with $R_g$ and $L_g$ for all $g\in G$. Since the scattering networks described in Section \ref{section a} are made with convolution with class functions and modulus, we have the following result.
\begin{proposition} \label{eq:equivariance2}
	Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be a kernel and $S$ the $G$-scattering operator. For all $g\in G$, $p\in P_J$, and $f\in L^2(G)$,
	$$  a) \  S[p]L_g f = L_g S[p]f\,,\qquad \text{and}  \qquad b) \ S[p]R_g f = R_g S[p]f\,.$$
\end{proposition}

Another property of operators is invariance. For the convolution operators $C_\psi$ and the right and left regular representations this means
\begin{equation} \label{eq:invariance2}
	  a) \ S[p]L_g f = S[p]f\,,\qquad \text{and}  \qquad b) \ S[p]R_g f = S[p]f\,.
\end{equation}
$f\in L^2(G)$ and $g\in G$. If \eqref{eq_right-cov} and part $b)$ of \eqref{eq:invariance2} hold simultaneously, for all $g\in G$ and all $x\in G$,
$$
L_g C_\psi (f)(x) = C_\psi(f)(xg).
$$
Taking $x=e$, the identity of the group $G$, it follows that $C_\psi f(g) = C_\psi (e)$, and thus, $C_\psi(f)$ is a constant function in $G$. Similarly if
\eqref{eq_left-cov} and part $a)$ of \eqref{eq:invariance2} hold simultaneously. Consequently, we cannot have, in general, invariance of the $G$-scattering transform. Nevertheless, we can prove that at the depth of the scattering propagator increases, the $G$-scattering features become closer to be invariant, and, hence, closer to be constant functions.
\begin{theorem} ({\bf Approximate invariance}) \label{th:approxinv}
	Let $\gamma = \{ \gamma_j: \{1,2, \dots, k\} \to \mathbb C\}_{j=0,1,\dots, J}$ be an admissible kernel as given in Definition \ref{admissible1}. For each $m\geq 1, f\in L^2(G), g\in G$,
	$$
	\sum_{p\in \Lambda_J^m} \| S[p]L_g f - S[p]f\|^2 \leq  \left(\max_{1\leq r \leq k} |\gamma_0(r)|^2\right) 4\, \alpha^m \|f\|^2\,,
	$$
	where $\alpha = 1 -\beta_\gamma <1$ and $\beta_\gamma$ is defined in \eqref{admissible2}. Moreover, a similar result holds replacing $L_g$ by $R_g, g\in G.$	
\end{theorem}
\begin{proof}
	By part $a)$ of Proposition \ref{eq:equivariance2},
	\begin{align*}
		\sum_{p\in \Lambda_J^m} \| S[p]L_g f - S[p]f\|^2 &= \sum_{p\in \Lambda_J^m} \|L_g S[p] f - S[p]f\|^2 \nonumber \\
		&\leq \| L_g - I\|^2 \sum_{p\in \Lambda_J^m} \| S[p]f\|^2 
	\end{align*}
    In view of Corollary \ref{corollary2}, we only need to prove the estimate $\|L_g - I\|^2 \leq 4.$ This follows from the following computation. For any $f\in L^2(G)$,
    \begin{align*}
    	\|L_g f - f\|^2 &=\frac{1}{|G|} \sum_{y\in G} |f(g^{-1}y) - f(y)|^2 
    	\leq \frac{1}{|G|} \sum_{y\in G} (|f(g^{-1}y)| + |f(y)|)^2 \\
    	&\leq \frac{2}{|G|} \sum_{y\in G} (|f(g^{-1}y)|^2 + |f(y)|^2) = 4 \|f\|^2\,.
    \end{align*}
The proof for the right regular representation is similar.	
\end{proof}

