\section{Preliminaries}
\label{sec:background_team_based_logic}
We present the background on propositional logics with classical semantics, team semantics and propositional dependence logic %
(a survey on team-based logics can be found by \citeauthor{AKV16}, \citeyear{AKV16}).
Furthermore, we present the background on computational complexity.


%
%
%
\MYParagraph{Language of Propositional Logic.}
%
In the following, we describe some logics we consider in this paper.
We denote by $\Prop=\{\;p_i\mid i\in \mathbb{N}\;\}$ the countably infinite set of propositional variables. 
We will use letters $p,q,r,\dots$ (with or without subscripts) to stand for elements of $\Prop$. 
In this paper, we consider propositional formulas in negation normal form, i.e., 
well-formed \PL-formulas $\formulaOne$  are formed by the grammar:
 \[\formulaOne\Coloneqq p\mid \neg p \mid \bot\mid\top\mid \formulaOne\wedge\formulaOne\mid\formulaOne\vee\formulaOne,\]
%
where $p\in\Prop$, and $\top,\bot$ are the usual syntactic sugars for true and false. We write $\Prop(\formulaOne)$ for the set of propositional variables occurring in $\formulaOne$.
%
%
	%
	%
	%
	%
%
%

\MYParagraph{Classical Propositional Logic (\CPL).}
We consider the \emph{classical semantics} for \PL-formulas.
If one considers a non-empty finite subset $N\subseteq \Prop$ of propositional variables, then define for valuations $v\colon N\to\{0,1\}$ over \( N \) and \PL-formulas \( \formulaOne \):
\[ \llbracket \formulaOne\rrbracket^c \coloneqq\{v\colon N\to\{0,1\}\mid v\models\formulaOne\}. \]
We also write $v\models p$ in case $v(p)=1$, and $v\not\models p$ otherwise. 
The valuation function $v$ is extended to the set of all \PL-formulas in the usual way.
Let denote by $\allModels{N}$ the set of all assignments over $N$. 
Furthermore, we will write $\PL(N)$ for all propositional formulas using variables only from $N$.
%
	\begin{comment}
		Let $v:\Prop\to\{0,1\}$ be a valuation. For any classical $\formulaOne$, the truth relation $v\models\formulaOne$ is defined inductively as:
		\begin{itemize}
			\item $v\models p$ ~~iff~~ $v(p)=1$;
			\item $v\models \bot$ ~~is never the case;
			\item $v\models \top$ ~~is always the case;
			\item $v\models\neg\formulaOne$ ~~iff~~ $v\not\models\formulaOne$;
			\item $v\models\formulaOne\wedge\formulaTwo$ ~~iff~~ $v\models\formulaOne$ and $v\models\formulaTwo$;
			\item $v\models\formulaOne\vee\formulaTwo$ ~~iff~~ $v\models\formulaOne$ or $v\models\formulaTwo$.
		\end{itemize}
	\end{comment}
	%
%
%
We write $\formulaOne\models^c\formulaTwo$ for $ \llbracket \formulaOne\rrbracket^c \subseteq \llbracket \formulaTwo\rrbracket^c $ and $\formulaOne\equiv^c\formulaTwo$ if both $\formulaOne\models^c\formulaTwo$ and $\formulaTwo\models^c\formulaOne$.
%
When we talk in this paper about \CPL, we refer to the logic with \PL-formulas and classical semantics. 

%

%
%
%

\begin{comment}


	\begin{theorem}\label{PL_usual_sem_expressive_complete}
		Let $N=\{p_1,\dots,p_n\}$. For every set $X\subseteq 2^N$, there is a \PL-formula $\formulaOne$
		such that $\llbracket \formulaOne\rrbracket_N^c=X$.
	\end{theorem}
	\begin{proof}
		Let 
		\[\formulaOne=\bigvee_{v\in X}(p_1^{v(1)}\wedge\dots\wedge p_n^{v(n)}),\]
		where $v(i)$ is short for $v(p_i)$, $p_i^{1}=p_i$ and $p_i^0=\neg p_i$ for any $1\leq i\leq n$, and in particular $\bigvee\emptyset:=\bot$. For any valuation $u:N\to\{0,1\}$, we have that 
		\[u\models \formulaOne\iff u\models p_1^{v(1)}\wedge\dots\wedge p_n^{v(n)}\text{ for some }v\in X\iff u=v\in X.\] 
	\end{proof}



	\begin{corollary}\label{PL_usual_sem_dnf}
		Let $N=\{p_1,\dots,p_n\}$. For every classical formula $\formulaOne(p_1,\dots,p_n)$, we have that
		\[\formulaOne\equiv^c\bigvee_{v\in\llbracket \formulaOne\rrbracket^c_N}(p_1^{v(1)}\wedge\dots\wedge p_n^{v(n)}).\]
	\end{corollary}
\end{comment}

\MYParagraph{Propositional Logic with Team Semantics (\TPL).}
Next, we define \emph{team semantics} for \PL-formulas (cf. \cite{HannulaKVV15,YangV16}). A  team $X$ is a set of valuations for some finite set $N\subseteq \Prop$. We write $\dom(X)$ for the domain $N$ of $X$.%


\begin{definition}[Team semantics of \PL]
	Let $X$ be a team. For any \PL-formula $\formulaOne$ with $\dom(X)\supseteq \Prop(\formulaOne)$, the satisfaction relation $X\models\formulaOne$ is defined inductively as:
	\begin{align*}
		&X\models p&&\text{if for all }v\in X: v\models p\\
		&X\models\neg p&&\text{if for all } v\in X: v\not\models p\\
		&X\models \bot&&\text{if } X=\emptyset\\
		&X\models \top&&\text{is always the case}\\
		&X\models\formulaOne\wedge\formulaTwo&&\text{if } X\models\formulaOne \text{ and } X\models\formulaTwo\\
		&X\models\formulaOne\vee\formulaTwo&&\text{if there exist } Y,Z\subseteq X\\
		&&&\text{ s.t. }X=Y\cup Z, Y\models\formulaOne, \text{ and }Z\models\formulaTwo.
	\end{align*}
\end{definition}
%
\noindent The set of all teams \( X \) with \( X\models\formulaOne \) is denoted by \( \modelsOf{\formulaOne} \).
%
%
For any two \PL-formulas \( \formulaOne,\formulaTwo \), we write $\formulaOne\models^t\formulaTwo $ if \( \modelsOf{\formulaOne} \subseteq \modelsOf{\formulaTwo} \).
%
Write $\formulaOne\equiv^t\formulaTwo$ if both $\formulaOne\models^t\formulaTwo$ and $\formulaTwo\models^t\formulaOne$.
With \TPL we refer to the logical setting of \PL-formulas with team semantics.
We define the following properties for a formula~$\formulaOne$:
\begin{itemize}
		\item $X\models \formulaOne \iff \text{for all } v\in X,~\{v\}\models\formulaOne$. \hfill {\small(\textbf{Flatness})}
		\item $\emptyset \models \formulaOne$.\hfill{\small(\textbf{Empty team property})}
		\item If $X \,{\models}\, \formulaOne$ and $Y\,{\subseteq}\, X$, then ${Y\models \formulaOne}$.\hfill{\small(\textbf{Downwards closure})}
		%
\end{itemize}
\begin{proposition}\label{prop:pdl_pincl_properties}
	\TPL has the flatness property, empty team property and downwards closure property. 
    %
\end{proposition}


%
%
%
%

%
%
%
%
%
%
%
%
%
%


%

%
%
%
%
%
%
Due to the flatness property, logical entailment of propositional logic with team-based semantics $\models^t$ and logical entailment of propositional logic with classical semantics $\models^c$ coincide.
However, we will see later that these different semantic approaches will lead to different preferential entailment relations.

%
%
%
%

%
%
\MYParagraph{Propositional Dependence Logic.}
%
%
\label{sec:pdl_pincl}
A {\em (propositional) dependence atom} is a string $\dep{a_1\dots a_k,b}$, 
%
in which $a_1,\dots,a_k,b$ are propositional variables from \Prop. 
The  team semantics of dependence atoms is defined  as follows, whereby \( \vec{a} \) stands for \( a_1,\dots, a_k \):
\begin{align*}
	& X \models \dep{\vec{a},b} && \text{if}~\text{for all }v, v' \in X, \\
	&&& \phantom{if} v(\vec{a})=v'(\vec{a}) \textrm{ implies }v(p)=v'(p).
\end{align*}
%
%
	%
	%
%
%
%
%
%
%
%
A dependence atom with the empty sequence in the first component will be abbreviated as $\dep{p}$ and called {\em constancy atoms}. The team semantics of the constancy atoms is reduced to
\begin{equation*}
	X \models \dep{p} ~~\text{if}~~ \text{for all }v, v' \in X, v(p)=v'(p).
\end{equation*}
We define the language of {\em propositional dependence logic} (denoted as \pdl) as the extension of \PL-formulas with dependence atoms.
With \PDL we refer to the whole logical approach, including the language and the above-mentioned semantics.
We consider an example for \PDL.
\begin{example}\label{example_dep_atm_propositional}
	Consider the team $X$ over $\{p,q,r\}$ defined by:
	\begin{center}
		\begin{tabular}{cccc}\toprule
			&$p$&$q$&$r$\\\midrule
			$v_1$&$1$&$0$&$0$\\
			$v_2$&$0$&$1$&$0$\\
			$v_3$&$0$&$1$&$0$\\\bottomrule
		\end{tabular}
	\end{center}
	We have $X\models\dep{p,q}$ and $X\models\dep{r}$. Moreover,  $X\models\dep{p}\vee \dep{p}$ but  $X\not \models\dep{p}$. %
	%
	%
	%
\end{example}
\begin{comment}
	As illustrated in the above example, in general, propositional dependence atoms with multiple arguments can be easily defined using constancy atoms.


	\begin{fact}
		$\displaystyle\dep{p_1\dots p_n,q}\equiv\bigvee_{v\in 2^N}(p_1^{v(1)}\wedge\dots\wedge p_n^{v(n)}\wedge\dep{q})$, where $N=\{p_1,\dots,p_n\}$.
	\end{fact}

\end{comment}



The following proposition describes properties of \PDL.
%
\begin{proposition}\label{prop:pdl_pincl_properties}
	\PDL has the empty team property and downwards closure property. 
    %
\end{proposition}
Note that \PDL does not satisfy the flatness property. 
We can define the flattening $\phi^f$ of a  \pdl-formula by replacing all dependence atoms in $\phi$ by $\top$. Clearly, $\phi^f$ is a \PL formula. Furthermore, one checks easily that $\phi \models^t \phi^f$
and that \( \{v\}\models \phi \Leftrightarrow v\models \phi^f \) for all assignments $v$.
%
	%
%
%
%
%



\MYParagraph{Generic View on Logics.} 
Some parts of this paper will require a generic view on logics. 
The following provides such a view that provides the right abstraction to capture those aspects of logics that we need in this paper in a generic way.
A satisfaction system is a triple \( \ssSystem = \tuple{\ssFormulas,\ssInt,\models} \), where \( \ssFormulas \) is the set of formulas, \( \ssInt \) is the set of interpretations, and  \( {\models} \subseteq \ssInt \times \ssFormulas \) is the model-relation.
An entailment relation for a satisfaction system is a relation \( {\nmableit} \subseteq \ssFormulas \times \ssFormulas\). 
A satisfaction system \( \ssSystem \) together with an entailment relation \( \nmableit \) is denoted as logic
%
 \( \ssLogic = \tuple{\ssFormulas,\ssInt,\models,\nmableit} \).
We say a logic \( \ssLogic \) is \emph{standard}, if \( \nmableit \) is the canonical logical entailment given by \( \formulaOne \nmableit  \formulaTwo \) if \( \modelsOf{\formulaOne} \subseteq \modelsOf{\formulaTwo} \), whereby \( \modelsOf{\formulaOne} = \{ v \in \ssInt \mid v \models \formulaOne  \}  \). The canonical logical entailment is often written with the same symbol $\models$.
The propositional logics described in this section provide the following instances of the generic approach for each \( N \subseteq \Prop \), which are all standard logics:
\begin{center}
    \begin{tabular}{@{}l@{\hskip0.05em}l@{\hskip0.05em}l@{}}
    \( \CPL_{N} \)  & \( =\! \tuple{\ssFormulas^{\CPL}_{N},\ssInt^{\CPL}_{N},\models,\models^{\CPL}}  \) & \( {=}\, \tuple{\PL(N),\allModels{N},\models,\models^c} \)\\
    \( \TPL_{N} \) & \( =\! \tuple{\ssFormulas^{\TPL}_{N},\ssInt^{\TPL}_{N},\models,\models^{\TPL}}\) & \( {=}\, \tuple{\PL(N),\mathbb{T}_{N},\models,\models^t} \)\\
    \( \PDL_{N} \) & \( =\! \tuple{\ssFormulas^{\PDL}_{N},\ssInt^{\PDL}_{N},\models,\models^{\PDL}} \) & \( {=}\, \tuple{\pdl, \mathbb{T}_{N},\models,\models^t}\)
\end{tabular}
\end{center}
Often, we will not mention \( N \) explicitly and assume that there is some \( N \) of appropriate size.
Moreover, we will write $\models$ instead of $\models^t$ when there is no ambiguity.

%

%
%



%
\MYParagraph{Computational Complexity.}
%
We assume basic familiarity with computational complexity theory~\cite{KS_Papadimitriou1994}. 
We will make use of the complexity classes $\Ptime$ and $\Delta_2^p=\Ptime^{\NP}$, as well as standard reducibility notions, e.g., logspace-many-to-one reductions~${\leqlogm}$.

Before we define a natural complete problem for $\Delta_2^p$, we need to formally introduce the lexicographic order on assignments. 
Let $P\subsetneq\Prop$ with $|P|=n$. 
An assignment function $v\colon P\to\{0,1\}$ is interpreted as a string $v_s$ from $\{0,1\}^n$ in the natural way, i.e., $v_s=v(x_1)\cdots v(x_n)$ if $P=\{x_1,\dots,x_n\}$.  
We denote by $v_s[i]$ for $1\leq i \leq n$ the $i$th bit of $v_s$. 

\begin{definition}[lexicographic order]
    For two strings $s,s'\in\{0,1\}^n$ with $s\neq s'$ we say that $s\lex s'$ if there exists a (possibly empty) prefix $0\leq j\leq n$ such that $s[k]=s'[k]$ for all $0\leq k\leq j$ and $s[k+1]<s'[k+1]$. 
\end{definition}

\problemdef{\OLMS}{A propositional formula $\formulaOne$ over variables $\{x_1,\dots,x_n\}$}{$\formulaOne$ is satisfiable, and for the largest satisfying assignment $\theta$ with respect to $\lex$ do we have that $\theta(x_n)=1$}

\begin{proposition}[\citeauthor{KS_Krentel1988}~\citeyear{KS_Krentel1988}]
    $\OLMS$ is $\Delta_2^p$-complete under $\leqlogm$-reductions.
\end{proposition}

The complementary problem to \OLMS is denoted here as \OLMSco, where $\theta(x_n)\neq1$.
%
%
As \( \Delta_2^p \) is a deterministic complexity class, \( \OLMSco \) of \( \OLMS \) is also $\Delta_2^p$-complete.
%
    %
    %

%
Now we will present the standard notion of a circuit family. 
For a comprehensive overview of the topic of circuit complexity, refer to the textbook by Vollmer~(\citeyear{v99}).

%
    %
    %
    %
        %
        %
        %
        %
        %
    %
    %
    %

\begin{definition}
    Let $B=\{\lor,\land,\lnot,0,1\}$. 
    A \emph{circuit family} over $B$ is a sequence $\mathcal C=(C_0,C_1,\dots)$, where for every $n\in\N$, $C_n$ is a circuit over $B$ with $n$ inputs. 
    Let $f^n$ be the function computed by $C_n$. 
    Then we say that $\mathcal C$ computes the function $f\colon \{0,1\}^*\to \{0,1\}^*$, defined for every $w\in\{0,1\}^*$ by $f(w)\coloneqq f^{|w|}(w)$. 
    We write $f=(f^n)_{n\in\N}$ and $\mathcal C=(C_n)_{n\in\N}$.
\end{definition}
%
%
    %
    %
    %

    %
    %
    %

As usual $\AC0$ denotes the class of all polynomial-sized circuit families of constant depth using gates with unbounded fan-in. 
$\NC{1}$ denotes the class of all polynomial-sized circuit families of logarithmic depth using gates with fan-in two.


\begin{example}\label{ex:lex-circ}
    Given two binary strings $\bar a=a_{n-1}\cdots a_{0},\bar b=b_{n-1}\cdots b_{0}$ (so the least significant bit is the rightmost bit), the lexicographic order $\lex$ can be defined via an $\AC0$-circuit, where the overline $\overline{\,\cdot\,}$ means an outermost negation:
    \[
    \overline{\bigvee_{i=0}^{n-1} \big(a_i > b_i  \land \bigwedge_{j=i+1}^{n-1} (a_j = b_j)\big)},
    \]
    and conjunctions (disjunctions) over the empty set are defined as true (false). 
    Here $a>b$ is then merely encoded via $a\land\lnot b$, and $a=b$ with $(a\land b)\lor(\lnot a\land\lnot b)$.
\end{example} 

\section{Background on Preferential Logics}
\label{sec:background_KLM_logic}
%
In this section, we present background on preferential logics in the style of Kraus, Lehmann and Magidor (\citeyear{KS_KrausLehmannMagidor1990}) (KLM).
%
%
%
%
In preferential logic, an entailment  \( \formulaOne \nmableit \formulaTwo \) holds, when minimal models of \( \formulaOne \) are models of \( \formulaTwo \). This is formalized via preferential models, which we introduce in the following.
%

	For a  strict partial order \( {\pmP} \subseteq \mathcal{S} \times \mathcal{S} \) on a set \( \mathcal{S} \) and a subset \( S \subseteq \mathcal{S} \), an element \( s \in S \) is called \emph{minimal in \( S \) with respect to \( \pmP \)} if for each \( s' \in S \) holds  \( s' \not \pmP s \). 
	Then, \( \minOf{S}{{\pmP}} \)  is the set of all \( s \in S \)  that are minimal in \( S \) with respect to \( \pmP \).
%

%
%
%
%
%
%
%
%
%
%
%
\begin{definition}[KLM, \citeyear{KS_KrausLehmannMagidor1990}]
    Let \( \ssLogic = \tuple{\ssFormulas,\ssInt,\models,\models^{\ssLogic}}  \) be a logic.
    A \emph{preferential model} for \(  \ssLogic  \) is a triple \( \pmW=\tuple{\pmS,\pmL,\pmP} \) where \( \pmS \) is a set, \( \ell\colon \pmS \to \Omega \), \( \pmP \) is a strict partial order on \( \pmS \), and the following condition is satisfied:
    \begin{itemize}
%
%
%
        \item[]\emph{[Smoothness]} \( \statesOf{\formulaOne}=\{ s \in \pmS \mid \ell(s) \models \formulaOne \} \) is smooth with respect to \( \pmP \) for every formula \( \formulaOne \in \ssFormulas \), i.e, for each \( s \in \statesOf{\formulaOne} \) holds
        \( s\in \minOf{\statesOf{\formulaOne}}{\pmS} \) or there exists an \( s' \in \statesOf{\formulaOne} \) with \( s'\in \minOf{\statesOf{\formulaOne}}{\pmS} \) and \( s' \pmP s \).
%
%
%
%
    \end{itemize}
    %
    %
We say a preferential model is finite if $\pmS$ is finite.
\end{definition}
%
%
%
%
Smoothness guarantees the existence of minimal elements.
For convenience, we make use of the following abbreviations: \( \minOf{\modelsOf{A}}{\pmP} = \{ \pmL(s) \mid s\in \minOf{S(A)}{\pmP}  \} \) and we write \( s \models \formulaOne \) for \( \pmL(s) \models \formulaOne \).
%
%
%
%
%
\begin{definition}[KLM, \citeyear{KS_KrausLehmannMagidor1990}]
%
    %
    Let \( \ssLogic = \tuple{\ssFormulas,\ssInt,\models,\models^{\ssLogic}}  \) be a standard logic.
    The entailment relation \( {\nmableitW} \subseteq \ssFormulas \times \ssFormulas \) for a preferential model \( \pmW \) for \(  \ssLogic \) is given by
    \begin{equation*}
    	\formulaOne \nmableitW \formulaTwo \text{ if }  \minOf{\modelsOf{\formulaOne}}{\pmP} \subseteq \modelsOf{\formulaTwo}\ .
    \end{equation*}
    An entailment relation \( {\nmableit} \subseteq \ssFormulas \times \ssFormulas \) is called \emph{preferential} if there is a preferential model \( \pmW \) for \( \mathscr{L} \) such that  \( {\nmableit} =   {\nmableitW}  \). 
\end{definition}%
%

Every preferential model \( \pmW \) for a standard logic \( \ssLogic = \tuple{\ssFormulas,\ssInt,\models,\models^{\ssLogic}} \) give rise to a logic \( \ssLogic_{\pmW} = \tuple{\ssFormulas,\ssInt,\models,{\nmableitW}} \). We say that \( \ssLogic_{\pmW} \) is a preferential logic for \( \ssLogic \). 
%
\emph{Preferential propositional dependence logic} (\PDLPref) refers to the preferential logics for \( \PDL \); and analogously for \emph{preferential classical propositional logic} (\CPLPref) and  \emph{preferential propositional logic with team semantics} (\TPLPref).
