%
\MYParagraph{Relationship of \PDLPref to System~P.}
The following example shows that Proposition~\ref{prop:KLM_preferential_representation} does not carry over to \PDL, i.e., there are preferential entailments for \PDL that witness a violation of \eqref{pstl:Or}. 
\begin{example}\label{ex:violateOR}
    Assume that \( N=\{p,q\}\subseteq\Prop \) holds.
    The following valuations \( v_1,v_2 ,v_3 \) will be important: %
    \begin{align*}
        v_1(p) &=v_1(q)=v_2(q)=1 & v_2(p)&= v_3(p)=v_3(q)=0
    \end{align*}
    We consider the teams \( X_{pq}=\{ v_1\} \), \( X_{\overline{p}{q}}=\{ v_2\} \), and  \( X_{p\leftrightarrow q}=\{ v_1,v_3\} \).
    %
        %
            %
            %
            %
        %
        %
            %
            %
            %
        %
            %
            %
            %
            %
        %
    Let \( \pmWpq = \tuple{\pmSpq,\pmLpq,\pmPpq} \) be the preferential model such that
    \begin{align*}
        \pmSpq & = \{ s_{\Int} \mid \Int \text{ is a  non-empty team} \} & \pmLpq(s_X) & = X         
    \end{align*}
    holds, and such that \( \pmPpq \) is the strict partial order given by (for the sake of readability we identify \( s_X \) with \( X \)).
    \begin{align*}
        X_{p\leftrightarrow q} & \pmPpq  X_{pq}             & X_{pq}              & \pmPpq X \\
        X_{p\leftrightarrow q} & \pmPpq X_{\overline{p}{q}} & X_{\overline{p}{q}} & \pmPpq X
    \end{align*}
    where \( X \) stands for every team different from \( X_{\overline{p}{q}} \) and  \(  X_{p\leftrightarrow q} \).
    %
    We     obtain the following preferential entailments:
    \begin{align*}
        p & \nmableitWparam{\pmWpq} q &  \neg p & \nmableitWparam{\pmWpq} q & p\lor\neg p &\notnmableitWparam{\!\!\pmWpq} q
    \end{align*}
    This shows that \( \nmableitWparam{\pmWpq} \) violates \eqref{pstl:Or}, and thus, System~P.
\end{example}
\begin{proposition}
\PDLPref violates System~P.
\end{proposition}
