%
%
%
%
%
%


We will now identify two properties that will fully capture those preferential entailment relations that satisfy all rules of System~P within \PDL. 
%
As first, we can observe that one obtains System~P, when the underlying preferential model \( \pmW =\tuple{\pmS,\pmL,\pmP} \) satisfies the following property:
%
\begin{equation}
    \minOf{\modelsOf{A \lor \formulaTwo}}{\pmP} \subseteq \minOf{\modelsOf{A}}{\pmP} \cup \minOf{\modelsOf{\formulaTwo}}{\pmP}	\tag{\( \star \)}\label{eq:StarProperty}
\end{equation}
One checks easily that \eqref{eq:StarProperty} guarantees satisfaction of \eqref{pstl:Or}.
\begin{proposition}\label{prop:SystemPifStar}
    Let \( \pmW \) be a preferential model for \PDL.
    If \eqref{eq:StarProperty} is satisfied for all formulas \( \formulaOne,\formulaTwo \), then \( \nmableitW \) satisfies \eqref{pstl:Or}.
%
\end{proposition}
%
%
%
%
%
%
%
%
\noindent Second, we say that \( \pmW \) satisfies the \eqref{eq:TriangleProperty}-property if for all state \( s\in\pmS \) hold:
%
%
%
%
%
%
\begin{equation}
%
\text{If\,} |\pmL(\!s\!)|\,{>}\,1 \text{,\,then\,} \pmL(\!s') \,{\subsetneq}\, \pmL(\!s\!) \text{\,and\,} s'\,{\pmP}\, s \text{\,for\,some\,} s'{\in\,}\pmS . \tag{\( \triangle \)}\label{eq:TriangleProperty}
\end{equation}
The \eqref{eq:TriangleProperty}-property demands (when understanding states as teams) that for each non-singleton team \( X \) exists a proper subteam \( Y \) of \( X \) that is preferred im \( \pmW \) over \( X \).



In the following theorem, we show that the  \( \triangle \)-property and \eqref{eq:StarProperty}-property guarantee satisfaction of System~P.
\begin{theorem}\label{main}
    Let \( \pmW=\tuple{\pmS,\pmL,\pmP} \)  be a preferential model for \PDL.
    The following statements are equivalent:
    \begin{enumerate}[(i)]
        \item \( \nmableitW \) satisfies System~P.
        \item \( \pmW \) satisfies the \( \triangle \)-property.
        \item The \eqref{eq:StarProperty}-property holds for all \( \formulaOne,\formulaTwo\in\PDL \).
    \end{enumerate}
\end{theorem}
\pagebreak[3]
We prepare the proof of Theorem~\ref{main} via the following lemmata.
For the first lemma, assume that $N=\{p_1,\dots,p_n\}$, and let $X$ be an $N$-team. 
We define the following formula:
\[\Theta_X:=\bigvee_{v\in X}(p_1^{v(1)}\wedge\dots\wedge p_n^{v(n)}) \ ,\]
whereby \( p_i^{v(i)} \) is \( p_i \) if \( v(p_i)=1 \) and \( \neg  p_i \) otherwise.
%
%
Note that for a team \( X \), the powerset \( \mathcal{P}(X) \) is the set of all subteams of \( X \).
It is straightforward to check the following.
\begin{lemma}\label{lem:definedownsets}
     $\Theta_X$ defines the family of subteams of $X$, i.e., we have that 
     \( \modelsOf{\Theta_X} = \mathcal{P}(X) \).
%
\end{lemma}

%
%
%
%
%


%
%
The next lemma guarantees that for a sufficient large enough teams \( X \) exist formulas \( \formulaOne,\formulaTwo \) such that \( X \) is a model of the disjunction \( \formulaOne \lor \formulaTwo \), but \( X \) is not a model of \( \formulaOne \) and \( \formulaTwo \).
%
%
\begin{lemma}\label{lem:dagger}
    For each team \( X \) with \( |X|>1 \) exists formulas \( \formulaOne \) and \( \formulaTwo \) such that
    \begin{align*}
        X \models \formulaOne \lor \formulaTwo \text{ , } X \not\models \formulaOne \text{ , and } X \not\models \formulaTwo.
    \end{align*}
\end{lemma}
\begin{proof}
    Since \( |X|>1 \) %
    there exists non-empty \( Y,Z\subseteq X \) such that \( X=Y\cup Z \) and \( Y\neq X \) and \( Z \neq X \).
    There are formulas \( \formulaOne \) and \(\formulaTwo \) such that \( \modelsOf{\formulaOne}=\mathcal{P}(Y) \) and \( \modelsOf{\formulaTwo}=\mathcal{P}(Z) \), namely \( \formulaOne=\Theta_Y \) and \( \formulaTwo=\Theta_Z \) from by Lemma~\ref{lem:definedownsets}.
\end{proof}


