% \spara{Bias.}
After deriving the MLE of \Cref{eq:mle_bc}, we study its bias $\mathbb{E}(\est{\bc}) - \bc$.
Our definition of sBCM allows us to exploit a formal equivalence with
%connect our formalism to 
Rasch models, a well-established framework in Item Response theory~\cite[Ch. 16]{fischer200616}.
In item response experiments, individuals respond to a set of items.
Rasch models characterize each individual with an ability parameter, and each item with a difficulty parameter.
Under the assumptions of Rasch models, the probability that an individual correctly answer to an item increases with the ability of the person, while it decreases with the item difficulty.

\begin{lemma}
    Estimating \bc in a sBCM with observed $\state^0$ and known \rate is equivalent to estimating the ability parameter of a single individual in a Rasch model.
    In particular, \bc is associated to the person parameter, and $|\state_i^t - \state_j^ t|$ is associated to the item parameter.
\label{lemma:rasch}
\end{lemma}

We provide the proof of \Cref{lemma:rasch} in \Cref{apx:rasch}, by simply substituting the variables of sBCM into the equation of Rasch models.
Now, we have all the ingredients to prove \Cref{theorem:asymptotically_unbiased}.
\begin{proof}[Proof of \Cref{theorem:asymptotically_unbiased}]
By leveraging well-known results on Rasch models, in \Cref{apx:biasvariance} we obtain the closed formula of the bias of the MLE.
We denote $h = (i,j,t)$ and $\kappa_h = \kappa_{i,j,t}(\bc)$.
\begin{equation}
    Bias(\est\bc) = \frac{1}{\rho \left(\sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \right)^2} \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \left(\kappa_{h} - \frac{1}{2}\right)
    \label{eq:bias_rasch}
\end{equation}

Hence, the estimator is biased for small samples.
Specifically, the only term of \Cref{eq:bias_rasch} that can be negative is $\kappa_{h} - \frac{1}{2}$.
This implies that the bias is positive in the experiments with a higher weight given by positive interactions, consequently higher values of $\kappa_{h} - \frac{1}{2}$, and negative otherwise.
Therefore, the MLE pushes towards the extreme values,  overestimating high values of \bc, while underestimating low values of \bc.

Next, we can write
\begin{align}
\begin{split}
    \lvert Bias(\hat\bc) \rvert &= \left| \frac{1}{\rho \left(\sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \right)^2} \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \left(\kappa_{h} - \frac{1}{2}\right) \right| \\
    &=  \frac{1}{\rho \left(\sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \right)^2} \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \left(\right| \kappa_{h} - \frac{1}{2} \left| \right)  \\
    &<  \frac{1}{\rho \left(\sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) \right)^2} \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h})  \frac{1}{2}  \\
    &=  \frac{1}{2 \rho \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h}) } \\
    &< \frac{1}{8 \rho T},    
\end{split}
\end{align}
and the bias is of order $T^{-1}$.
%This proves \Cref{lemma:asymptotically_unbiased}.
\end{proof}

Moreover, the bias goes to 0 as $\rho\rightarrow\infty$ (see \Cref{fig:rho_vs_bias}).
This means that as the sBCM tends to its deterministic counterpart, that is, Deffuant's BCM, the bias of MLE disappears.

Furthermore, we also have the estimate of the variance of the MLE (see \Cref{apx:biasvariance}), that is,

\begin{equation}
    Var(\est\bc) = \frac{1}{\rho^2 \sum\limits_{h \in \order} \kappa_{h} (1 - \kappa_{h})}.
\label{eq:var}
\end{equation}


