    \centering
    \includegraphics[scale=0.8]{figures/hedgehogs2.pdf}
    \caption{The forbidden induced subgraphs for clique-sparse graphs: 
        the \textcolor{CornflowerBlue}{filled} ellipses represent cliques, while the empty ellipses represent independent sets. See \cref{sec:Prelim} for precise definitions. }
    \label{fig:matchingKI_and_matchingKK}
\end{figure}

Let us summarise these characterisations of clique-sparseness in the following theorem. 

\begin{theorem}
    \label{thm:clique-sparse}
    Let~$\mathcal{G}$ be a hereditary class of graphs. 
    Then the following statements are equivalent. 
    \begin{enumerate}
        [label=(\arabic*)]
        \item $\mathcal{G}$ is clique-sparse (i.e.~both $\reduced{\omega}{}$ and $\cideg{}$ are bounded). 
        \item There is a constant $d$ such that for every graph in~$G$, the graph obtained from successively identifying true twins in~$G$ has maximum degree~$d$. 
        \item Both $\reduced{\omega}{}$ and $\local{\alpha}{}$ are bounded in $\mathcal{G}$.
        \item Both $\reduced{\omega}{}$ and $\local{\theta}{}$ are bounded in $\mathcal{G}$.
        \item $\cdeg{}$ is bounded in $\mathcal{G}$.
        \item $\mathcal{G}$ excludes a star, a split matching, a matching between two cliques, an anti-matching between two cliques, and a half-graph between two cliques as induced subgraph. 
    \end{enumerate}
\end{theorem}

As mentioned earlier, our last result establishes a close relation between $\alpha$-treewidth and rankwidth in clique-sparse graph classes. 
In particular, we establish in \cref{sec:rankwidth} exactly which of the following: a split matching, a matching between two cliques, an anti-matching between two cliques, a half-graph between two cliques, and a star, a graph class needs to exclude in order for $\alpha$-treewidth to be equivalent to the maximum of the local independence number and the rankwidth.
Indeed, this is the case if and only if the class of graphs excludes~$P_4$ and a star, or it excludes one of each of the aforementioned graph families. 


\section{Preliminaries}
\label{sec:Prelim}

Given two integers $a,b\in\mathbb{Z},$ we denote by $[a,b]$ the set $\{ x\in\mathbb{Z} \mid a\leq x\leq b \}.$
Notice that $[a,b]$ is empty in case $b<a.$
Moreover, for a single integer $k\in\mathbb{Z},$ we denote by $[k]$ the set $[1,k].$
Unless stated otherwise, all logarithms in this paper are assumed to be binary. 

Let $G$ and $H$ be graphs and $e=xy\in E(G)$ be an edge.
We say that $H$ is obtained from $G$ by \emph{contracting} $e$ if there exists a vertex $u\in V(H)$ such that $H-u\equiv G-x-y$ and $N_H(u)= N_G(x)\cup N_G(y)$.
If $H$ is obtained from $G$ by repeatedly contracting edges, we say that $H$ is \emph{obtained from $G$ by edge contractions}.

We say that a graph $H$ is an \emph{induced minor} of a graph $G$ if $H$ can be obtained from $G$ by vertex deletions and edge contractions.

Let $G$ be a graph and $X\subseteq V(G)$.
We denote by $N_G(X)$ the \emph{neighbourhood} of $X$ in $G$, that is the set ${\{ v\in V(G)\setminus X \mid vx\in E(G)\text{ for some }x\in X \}}$. 
Moreover, $N_G[X]\coloneqq N_G(X)\cup X$ is called the \emph{closed neighbourhood} of $X$.
For a positive integer $r$, the \emph{distance-$r$-neighbourhood} of a vertex $v\in V(G)$, denoted by $N^r_G(v)$, is the set $\{ u\in V(G)\setminus\{ v\} \mid \mathsf{dist}_G(u,v)\leq r \}$.
The \emph{closed distance-$r$-neighbourhood} of $v$, denoted by $N_G^r[v]$, is the set $N_G^r(v)\cup\{ v\}$.

Let $G$ be a graph and $r\in \N$ be a positive integer.
The \emph{$r$-th power} of $G$, denoted by $G^r$, is the graph with vertex set $V(G)$ where any two distinct vertices $u,v\in V(G)$ are adjacent if and only if $\mathsf{dist}_G(u,v)\leq r$.

Let $G$ be a graph.
In what follows, we often work on the following hypergraph structure induced by the cliques of $G$.
Let $\mathcal{K}(G)$ denote the set of all vertex sets of $G$ which induce maximal cliques in $G$.
Then $(V(G),\mathcal{K}(G))$ forms a hypergraph.
As a convention, we suppress isolated vertices in hypergraphs, and thus, it suffices to denote a hypergraph as its edge set.
In particular, we can consider $\mathcal{K}(G)$ as a hypergraph. 
By slight abuse of notation, we may refer to~${K \in \mathcal{K}(G)}$ to be the maximal clique of $G$ instead of writing~$G[K]$. 

Let $\mathcal{E}$ be a hypergraph.
The \emph{linegraph} of $\mathcal{E}$, denoted by $\linegraph{\mathcal{E}}$, is the graph with vertex set $\mathcal{E}$ where two vertices $e,f\in\mathcal{E}$ are adjacent if and only if they are distinct and $e\cap f\neq \emptyset$. 

Let $k$ be a positive integer, $G$ be a graph, and $A,B \subseteq V(G)$ be sets of vertices.
An \emph{$A$-$B$-linkage} of \emph{order $k$} is a subgraph $L$ of $G$ consisting of $k$ pairwise vertex-disjoint $A$-$B$-paths.
An $A$-$B$-linkage is \emph{induced} if $L=G[V(L)]$. 

For a set~$X$, let~$K(X)$ denote the clique with vertex set~$X$. 
For two graphs~$G$ and~$H$, we define the \emph{union}~$G \cup H$ as the graph on~$V(G) \cup V(H)$ with edge set~$E(G) \cup E(H)$. 

\paragraph{Graph parameters and parametric graphs.}
A \emph{graph parameter} is a map $\mathsf{p}$ that assigns to every graph $G$ a non-negative integer value $\mathsf{p}(G)$.
Two graph parameters $\mathsf{p}$ and $\mathsf{q}$ are said to be \emph{asymptotically equivalent}, or simply \emph{equivalent}, if there exist functions $f,g\colon \N\to\N$ such that for all graphs $G$ it holds that
\begin{align*}
f(\mathsf{p}(G))\leq \mathsf{q}(G)\leq g(\mathsf{p}(G)).
\end{align*}
Let $\preceq$ be a graph containment relation.
A graph parameter $\mathsf{p}$ is said to be \emph{$\preceq$-monotone} if for every pair of graphs $H\preceq G$ it holds that $\mathsf{p}(H)\leq \mathsf{p}(G)$.

In this paper, we are mainly concerned with two graph containment relations.
The first is the \emph{induced subgraph relation}, denoted by $\InducedSubgraph$.
A graph $H$ is an \emph{induced subgraph} of a graph $G$, denoted~$H\InducedSubgraph G$, if it can be obtained from $G$ by deleting vertices.
A graph parameter $\mathsf{p}$ is said to be \emph{hereditary} if it is $\InducedSubgraph$-monotone.

The second relation is the \emph{induced minor relation}, denoted by $\InducedMinor$.
A graph $H$ is an \emph{induced minor} of a graph $G$, denoted~$H\InducedMinor G$, if it can be obtained from $G$ by a sequence of vertex deletions and edge contractions.
We say that a graph parameter $\mathsf{p}$ is \emph{induced minor monotone} if it is $\InducedMinor$-monotone.

Let $\mathsf{p}_1,\dots,\mathsf{p}_{\ell}$ be graph parameters.
We denote by $\maxP{\mathsf{p}_1,\dots,\mathsf{p}_{\ell}}{}$ the parameter defined as $\maxP{\mathsf{p}_1,\dots,\mathsf{p}_{\ell}}{G} \coloneqq \max \{ \mathsf{p}_1(G),\dots,\mathsf{p}_{\ell}(G)\}$.


For any graph parameter~$\mu$, we define a \emph{local} version of~$\mu$ via 
        \[
            \local{\mu}{G} \coloneqq \max \{ \mu(N[v]) \mid v \in V(G) \}.
        \]

\medskip

A \emph{parametric graph} is a sequence $\mathscr{H}=\langle \mathscr{H}_i\rangle_{i\in\N}$.
Given a graph containment relation $\preceq$ we say that a parametric graph $\langle \mathscr{H}_i\rangle_{i\in\N}$ is \emph{$\preceq$-monotone} if $\mathscr{H}_i\preceq \mathscr{H}_{i+1}$ for all $i\in\N$. 

Let~$\mathfrak{F}=\{ \langle\mathscr{H}^1_j\rangle_{j\in\N},\dots,\langle\mathscr{H}^{\ell}_j\rangle_{j\in\N}\}$ be a set of parametric graphs and let~$\preceq$ be a graph containment relation. 
We define the following graph parameter
\begin{align*}
\bigPG{\mathfrak{F}}{\preceq}{G}\coloneqq \max\{ k \mid \text{there exists }i\in[\ell]\text{ such that }\mathscr{H}^i_k\preceq G \}.
\end{align*}
In case $\mathfrak{F}$ contains a single parametric graph $\mathscr{H}$ we write $\bigPG{\mathscr{H}}{\preceq}{G}$ instead of $\bigPG{\mathfrak{F}}{\preceq}{G}$.

\medskip

Now, let us discuss some specific parametric graphs. 


Let~$X$ and~$Y$ be sets. 
We denote by~$K(X)$ the complete graph with vertex set~$X$ and by~$K(X,Y)$ the complete bipartite graph with bipartition classes~$X$ and~$Y$.
Now suppose~${X = \{ x_1, \dots, x_n \}}$ and~$Y = \{ y_1, \dots, y_n \}$ are ordered sets of the same size.
Then
\begin{itemize}
    \item let $\mathscr{M}(X,Y)$ denote the bipartite graph with vertex set~$X \cup Y$ and edge set~$\{ x_i y_i \mid i \in [n] \}$, which we call the \emph{matching} between~$X$ and~$Y$,
    \item let~$\mathscr{A}(X,Y)$ bipartite graph with vertex set~$X \cup Y$ and edge set~$\{ x_i y_j \mid i,j \in [n], \, i \neq j \}$, which we call the \emph{anti-matching} between~$X$ and~$Y$, and
    \item let $\mathscr{H}(X,Y)$ bipartite graph with vertex set~$X \cup Y$ and edge set~$\{ x_i y_j \mid i,j \in [n], \, i \leq j \}$, which we call the \emph{half-graph} between~$X$ and~$Y$. 
\end{itemize}

We use these notations to denote several parametric graphs, see also \cref{fig:allhedgehogs}. 
For each positive integer~$i$, let~${X_i = \{ x_1, \dots, x_i \}}$ and~$Y_i = \{ y_1, \dots, y_i \}$ denote (ordered) sets of the same size, and let~${c \notin X_i \cup Y_i}$

\begin{itemize}
    \item Let~${\Star_{i} = K(\{c\},X_i)}$ denote the \emph{star} with with~$i$ leaves, and let 
    $\Star = \langle {\Star_{i}} \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{stars}.

    \item Let~$\matchingII_i = \mathscr{M}(X_i,Y_i)$ denote the \emph{matching} of order~$i$, and let 
    $\matchingII = \langle \matchingII_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{matchings}.

    \item Let~$\matchingKI_i = \mathscr{M}(X_i,Y_i) \cup K(X_i)$ denote the \emph{split matching} of order~$i$, and let 
    $\matchingKI = \langle \matchingKI_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{split matchings}.

    \item Let~$\matchingKK_i = \mathscr{M}(X_i,Y_i) \cup K(X_i) \cup K(Y_i)$ denote the \emph{clique matching} of order~$i$, and let 
    $\matchingKK = \langle \matchingKK_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{clique matchings}.

    \item Let~$\antimatchingII_i = \mathscr{A}(X_i,Y_i)$ denote the \emph{anti-matching} of order~$i$, and let 
    $\antimatchingII = \langle \antimatchingII_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{anti-matchings}.

    \item Let~$\antimatchingKI_i = \mathscr{A}(X_i,Y_i) \cup K(X_i)$ denote the \emph{split anti-matching} of order~$i$, and let 
    $\antimatchingKI = \langle \antimatchingKI_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{split anti-matchings}.

    \item Let~$\antimatchingKK_i = \mathscr{A}(X_i,Y_i) \cup K(X_i) \cup K(Y_i)$ denote the \emph{clique anti-matching} of order~$i$, and let 
    $\antimatchingKK = \langle \antimatchingKK_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{clique anti-matchings}.

    \item Let~$\halfgraphII_i = \mathscr{H}(X_i,Y_i)$ denote the \emph{half-graph} of order~$i$, and let 
    $\halfgraphII = \langle \halfgraphII_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{half-graphs}.

    \item Let~$\halfgraphKI_i = \mathscr{H}(X_i,Y_i) \cup K(X_i)$ denote the \emph{split half-graphs} of order~$i$, and let 
    $\halfgraphKI = \langle \halfgraphKI_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{split half-graphs}.

    \item Let~$\halfgraphKK_i = \mathscr{H}(X_i,Y_i) \cup K(X_i) \cup K(Y_i)$ denote the \emph{clique half-graphs} of order~$i$, and let 
    $\halfgraphKK = \langle \halfgraphKK_i \rangle_{i \in \N}$ 
    denote the parametric graph of \emph{clique half-graphs}. 
\end{itemize}

