Let $\mathcal{C}$ be a graph class and $\preceq$ be a graph containment relation.
We say that $\mathcal{C}$ is \emph{closed under $\preceq$} if for every pair $H\preceq G$ of graphs $G\in\mathcal{C}$ implies that $H\in\mathcal{C}$.
A graph class is \emph{hereditary} if it is closed under $\InducedSubgraph$ and \emph{closed under induced minors} if it is $\InducedMinor$-closed.


\paragraph{Graph measures and tree-decompositions.}

A graph measure is a function $\mu$ that, for every graph $G$, assigns to each vertex set $X\subseteq V(G)$ a non-negative integer $\mu_G(X)$.
For the two graph parameters $\alpha$ and $\theta$ we define corresponding graph measures by $\mu_G(X)\coloneqq \mu(G[X])$ for both $\mu\in\{ \alpha,\theta\}$.
Generally, if the graph is understood from the context, we drop the subscript in this notation.
In this paper,r we are mostly concerned with the graph measures $\alpha$, $\theta$, and the \textit{cardinality}, denoted by $\abs{{}\cdot{}}$.

A \emph{tree-decomposition} for a graph $G$ is a tuple $\mathcal{T}=(T,\beta)$ where $T$ is a tree and $\beta\colon V(T)\to 2^{V(G)}$, called the \emph{bags} of $\mathcal{T}$, such that
\begin{enumerate}
	\item $\bigcup_{t\in V(T)}\beta(t)=V(G)$,
	\item for every $e\in E(G)$ there exists some $t\in V(T)$ such that $e\subseteq \beta(t)$, and
	\item for every vertex $v\in V(G)$ the set $\{ t\in V(T) \mid v\in\beta(T) \}$ induces a subtree of $T$.
\end{enumerate}
Given a graph measure $\mu$, the \emph{$\mu$-width} of $\mathcal{T}$ is defined as the value~${\max_{t\in V(T)}\mu_G(\beta(t))}$ and the $\mu$-treewidth of~$G$, denoted by $\mu$-$\mathsf{tw}(G)$, is the minimum $\mu$-width over all tree-decompositions for~$G$.

For $\mu=\abs{{}\cdot{}}$, the definition above yields a parameter which is (up to a $-1$ in the original definition) equal to \emph{treewidth}.
For $\mu=\alpha$ we obtain the definition of $\alpha$-treewidth, or sometimes called the \textit{tree-independence-number}.
Finally, for $\theta$ we obtain the notion of \emph{clique-cover-treewidth}.
In slight abuse of notation
we write $\tw{G}$ instead of $\abs{{}\cdot{}}\text{-}\tw{G}$. 

Let~$G$ be a graph and~$\mu$ be a graph measure.
A \emph{separation} in~$G$ is a tuple~${(A,B)}$ such that there is no edge between~${A \setminus B}$ and~${B \setminus A}$.
The \emph{$\mu$-order} of ${(A,B)}$ is defined to be the value~${\mu(A \cap B)}$.


\section{Clique-incidence-diversity, clique-incidence-degree, and the clique-quotient graph}
\label{sec:cid}

Let~$G$ be a graph. 
Recall that~$\mathcal{K}(G)$ denotes the set of all vertex sets of~$G$ which induce maximal cliques in~$G$.
We define an equivalence relation~$\sim_{\mathcal{K}(G)}$ on~$V(G)$ by saying that~${v \sim_{\mathcal{K}(G)} w}$ if and only if for all~${K \in \mathcal{K}(G)}$, 
\[{v \in K} \textnormal{ if and only if } {w \in K}.\]
We denote by~$\widetilde{V(G)}$ the set of equivalence classes of~$\sim_{\mathcal{K}(G)}$ and by~$\widetilde{G}$ the graph on~$\widetilde{V(G)}$ obtained from~$G$ by identifying equivalent vertices. 
We call~${\widetilde{G}}$ the \emph{clique-quotient graph} of~$G$. 
Observe that two vertices~${v,w}$ of~$G$ are equivalent, if and only if they are \emph{true twins} in~$G$, that is, for every~${x \in V(G)}$, we have that~${vx \in E(G)}$ if and only if~${vy \in E(G)}$. 
In other words, the equivalence classes are precisely the \emph{modules} of~$G$ (that are, the sets~$X$ of vertices such that each vertex outside of~$X$ is either adjacent to each vertex in~$X$ or no vertex in~$X$) that are also cliques, and the clique-quotient graph is obtained from~$G$ by contracting every such clique-module. 
Throughout this paper, for ease of notation, for each~${v \in V(G)}$, we denote by~$\widetilde{v}$ the equivalence class of~$v$ with respect to~$\sim_{\mathcal{K}(G)}$, and for~${X \subseteq V(G)}$, we denote by~${\widetilde{X}}$ the set~$X /{\sim_{\mathcal{K}(G)}} = \{ \widetilde{x} \in \widetilde{V(G)} \mid x \in X \}$. 
On the other hand, we may introduce an arbitrary vertex~${\widetilde{v} \in V(\widetilde{G})}$ without having introduced~$v$ beforehand. 
In this case, we may implicitly talk about~${v}$ as a representative of~$\widetilde{v}$. 
Similarly, we may introduce an arbitrary subset~$\widetilde{X} \subseteq V(\widetilde{G})$ without having introduced a set~$X$ beforehand. 
We often make use of the set~${\bigcup \widetilde{X} \coloneqq \{ x \in V(G) \mid \widetilde{x} \in \widetilde{X} \}}$.
Note that~${\widetilde{\bigcup \widetilde{X}} = \widetilde{X}}$. 
Additionally, when we introduce~$\widetilde{X} \subseteq V(\widetilde{G})$ for a set~$X$ of representatives, then we take~$X$ to be a set that, for each~$\widetilde{x} \in \widetilde{X}$, contains exactly one element of~$\widetilde{x}$. 

Let~${x,y \in V(G)}$ with~${x \not\sim_{\mathcal{K}(G)} y}$. 
By definition of~$\widetilde{G}$, we have
\begin{equation}
    {xy \in E(G)} \,\text{ if and only if }\, \widetilde{x}\widetilde{y} \in E(\widetilde{G}). \tag{$\ast$} \label{eq:ast}
\end{equation}
Expanding on this idea, we observe the following. 

\begin{observation}
    \label{obs:GtildeEdges}
    Let~$G$ be a graph, let~${X,Y \subseteq V(G)}$. 
    Then the following properties hold. 
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{obs:GtildEedges:1} There is an edge between~$\widetilde{X}$ and~$\widetilde{Y}$ in~$E(\widetilde{G})$ if and only if there is an edge between~$\bigcup \widetilde{X}$ and~$\bigcup \widetilde{Y}$ in~$E(G)$. 
        \item \label{obs:GtildEedges:2} If there is an edge between~$\widetilde{X}$ and~$\widetilde{Y}$ in~$E(\widetilde{G})$, then there is an edge between~$X$ and~$Y$ in~$E(G)$. 
        \item \label{obs:GtildEedges:3} If there is an edge between~$X$ and~$Y$ in~$E(G)$, then either there is an edge between~$\widetilde{X}$ and~$\widetilde{Y}$ in~$E(\widetilde{G})$, or a vertex in~$\widetilde{X} \cap \widetilde{Y}$.
    \end{enumerate}
\end{observation}

\begin{proof}
    Let~${x \in X}$ and~${y \in Y}$ with~${x \not\sim_{\mathcal{K}(G)} y}$. 
    By~(\cref{eq:ast}), ${xy \in E(G)}$ if and only if~${\widetilde{x}\widetilde{y} \in E(\widetilde{G})}$. 
    And since~${x \in \bigcup \widetilde{X}}$ and~${y \in \bigcup \widetilde{Y}}$, \ref{obs:GtildEedges:1} follows. 
    For~\ref{obs:GtildEedges:2}, if~${\widetilde{x}\widetilde{y} \in E(\widetilde{G})}$ for some~${\widetilde{x} \in \widetilde{X}}$ and~${\widetilde{y} \in \widetilde{Y}}$, then by definition there is an~${x' \in X \cap \widetilde{x}}$ and~${y' \in Y \cap \widetilde{Y}}$, and it follows that~${xy \in E(G)}$. 
    Finally, if~${xy \in E(G)}$ for some~${x \in X}$ and~${y \in Y}$, then either~${x \not \sim_{\mathcal{K}(G)} y}$ and hence~${\widetilde{x}\widetilde{y} \in E(\widetilde{G})}$ by~(\cref{eq:ast}), or~${x \sim_{\mathcal{K}(G)} y}$ and hence~$\widetilde{x} \in \widetilde{X} \cap \widetilde{Y}$, proving \ref{obs:GtildEedges:3}.
\end{proof}

For a maximal clique~${K \in \mathcal{K}(G)}$, we call the number of equivalence classes of~$\sim_{\mathcal{K}(G)}$ that intersect~$K$ the \emph{incidence-diversity} of~$K$. 
Then, the \emph{clique-incidence-diversity} of~$G$ is the maximum incidence-diversity over all~${K \in \mathcal{K}(G)}$, which we denote by~$\reduced{\omega}{G}$. 

For a vertex~${v \in V(G)}$, we call the number of maximal cliques $K\in\mathcal{K}(G)$ with $v\in K$ the \emph{clique-incidence-degree} of~$v$.
The \emph{clique-incidence-degree} of~$G$ is the maximum clique-incidence-degree over all~${v \in V(G)}$, which we denote by~$\cideg{G}$. 
Note that~$\cideg{G}$ is equal to the maximum degree of the hypergraph~${\mathcal{K}(G)}$. 

A key observation on the behaviour of~$\sim_{\mathcal{K}(G)}$ is that taking its quotient preserves a lot of the original structure of~$G$ from the perspective of maximal cliques.
We illustrate this behaviour with the following observations.

\begin{lemma}
    \label{lem:clique-quotient-graph}
    For every graph~$G$, the map~${\widetilde{\pi} \colon V(G) \to V(\widetilde{G})}$ that maps every vertex~$v$ of~$G$ to its equivalence class~$\widetilde{v}$ with respect to~$\sim_{\mathcal{K}(G)}$ induces a bijection~$\kappa$ between~${\mathcal{K}(G)}$ and~${\mathcal{K}(\widetilde{G})}$. 

    In particular, 
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{item:lem:clique-quotient-graph1} $\kappa$ is an isomorphism between~$\linegraph{\mathcal{K}(G)}$ and~$\linegraph{\mathcal{K}(\widetilde{G})}$, 
    \end{enumerate}
    and, for every set~$R$ of representatives of the equivalence classes of~$\sim_{\mathcal{K}(G)}$, 
    \begin{enumerate}
        [label=(\arabic*), resume]
        \item \label{item:lem:clique-quotient-graph2} the restriction of~$\widetilde{\pi}$ to~$R$ is an isomorphism between the hypergraph ${\mathcal{K}(\widetilde{G})}$ and the subhypergraph of~$\mathcal{K}(G)$ induced by~$R$, and
        \item \label{item:lem:clique-quotient-graph3} the restriction of~$\widetilde{\pi}$ to~$R$ is an isomorphism between $\widetilde{G}$ and~$G[R]$. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    By (\cref{eq:ast}), ${\widetilde{\pi}(K) = \widetilde{K}}$
    induces a maximal clique of~$\widetilde{G}$ for every~${K \in \mathcal{K}(G)}$. 
    On the other hand, $\widetilde{x}$ induces a clique for each~${x \in V(G)}$. 
    So for each~${\widetilde{K} \in \mathcal{K}(\widetilde{G})}$, the union~$\bigcup \widetilde{K}$ is a clique of~$G$. 
    Straightforwardly, the maximality of~$\widetilde{G}[\widetilde{K}]$ implies the maximality of~$G[\bigcup \widetilde{K}]$. 

    Clearly, for~${K, K' \in \mathcal{K}(G)}$ we observe that~${K \cap K' = \emptyset}$ if and only if~${\widetilde{K} \cap \widetilde{K'} = \emptyset}$, and hence~$\linegraph{\mathcal{K}(G)}$ is isomorphic to~$\linegraph{\mathcal{K}(\widetilde{G})}$. 

    Lastly, observe that if~$R$ is a set of representatives of the equivalence classes with respect to~$\sim_{\mathcal{K}(G)}$, then the restriction of~$\widetilde{\pi}$ to~$R$ is a bijection, and hence, by the reasoning above, an isomporphism between the subhypergraph of~$\mathcal{K}(G)$ induced by~$R$ and~$\mathcal{K}(\widetilde{G})$, as well as~$\widetilde{G}$ and~$G[R]$. 
\end{proof}

A straightforward consequence of this lemma is that the clique-incidence-diversity~$\reduced{\omega}{G}$ of a graph~$G$ is equal to the clique number~$\omega(\widetilde{G})$ of~$\widetilde{G}$.
Indeed, it follows that several graph parameters on~$G$ and~$\widetilde{G}$ are equal, as we summarise in the following corollary.

\begin{corollary}
    \label{cor:Gtildeproperties}
    Let~$G$ be a graph.
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{item:cor:Gtildeproperties1} ${\reduced{\omega}{G} = \omega(\widetilde{G})}$. 
        \item \label{item:cor:Gtildeproperties2} ${\cideg{G} = \cideg{\widetilde{G}}}$.
        \item \label{item:cor:Gtildeproperties3} ${\alpha(G) = \alpha(\widetilde{G})}$ 
            and~${\local{\alpha}{G} = \local{\alpha}{\widetilde{G}}}$.
        \item \label{item:cor:Gtildeproperties5} ${\theta(G) = \theta(\widetilde{G})}$ 
            and~${\local{\theta}{G} = \local{\theta}{\widetilde{G}}}$.
    \end{enumerate}
\end{corollary}

\begin{proof}
    The bijection~$\kappa$ from \cref{lem:clique-quotient-graph} maps a maximal clique~${K \in \mathcal{K}(G)}$ to~${\widetilde{K}}$. 
    Since the latter has exactly as many vertices as~$K$ contains equivalence classes of~$\sim_{\mathcal{K}(G)}$, it follows that~${\reduced{\omega}{G} = \omega(\widetilde{G})}$. 

    Property~\ref{item:cor:Gtildeproperties2} follows immediately from \cref{lem:clique-quotient-graph}\ref{item:lem:clique-quotient-graph1} together with the fact that the maximum degree of a hypergraph is equal to the clique number of its linegraph. 

    Since every independent set of~$G$ contains at most one vertex from each equivalent class of~$\sim_{\mathcal{K}(G)}$, it follows from \cref{lem:clique-quotient-graph}\ref{item:lem:clique-quotient-graph3} that~${\alpha(G) = \alpha(\widetilde{G})}$. 
    Similarly, as we may assume 
    a clique-cover to consist only of maximal cliques, it follows from \cref{lem:clique-quotient-graph}\ref{item:lem:clique-quotient-graph1} that~${\theta(G) = \theta(\widetilde{G})}$. 
    From these observations, it immediately follows that the local variants of both of these parameters are also equal on~$G$ and~$\widetilde{G}$. 
\end{proof}

For any graph parameter~$\mu$, let~$\reduced{\mu}{}$ be the graph parameter defined by~${\reduced{\mu}{G} \coloneqq \mu(\widetilde{G})}$. 
In particular, let us turn our attention to the maximum degree of the clique-quotient graph, that is, the graph parameter~$\reduced{\Delta}{}$, and its interaction with both the clique-incidence-diversity and the clique-incidence-degree. 


\begin{lemma}
    \label{lem:cidcidegdelta}
    For every graph~$G$, 
    \begin{enumerate}
        [label=(\arabic*)]
        \item ${\reduced{\omega}{G} \leq \reduced{\Delta}{G}}$, unless~$\widetilde{G}$ is edgeless (in which case~${\reduced{\omega}{G} \leq 1}$ and~${\reduced{\Delta}{G} = 0}$), 
        \item ${\cideg{G} \leq 3^{\lceil{\reduced{\Delta}{G}/3}\rceil}}$, and
        \item ${\reduced{\Delta}{G} \leq \cideg{G} \cdot (\reduced{\omega}{G} - 1)}$. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    Clearly, ${\reduced{\omega}{G} \leq \reduced{\Delta}{G} + 1}$. 
    Suppose~$G$ is a graph for which~${k \coloneqq \reduced{\omega}{G} = \reduced{\Delta}{G} + 1}$. 
    In particular, $\widetilde{G}$ contains a clique~$\widetilde{K}$ of size~$k$. 
    Since~${\Delta(\widetilde{G}) = k - 1}$, each vertex in~$\widetilde{K}$ has degree~${k-1}$ in~$\widetilde{G}$, and hence~${\widetilde{G}[\widetilde{K}]}$ is a component of~$\widetilde{G}$. 
    But since no other maximal clique of~$G$ intersects~${K \coloneqq \bigcup\widetilde{K}}$, all vertices in~$K$ are equivalent, and hence~${k = 1}$. 
    It follows that~${\Delta(\widetilde{G}) = 0}$, and hence~$\widetilde{G}$ is edgeless. 

    To show that $\cideg{G} \leq 3^{\lceil{\reduced{\Delta}{G}}/3\rceil}$, first recall that~$\cideg{G} = \cideg{\widetilde{G}}$, see \cref{cor:Gtildeproperties}. 
    Moreover, for every vertex~${\widetilde{v} \in V(\widetilde{G})}$, every~${\widetilde{K} \in \mathcal{K}(\widetilde{G})}$ that contains~$\widetilde{v}$ is contained in~$N_{\widetilde{G}}[\widetilde{v}]$. 
    In particular, the number of maximal cliques that contain~$\widetilde{v}$ is equal to the number of maximal cliques of~${G[N_{\widetilde{G}}(\widetilde{v})]}$. 
    Using the bound of Moon and Moser~\cite{MoonM1965cliques} that an~$n$-vertex graph contains at most~$3^{\lceil n/3 \rceil}$ maximal cliques, we obtain the desired bound. 

    For the third inequality, consider a vertex~${\widetilde{v} \in V(\widetilde{G})}$. 
    By \cref{lem:clique-quotient-graph}, $\widetilde{v}$ is adjacent to exactly those~$\widetilde{w}$ for which there is a maximal clique~${K \in \mathcal{K}(G)}$ with~${\widetilde{v} \cup \widetilde{w} \subseteq K}$. 
    And since there are at most~$\cideg{G}$ such maximal cliques, each of which contains at most~$(\reduced{\omega}{G} - 1)$ equivalence classes that are distinct from~$\widetilde{v}$, the result follows. 
\end{proof}

First, let us observe that all these inequalities are tight. 
For the first inequality, consider~$\matchingKI_n$, where~${\reduced{\omega}{\matchingKI_n} = \reduced{\Delta}{\matchingKI_n} = n}$. 
For the second inequality, consider the graph~$G$ obtained from a complete multipartite graph with~$n$ partition classes, each of size~$3$, by adding a universal vertex. 
Clearly, this graph has~$3^n$ maximal cliques (cf.~Moon and Moser~\cite{MoonM1965cliques}) which, furthermore, distinguish all vertices with respect to~$\sim_{\mathcal{K}(G)}$. 
Hence~${G = \widetilde{G}}$ and hence~${\reduced{\Delta}{G} = \Delta(G) = 3n}$. 
For the third inequality, observe that~${\reduced{\Delta}{\Star_n} = \Delta(\Star_n) = n = \cideg{\Star_n}}$ and that~${\reduced{\omega}{\Star_n} = \omega(\Star_n) = 2}$.


The first two inequalities from the previous lemma imply that~${\maxP{\cideg{},\reduced{\omega}{}}{G} \leq 3^{\lceil{\reduced{\Delta}{G}/3}\rceil}+1}$ for all graphs~$G$.
So in particular, the class of all graphs with~${\maxP{\cideg{},\reduced{\omega}{}}{}}$ at most~${3^{\lceil{d/3}\rceil}+1}$ is strictly more general than the class of graph of maximum degree at most~$d$. 
Moreover, $\matchingKI_n$ is a graph with~${\cideg{\matchingKI_n} = 2}$ and~${\reduced{\Delta}{\matchingKI_n} = \reduced{\omega}{\matchingKI_n} = n}$, while~$\Star_n$ is a graph with~${\reduced{\omega}{\Star_n} = 2}$ and~${\reduced{\Delta}{\Star_n} = \cideg{\Star_n} = n}$. 
Hence, bounding either~$\cideg{}$ or~$\reduced{\omega}{}$ while not bounding the other leads to a class strictly less general than bounding~$\reduced{\Delta}{}$. 
From the first inequality of the previous lemma, we observe that~$\reduced{\Delta}{}$ and~$\maxP{\reduced{\Delta}{},\reduced{\omega}{}}{}$ are equivalent. 
Together with the third inequality, we observe that~$\reduced{\Delta}{}$ is equivalent to~$\maxP{\cideg{},\reduced{\omega}{}}{}$. 

\begin{corollary}
    \label{cor:cid-cideg-Deltatilde}
    The parameters~$\reduced{\Delta}{}$ and~$\maxP{\cideg{},\reduced{\omega}{}}{}$ are equivalent. 
    \qed
\end{corollary}

\section{An approximate Menger theorem and an induced grid theorem on graphs with bounded clique-incidence-diversity and bounded clique-incidence-degree}

Let us first prove the generalisation of \cref{thm:gartlandinducedmenger} to graphs of bounded $\maxP{\cideg{},\reduced{\omega}{}}{}$. 
To that end, we first investigate how separations and paths relate between~$G$ and~$\widetilde{G}$ in the following two lemmas. 

\begin{lemma}
    \label{lemma:quotientseparations}
    Let~$k$ be a positive integer.
    For any graph~$G$, 
    \begin{enumerate}
        [label=(\arabic*)]
        \item if $(A,B)$ is a separation of~$G$ of $\theta$-order~$k$, then~$(\widetilde{A}, \widetilde{B})$ is a separation of~$\widetilde{G}$ of order at most~$k \cdot \reduced{\omega}{G}$, and
        \item if $(\widetilde{A},\widetilde{B})$ is a separation in~$\widetilde{G}$ of order~$k$, then $(\bigcup\widetilde{A},\bigcup\widetilde{B})$ is a separation in $G$ of $\theta$-order at most~$k$. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    By \cref{obs:GtildeEdges}\ref{obs:GtildEedges:3} and since~$\widetilde{A} \setminus \widetilde{B}$ and~$\widetilde{B} \setminus \widetilde{A}$ are disjoint, if~$(A,B)$ is a separation of~$G$, then~$(\widetilde{A}, \widetilde{B})$ is a separation of~$\widetilde{G}$. 
    More straight-forwardly, by \cref{obs:GtildeEdges}\ref{obs:GtildEedges:1}, if~$(\widetilde{A},\widetilde{B})$ is a separation in~$\widetilde{G}$, then  $(\bigcup\widetilde{A},\bigcup\widetilde{B})$ is a separation of~$G$. 
    Moreover, if there is an edge between~${\bigcup \widetilde{A} \setminus \bigcup \widetilde{B}}$ and~${\bigcup \widetilde{B} \setminus \bigcup \widetilde{A}}$, then there is an edge between~${A \setminus B}$ and~${B \setminus A}$.
    So in particular, if~$(\widetilde{A},\widetilde{B})$ is a separation of~$\widetilde{G}$, then~$(\bigcup\widetilde{A},\bigcup\widetilde{B})$ is a separation of~$G$, and if~$(A,B)$ is a separation of~$G$, then~$(\widetilde{A},\widetilde{B})$ is a separation of~$\widetilde{G}$. 

    So let~${(A,B)}$ be a separation of~$G$ with~${\theta(G[A \cap B]) = k}$, and let~${\{ K^1, \dots, K^k \}}$ be a clique-cover of~${G[A \cap B]}$. 
    Then by \cref{lem:clique-quotient-graph}, ${\{ \widetilde{K}^1, \dots, \widetilde{K}^k \}}$ is a clique-cover of~${\widetilde{G}[\widetilde{A} \cap \widetilde{B}}]$. 
    With \cref{cor:Gtildeproperties}\ref{item:cor:Gtildeproperties1}, if follows that~${\abs{\widetilde{A} \cap \widetilde{B}} \leq k \cdot \reduced{\omega}{G}}$. 

    Finally, let~${(\widetilde{A},\widetilde{B})}$ be a separation of~$\widetilde{G}$ of order~$k$. 
    Since~$G[\widetilde{x}]$ is a clique for each~$\widetilde{x} \in \widetilde{A} \cap \widetilde{B}$, ${\{G[\widetilde{x}] \mid x \in \widetilde{A} \cap \widetilde{B} \}}$ is a clique-cover of~${A \cap B}$ of size~$k$, so~${\theta(G[A \cap B]) \leq k}$.
\end{proof}

\begin{lemma}
    \label{lemma:quotientpahts}
    Let~$\ell$ be a positive integer.
    For every graph~$G$, 
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{item:lemma:quotientpahts1} if ${x_1 x_2 \dots x_\ell}$ is an induced path in~$G$ and~${\ell \geq 3}$, then ${\widetilde{x_1} \widetilde{x_2} \dots \widetilde{x_\ell}}$ is an induced path in~$\widetilde{G}$, and
        \item \label{item:lemma:quotientpahts2} if $\widetilde{x_1} \widetilde{x_2} \dots \widetilde{x_\ell}$, then, for each set~${\{ r_1, r_2, \dots, r_\ell \}}$ with~${r_i \in \widetilde{x_i}}$ for all~${i \in [\ell]}$, we have that~${r_1 r_2 \dots r_\ell}$ is an induced path in~$G$.
    \end{enumerate}
\end{lemma}

\begin{proof}
     \ref{item:lemma:quotientpahts2} immediately follows from (\cref{eq:ast}). 
     For \ref{item:lemma:quotientpahts1}, by (\cref{eq:ast}), it suffices to show is that no two vertices of the path are equivalent with respect to~$\sim_{\mathcal{K}(G)}$.
     This is clear for vertices that are not adjacent, so fix some arbitrary~${i,j \in [\ell]}$ with~${i < j}$ and $\abs{i-j} = 1$. 
     Since~${\ell \geq 3}$ and the path is induced, there is a~${k \in [\ell] \setminus \{i,j\}}$ such that~${x_k}$ is adjacent to exactly one of~${x_i, x_j}$.
     % \MH{This argument fails for $\ell=3$.
     % Isn't the general argument that "$x_ix_j \notin E(G)$ implies $x_i \not\sim_{\mathcal{K}(G)} x_j$ and thus, by \cref{eq:ast}, also $\widetilde{x_i}\widetilde{x_j} \notin E(\widetilde{G})$." not the easier argument anyways?}
     Hence, $x_i$ and~$x_j$ are not true twins, and therefore~${x_i \not \sim_{\mathcal{K}(G)} x_j}$. 
\end{proof}

Now, we can prove \cref{thm:hedgehogmenger}. 

\hedgehogmenger*

\begin{proof}
    Let~$G$ be a graph with ${\reduced{\omega}{G} \leq s}$ and~${\cideg{G} \leq t}$, and let~${A,B \subseteq V(G)}$. 
    By \cref{lem:cidcidegdelta}, ${\Delta(\widetilde{G}) \leq t(s-1)}$. 
    We apply \cref{thm:gartlandinducedmenger} to~$\widetilde{G}$ and~${\widetilde{A}, \widetilde{B}}$ to find, for each positive integer~$k$, either an induced $\widetilde{A}$-$\widetilde{B}$-linkage~${\widetilde{\mathcal{L}}}$ of order~$k$ or a set~$\widetilde{S}$ of size at most~${k \cdot (t(s-1) + 1)^{t^2(s-1)^2 + 1}}$ such that there does not exist an~$\widetilde{A}$-$\widetilde{B}$-path in~$\widetilde{G} - \widetilde{S}$. 

    Let~${\widetilde{\mathcal{L}}}$ be an $\widetilde{A}$-$\widetilde{B}$-linkage of order~$k$. 
    For each~$P \in \widetilde{\mathcal{L}}$, fix a set~$R_P$ of representatives of the equivalence classes in~$V(\widetilde{P})$ with the additional property that for the startvertex in~$\widetilde{A}$, we pick a representative in~$A$ and for the endvertex in~$\widetilde{B}$, we pick a representative in~$B$. 
    By \cref{lemma:quotientpahts}, each~$G[R_P]$ is an induced $A$-$B$-path. 
    Note that since~$\widetilde{\mathcal{L}}$ is an induced $\widetilde{A}$-$\widetilde{B}$-linkage, for distinct~$P,Q \in \widetilde{\mathcal{L}}$, we observe that no vertex in~$R_P$ is equivalent to a vertex in~$R_Q$. 
    So in particular, $R_P$ and~$R_Q$ are disjoint, and by \cref{obs:GtildeEdges}\ref{obs:GtildEedges:3}, there is no edge between~$R_P$ and~$R_Q$ in~$E(G)$. 
    Hence, ${\mathcal{L} \coloneqq \{ G[R_P] \mid P \in \widetilde{\mathcal{L}}\}}$ is an $A$-$B$-linkage in~$G$ of order~$k$. 

    Lastly, let~$\widetilde{S}$ be a set of size at most~${k \cdot (t(s-1) + 1)^{t^2(s-1)^2 + 1}}$ such that there does not exist an~$\widetilde{A}$-$\widetilde{B}$-path in~$\widetilde{G} - \widetilde{S}$. 
    Let~$(\widetilde{X},\widetilde{Y})$ be a separation of~$\widetilde{G}$ with~${\widetilde{A} \subseteq \widetilde{X}}$, ${\widetilde{B} \subseteq \widetilde{Y}}$, and~$\widetilde{S} = \widetilde{X} \cap \widetilde{Y}$. 
    By \cref{lemma:quotientseparations}, the separation $(\bigcup \widetilde{X}, \bigcup \widetilde{Y})$ is a separation with~${A \subseteq \bigcup \widetilde{X}}$, ${B \subseteq \widetilde{Y}}$, and for~${S \coloneqq \widetilde{X} \cap \widetilde{Y}}$, we have~$\theta(G[S]) \leq (t(s-1) + 1)^{t^2(s-1)^2 + 1}$, as desired. 
\end{proof}



\section{Comparison with other graph parameters}
\label{sec:parametercomp}

In this section, we further analyse how the graph parameters of clique-incidence degree and clique-incidence diversity relate to other parameters to obtain further characterisations for clique-sparse graph classes. 

\begin{lemma}
    \label{lem:parameterinequalities-1}
    For every graph~$G$ holds 
    \[
        \local{\alpha}{G} 
        \leq \local{\theta}{G}
        \leq \cideg{G}.
    \]
\end{lemma}

\begin{proof}
    To show ${\local{\alpha}{G} \leq \local{\theta}{G}}$, notice that each leaf of a maximal induced star needs to be covered by a distinct clique in any clique-cover. 

    For the inequality ${\local{\theta}{G} \leq \cideg{G}}$, 
    notice that every vertex~$v$ is a dominating vertex of the graph induced by the closed neighbourhood of~$v$.
    Thus, for every clique~$K$ of~$G[N_G[v]]$, we observe that~${G[V(K) \cup \{v\}]}$ is a clique as well. 
    In particular, the set~${\{ G[K \cap N_G[v]] \colon K \in \mathcal{K}(G) \textnormal{ with } v \in K \}}$ is a
    clique-cover of~${G[N_G[v]]}$. 
\end{proof}

Note that all these inequalities are tight, as witnessed by trees.
On the other hand, for each of the inequalities, there exist graphs where the difference is arbitrarily large. 
For the first inequality, consider a graph obtained from the complement of a graph, which is both triangle-free and has arbitrarily large chromatic number (cf.~Erd\H{o}s~\cite{Erdos1959}), by adding a universal vertex.
For the difference between~$\local{\theta}{}$ and~$\cideg{}$, note that~$\antimatchingKK_n$ is a graph with~${\local{\theta}{\antimatchingKK_n} = 2}$ and~${\cideg{\antimatchingKK_n} = 2^{n-1}}$.

\begin{lemma}
    \label{lem:parameterinequalities-2}
    For every graph~$G$ holds
    \[
        \reduced{\Delta}{G} \leq \local{\alpha}{G}^{\reduced{\omega}{G}}.
    \]
\end{lemma}

\begin{proof}
    Let~$G$ be a graph,
    let~${s \coloneqq \local{\alpha}{G}}$, and let~${d \coloneqq \reduced{\omega}{G}}$. 
    Consider some vertex~${\widetilde{v} \in V(\widetilde{G})}$. 
    Let $T$ be the $s$-ary tree of height~$d$ and for each node~${t \in V(T)}$, let~$P_t$ denote the unique path in~$T$ from the root~$r$ of~$T$ to~$t$.

    We construct a labelling~$\lambda$ of some nodes of $T$ with vertices of~$\widetilde{G}$ such that every vertex in~$N_{\widetilde{G}}(v)$ appears as a label, proving that~${\deg{\widetilde{v}} \leq s^d}$.  
    We start by defining~$\lambda(r) \coloneqq \widetilde{v}$. 
    Assume for a node~$t$ that~$\lambda(t')$ is already defined for each~${t' \in V(P_t)}$. 
    We then label a set of children of~$t$ with a maximum independent set in~${\bigcap \{N_{\widetilde{G}}(\lambda(t')) \mid t' \in V(P_t) \}}$, and leave all other children unlabelled. 
    Continuing this process, we obtain a labelled subtree~$T'$ of~$T$ with the property that for each node~${t \in V(T')}$, each~$\lambda(V(P_t))$ is a clique of~$\widetilde{G}$ and for the set~$C_t$ of children of~$t$ in~$T'$, we have that~$\lambda(C_t)$ is a maximum independent set in the common neighbourhood of~$V(P_t)$.

    Assume for a contradiction that some~${\widetilde{w} \in N_{\widetilde{G}}(\widetilde{v})}$ is not used as a label in $T'$. 
    Let~$t$ be maximal in the tree order such that~$\widetilde{w}$ is adjacent to~$\lambda(t')$ for every node~${t' \in V(P_t)}$. 
    If~$t$ is not a leaf of~$T'$, then, since the set~$\lambda(C_t)$ is a maximum independent set in the common neighbourhood of~$V(P_t)$, there is a child~$t'$ of~$t$ in~$T'$ such that~$\widetilde{w}$ is adjacent to~$\lambda(t')$, contradicting the maximal choice of~$t$. 
    If~$t$ is a leaf of~$T'$ but not a leaf of~$T$, then, by construction, the common neighbourhood of~$V(P_t)$ is empty, a contradiction. 
    But then, $t$ is a leaf of~$T$ and ${\lambda(V(P_t)) \cup \{\widetilde{w}\}}$ is a clique in~$\widetilde{G}$ of size~${d+1}$, a contradiction. 
    Hence, $\reduced{\Delta}{G} \leq s^{d}$, as desired. 
\end{proof}

Another auxiliary graph and parameter that may naturally come to mind in connection with these graphs is the maximum degree of the linegraph~$\linegraph{\mathcal{K}(G)}$ of the clique-hypergraph of~$G$, which we call the \emph{clique-degree}, denoted by~$\cdeg{G}$. 
We observe the following inequalities. 

\begin{lemma}
    \label{obs:CID+CIDEGvsCDEG}
    For every graph~$G$, 
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{item:obs:CID+CIDEGvsCDEG-1} ${\cdeg{G} \leq \reduced{\omega}{G} \cdot  (\cideg{G}-1)}$, 
        \item \label{item:obs:CID+CIDEGvsCDEG-2} ${\reduced{\omega}{G} \leq 2^{\cdeg{G}}}$, and 
        \item \label{item:obs:CID+CIDEGvsCDEG-3} ${\cideg{G} \leq \cdeg{G}+1}$. 
    \end{enumerate}  
\end{lemma}

\begin{proof}
    Consider a maximal clique~${K \in \mathcal{K}(G)}$, and let~$\mathcal{N}$ denote the set of maximal cliques that intersect~$K$ but are not equal to~$K$. 

    For \ref{item:obs:CID+CIDEGvsCDEG-1}, note that the number of maximal cliques in~$\mathcal{N}$ that intersect a fixed equivalence class is at most~$\cideg{G}-1$. 
    Hence, ${\abs{\mathcal{N}} \leq \reduced{\omega}{G} \cdot (\cideg{G}-1)}$. 

    For \ref{item:obs:CID+CIDEGvsCDEG-2}, note that the intersection of every equivalence class of~$\sim_{\mathcal{K}(G)}$ with~$K$ is described precisely by a subset of~$\mathcal{N}$ that contains the class. 
    Hence, the clique-incidence-diversity of~$K$ is at most~$2^{\cdeg{G}}$. 

    Moreover, for \ref{item:obs:CID+CIDEGvsCDEG-3}, each vertex of~$K$ is contained in~$K$ and at most~$\cdeg{G}$ many other maximal cliques, hence~${\cideg{G} \leq \cdeg{G}+1}$.
\end{proof}

As we observed above,~$\local{\alpha}{}$, $\local{\theta}{}$, and~$\cideg{}$ are not equivalent. 
But with \cref{lem:parameterinequalities-1,lem:parameterinequalities-2}, as well as \cref{cor:cid-cideg-Deltatilde}, we conclude the following equivalences of parameters. 


\begin{corollary}
    \label{cor:parameterequivalence1}
    The parameters~$\reduced{\Delta}{}$, 
    $\cdeg{}$, 
    $\maxP{\cideg{}, \reduced{\omega}{}}{}$,
    $\maxP{\local{\alpha}{}, \reduced{\omega}{}}{}$, and
    $\maxP{\local{\theta}{}, \reduced{\omega}{}}{}$
    are equivalent. 
    \qed
\end{corollary}



\section{An induced grid theorem on graphs with bounded clique-incidence-diversity and bounded local independence number}

Next, we prove the generalisation of \cref{thm:maxdegreegridtheorem} to graphs of bounded $\maxP{\reduced{\omega}{},\local{\alpha}{}}{}$. 
To that end, we first investigate how certain width parameters relate between~$G$ and~$\widetilde{G}$. 

\begin{lemma}
    \label{lemma:width-comparison}
    For every graph~$G$,
    \begin{enumerate}
        [label=(\arabic*)]
        \item \label{item:lemma:width-comparison0} ${\ptw{\alpha}{G} = \ptw{\alpha}{
        \widetilde{G}}}$ and~${\ptw{\theta}{G} = \ptw{\theta}{\widetilde{G}}}$, 
        \item \label{item:lemma:width-comparison1} $\ptw{\alpha}{G} \leq \ptw{\theta}{G} \leq \reduced{\tw{}}{G}$, 
        \item \label{item:lemma:width-comparison2} $\reduced{\tw{}}{G} \leq \ptw{\theta}{G} \cdot \reduced{\omega}{G}$, and 
        \item \label{item:lemma:width-comparison3} $\reduced{\tw{}}{G} \leq \ptw{\alpha}{G} \cdot \reduced{\Delta}{G}$. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    For \ref{item:lemma:width-comparison0} we first look at a way to turn a tree-decomposition of~$G$ into one of~$\widetilde{G}$ and vice versa. 
    Moreover, both of these constructions preserve both the $\alpha$-width and the $\theta$-width of the original tree-decomposition. 

    Let~$(T,\beta)$ be a tree-decomposition of~$G$. 
    Then we define~$\widetilde{\beta}$ by setting~${\widetilde{\beta}(t) \coloneqq \{ \widetilde{v} \mid v \in \beta(t) \}}$. 
    We claim that~${(T,\widetilde{\beta})}$ is a tree-decomposition of~$\widetilde{G}$. 
    Clearly, the first two properties of a tree-decomposition follow directly from the fact that~$(T,\beta)$ is a tree-decomposition. 
    So consider a vertex~${\widetilde{v} \in V(\widetilde{G})}$ and assume for a contradiction that~${\{ t \in V(T) \mid v \in \widetilde{\beta}(t) \}}$ induces a disconnected subforest of~$T$. 
    Then there is a node~$t'$ of~$T$ such that~$\widetilde{v}$ is not in~$\widetilde{\beta}(t)$, but two distinct components of~${T - t'}$ contain nodes~$t_1$ and~$t_2$ with~${\widetilde{v} \in \widetilde{\beta}(t_1) \cap \widetilde{\beta}(t_2)}$. 
    So $\beta(t_1)$ contains a vertex~$v_1$ and~$\beta(t_2)$ contains a vertex~$v_2$, both equivalent to~$v$, while~$\beta(t')$ does not contain any node equivalent to~$v$. 
    In particular, the subtree induced by~${\{ t \in V(T) \mid v_1 \in \beta(t) \}}$ and the subtree induced by~${\{ t \in V(T) \mid v_2 \in \beta(t) \}}$ are contained in distinct components of~${T - t'}$. 
    But then, no bag of~$(T,\beta)$ contains the edge~$v_1v_2$, contradicting that~$(T,\beta)$ is a tree-decomposition. 
    It is easy to see that~$\widetilde{G}[\widetilde{\beta}(t)]$ is isomorphic to~$\widetilde{G[\beta(t)]}$. 
    So the fact that the $\alpha$- and $\theta$-width of~$(T,\beta)$ and~$(T,\widetilde{\beta})$ are the same follows from \cref{cor:Gtildeproperties}. 

    On the other hand, let~$(T,\beta)$ be a tree-decomposition of~$\widetilde{G}$. 
    We define~$\overline{\beta}$ by setting~${\overline{\beta}(t) \coloneqq \{ v \mid \widetilde{v} \in \beta(t) \}}$. 
    Now~${(T,\overline{\beta})}$ is a tree-decomposition of~$G$ as all the properties follow directly from the fact that~$(T,\beta)$ is a tree-decomposition.
    Similar to before, $\widetilde{G}[\beta(t)]$ is isomorphic to~$\widetilde{G[\overline{\beta}(t)]}$.
    So the fact that the $\alpha$- and $\theta$-width of~$(T,\beta)$ and~$(T,\overline{\beta})$ are the same follows again from \cref{cor:Gtildeproperties}. 

    Both constructions together show \ref{item:lemma:width-comparison0}. 

    Towards \ref{item:lemma:width-comparison1}, note that since the size of a maximum independent set is at most as large as a smallest clique-cover, we observe that~$\ptw{\alpha}{G} \leq \ptw{\theta}{G}$. 
    And since clearly~$\ptw{\theta}{\widetilde{G}} \leq \tw{\widetilde{G}}$, \ref{item:lemma:width-comparison1} follows from~\ref{item:lemma:width-comparison0}. 

    Now \ref{item:lemma:width-comparison2} and \ref{item:lemma:width-comparison3} follow with~\ref{item:lemma:width-comparison0} directly from the facts that~${\abs{V(G)} \leq \alpha(G) \Delta(G)}$ and~${\abs{V(G)} \leq \theta(G) \omega(G)}$ for every graph~$G$. 
\end{proof}

Using the established relations, we finally prove \cref{thm:hedgehoggrid}. 

\hedgehoggrid*

\begin{proof}
    Let $f'$ be the function from \cref{thm:maxdegreegridtheorem}. 
    We define~${f(k,s,d) \coloneqq f'(k,(s-1) \cdot d)}$. 
    Let~$G$ be a graph with~${\ptw{\theta}{G} \geq f(k,s,d)}$.
    By \cref{lemma:width-comparison}, ${\ptw{\theta}{G} = \ptw{\theta}{\widetilde{G}} \leq \reduced{\tw{}}{G} = \tw{\widetilde{G}}}$.
    By \cref{lem:parameterinequalities-2}, ${\reduced{\Delta}{G} = \Delta(\widetilde{G}) \leq \local{\alpha}{G}^{\reduced{\omega}{G}}}$. 
    So by applying \cref{thm:maxdegreegridtheorem} to~$\widetilde{G}$, we find a $(k \times k)$-grid as an induced minor of~$\widetilde{G}$. 
    And since, by \cref{lem:clique-quotient-graph}, $\widetilde{G}$ is isomorphic to an induced subgraph of~$G$, we find a $(k \times k)$-grid as an induced minor of~$G$ as well. 
\end{proof}



\section{Forbidden induced subgraphs}
\label{sec:forbiddeninducedsubgraphs}

We move on to proving the arguably most powerful theorem of this paper:
An asymptotic classification of the hereditary graph classes with bounded $\maxP{\cideg{},\reduced{\omega}{}}{}$ in terms of a finite set of parametric graphs that have to be excluded as induced subgraphs.
For this purpose, we first provide an asymptotic description of all hereditary graph classes where $\reduced{\omega}{}$ is bounded before obtaining the full asymptotic classification theorem as a corollary. 

First, we make some basic observations on clique-incidence-diversity. 

Let~$G$ be a graph and~${X \subseteq V(G)}$.
A set~${Y \subseteq N_G(X)}$ of neighbours of~$X$ is said to be \emph{$X$-diverse} if no two distinct vertices in~$Y$ have the same set of neighbours in~$X$, that is~${N_G(y_1) \cap X \neq N_G(y_2) \cap X}$ for all distinct choices of~${y_1,y_2 \in Y}$.
The \emph{diversity number} of a set~$X$ of vertices from a graph~$G$, denoted by~$\dn{G}{X}$, is the maximum size of an $X$-diverse set in~${N_G(X)}$.
In case the graph~$G$ is understood from the context, we drop the subscript. 

\begin{lemma}\label{lemma:diverseneighbours}
    Let~$G$ be a graph and~${K \in \mathcal{K}(G)}$, then~${\log(\dn{}{K}+2) \leq \abs{\widetilde{K}} \leq 2^{\dn{}{K}}}$.
\end{lemma}

\begin{proof}
    Let~$X$ be a maximum $K$-diverse set in~$G$. 
    Observe that for every vertex~${y \in N(K) \setminus X}$ there exists a vertex~${x \in X}$ such that~${N(x) \cap K = N(y) \cap K}$ as~$X$ is maximum. 
    It follows that the classes of $\sim_{\mathcal{K}(G)}$ within~$K$ are exactly determined by the subsets of~$X$.
    To be more precise, for two vertices~${u,v \in K}$ we have~${u \sim_{\mathcal{K}(G)} v}$ if and only if~${N(u) \cap X = N(v) \cap X}$. 
    Therefore, $\abs{\widetilde{K}} \leq 2^{\abs{X}}=2^{\dn{}{K}}$.

    For the lower bound, simply observe that for every~${x \in X}$ the set~${(N(x) \cap K) \cup \{ x \}}$ belongs to some maximal clique of~$G$ which cannot contain any other vertex of~$X$. 
    Hence, we obtain~${\abs{X} = \dn{}{K}}$ many pairwise distinct maximal cliques of~$G$, all of which have a non-empty intersection with~$K$, and all these intersections are pairwise distinct. 
    Since~$K$ is maximal, $K$ is not a subset of any of these cliques. 
    Hence, $\widetilde{K}$ has at least~$\dn{}{K}$ proper non-empty subsets, so ${\dn{}{K} + 2 \leq 2^{\abs{\widetilde{K}}}}$, as required.
\end{proof}


To derive our forbidden induced subgraphs with the help of \cref{lemma:diverseneighbours}, we employ a couple of seminal results from Ramsey theory and the theory of vertex-minors. 

We consider all matrices over~$\mathds{F}_2$, and denote the \emph{adjacency matrix} of a graph~$G$ by~$\AM{G}$. 
For a set of vertices~$X$ in a graph~$G$ we define its \emph{cutrank}, denoted~$\cutrank{G}{X}$, as the rank of the submatrix of~$\AM{G}$ with rows~$X$ and columns~${\V{G}\setminus X}$. 
Given two disjoint sets of vertices~${X, Y \subseteq V(G)}$ we denote the \emph{local cutrank}, that is~${\cutrank{G[X \cup Y]}{X} = \cutrank{G[X \cup Y]}{Y}}$, by~${\localcutrank{G}{X,Y}}$. 
If the graph~$G$ is clear from the context, we drop the subscript.

Let~${X \subseteq V(G)}$ be some set of vertices in a graph~$G$.
Observe that the submatrix of~$\AM{G}$ with rows~$X$ and columns~${V(G) \setminus X}$ has exactly~$\dn{}{X}$ many distinct rows. 
Thus, the following lemma allows us to relate the diversity number of maximal cliques to their local cutrank. 

\begin{lemma}[\cite{NguyenO2020-averangecutrank}]
    \label{lemma:averagecut}
    Let~$M$ be a matrix over~$\mathds{F}_2$.
    Then the number of distinct rows in~$M$ is at most~${2^{\mathsf{rank}(M)}}$.
\end{lemma}

Indeed, combining \cref{lemma:averagecut} with \cref{lemma:diverseneighbours} yields the following.

\begin{corollary}
    \label{cor:diversitytorank}
    Let~$G$ be a graph and let~${K \in \mathcal{K}}$ be a maximal clique in~$G$, then ${\log(\log(\abs{\widetilde{K}})) \leq \localcutrank{}{K,N(K)}}$.
\end{corollary}

Let~$B$ be a bipartite graph with a bipartition~${V_1 \cup V_2}$ such that both~$V_i$ induce independent sets. 
The \emph{biadjacency matrix} of~$B$ with respect to~$V_1$ and~$V_2$ is the submatrix of~$\AM{G}$ with rows~$V_1$ and columns~$V_2$.
The definitions of matchings ($\mathscr{M}$), anti-matchings ($\mathscr{A}$), and half-graphs ($\mathscr{H}$) provide natural bipartitions of their vertex sets, and their biadjacency matrices are unique up to reordering of rows and columns.

Let $G$ be a graph and ${X, Y \subseteq V(G)}$ be two disjoint sets of vertices.
We say that $X$ and $Y$ are \emph{coupled} if the submatrix of $\AM{G}$ with rows $X$ and columns $Y$ is the biadjacency matrix of a matching, anti-matching, or half-graph. 
Ding, Oporowski, Oxley, and Vertigan \cite{DingOOV1996-Unavoidable3-con} showed that any pair of sets with large cutrank between them must contain a large coupled pair of sets.

\begin{theorem}[\cite{DingOOV1996-Unavoidable3-con}]
    \label{thm:coupledpairs}
    There exists a function ${f_{\ref{thm:coupledpairs}} \colon \N \to \N}$ such that for every positive integer~$k$, every graph~$G$ and every pair of disjoint sets~${X,Y \subseteq V(G)}$ with~${\localcutrank{}{X,Y} \geq f_{\ref{thm:coupledpairs}}(k)}$ there exists a coupled pair of sets~${X' \subseteq X}$ and~${Y' \subseteq Y}$ with~${\abs{X'} = \abs{Y'} = k}$.
\end{theorem}

The last bit of technology we need are the standard \emph{Ramsey numbers} \cite{Ramsey1929}. 
We denote by~$R(k)$ the Ramsey number that guarantees that every graph of size at least~$R(k)$ contains a clique or an independent set of size at least~$k$.

With this, we are ready to state and prove the main result of this \namecref{sec:forbiddeninducedsubgraphs}.

\begin{theorem}\label{thm:obstructionsforcid}
    Let $\mathfrak{A}$ denote the set~${\{\matchingKI,\matchingKK,\antimatchingKI,\antimatchingKK,\halfgraphKI,\halfgraphKK\}}$.
    Then the graph parameters $\bigPG{\mathfrak{A}}{\InducedSubgraph}{}$ and $\reduced{\omega}{}$ are equivalent.
\end{theorem}

\begin{proof}
    Let~${\mathscr{X} \in \mathfrak{A}}$ and~$t$ be a positive integer.
    Notice that~$\mathscr{X}_t$ has a natural bipartition of its vertex set, induced by the definition, into a clique~$X$ and a set~$Y$ which is either a clique or an independent set such that~$X$ and~$Y$ are coupled and both of size~$t$. 
    Moreover, note that in all cases, ${\widetilde{\mathscr{X}_t} = \mathscr{X}_t}$ since~$\mathscr{X}_t$ has no true twins. 
    It is straight forward to observe that $\reduced{\omega}{}$ is monotone under the induced subgraph relation, and so if~$\mathscr{X}_t$ is an induced subgraph of a graph~$G$, then~${\reduced{\omega}{G} \geq \reduced{\omega}{\mathscr{X}_t} = \omega(\mathscr{X}_t) \geq t}$.
    Hence, we obtain~$\bigPG{\mathfrak{A}}{\InducedSubgraph}{G} \leq \reduced{\omega}{G}$ for all graphs~$G$.

    To prove the other direction, let~$G$ be a graph satisfying
    $\reduced{\omega}{G} \geq 2^{2^{f_{\ref{thm:coupledpairs}}(R(t))}}$. 
    We claim that there exists some~${\mathscr{X} \in \mathfrak{A}}$ such that~$G$ contains~$\mathscr{X}_t$ as an induced subgraph. 

    Let~${K \in \mathcal{K}(G)}$ be some maximal clique of~$G$ with~${\abs{\widetilde{K}}} \geq 2^{2^{f_{\ref{thm:coupledpairs}}(R(t))}}$ and let~${X \coloneq N(K)}$ be the neighbourhood of~$K$. 
    By \cref{cor:diversitytorank} this implies~${\localcutrank{}{K,X} \geq f_{\ref{thm:coupledpairs}}(R(t))}$. 
    We now call upon \cref{thm:coupledpairs} to find sets~${Y \subseteq K}$ and~${Z \subseteq X}$ such that~$Y$ and~$Z$ are coupled and~${\abs{Y} = \abs{Z} = R(t)}$.
    Let~$H$ be the subgraph of~$G$ induced by the edges\footnote{That is, the vertex set of~$H$ is~${Y \cup Z}$ and the edge set of~$H$ is exactly those edges with exactly one end in~$Y$ and the other end in~$Z$.} between~$Y$ and~$Z$.
    Notice that there exists a bijective function~${\phi \colon Z \to Y}$ such that for each~${z \in Z}$, ${\phi(z)z \in E(G)}$ if~$H$ is a matching, ${\phi(z)z \notin E(G)}$ if~$H$ is an anti-matching, and, if~$H$ is a half-graph, $\phi$ ensures that, for the ordering of the sets~${Y = \{ y_1,y_2,\dots,y_{\abs{Y}}\}}$ and~${Z = \{ z_1,z_2,\dots,z_{\abs{Z}}\}}$ induced by the definition of half-graphs, it holds that~${\phi(z_i) = y_i}$. 
    As~${\abs{Z} = R(t)}$ we find a set~${Z' \subseteq Z}$ which is either an independent set or a clique. 
    Let~${Y' \coloneqq \{ \phi(z) \mid z \in Z' \}}$. 
    Notice that~$Y'$ and~$Z'$ are again coupled.
    Hence, ${G[Y' \cup Z']}$ is isomorphic to one of~$\matchingKI_t$, $\matchingKK_t$, $\antimatchingKI_t$, $\antimatchingKK_t$, $\halfgraphKI_t$ or~$\halfgraphKK_t$, as desired.
\end{proof}

As a direct consequence, we obtain a forbidden subgraph characterisation for bounding~$\maxP{\cideg{},\reduced{\omega}{}}{}$ (or any of the equivalent parameters from \cref{cor:parameterequivalence1}). 

\begin{corollary}
    \label{cor:parameterequivalence2}
    Let $\mathfrak{B}$ denote the set~${\{ \matchingKI,\matchingKK,\antimatchingKK,\halfgraphKK \} \cup \{ \Star \}}$.
    Then the graph parameter $\bigPG{\mathfrak{B}}{\InducedSubgraph}{}$ is equivalent to each of~$\reduced{\Delta}{}$, 
    $\cdeg{}$, 
    $\maxP{\cideg{}, \reduced{\omega}{}}{}$,
    $\maxP{\local{\alpha}{}, \reduced{\omega}{}}{}$, and
    $\maxP{\local{\theta}{}, \reduced{\omega}{}}{}$. 
\end{corollary}

\begin{proof}
    Let~$\mathfrak{A}$ be as in~\cref{thm:obstructionsforcid}, and let~${\mathfrak{C} \coloneqq \mathfrak{A} \cup \{ \Star \}}$. 

    First, let~$t$ be a positive integer and let~$G$ be a graph such that~${\maxP{\local{\alpha}{},\reduced{\omega}{}}{G} \leq t}$. 
    We obtain from \cref{thm:obstructionsforcid} that~${\bigPG{\mathfrak{A}}{\InducedSubgraph}{G} \leq f(t)}$ for some function~$f$, for which we may assume without loss of generality, that~${f(t) \geq t}$. 
    Since~${\bigPG{\Star}{\InducedSubgraph}{G} = \local{\alpha}{G} \leq t}$, we additionally observe that~${\bigPG{\mathfrak{C}}{\InducedSubgraph}{G} \leq f(t)}$, and since~${\mathfrak{B} \subseteq \mathfrak{C}}$, we conclude~${\bigPG{\mathfrak{B}}{\InducedSubgraph}{G} \leq f(t)}$, as desired. 

    On the other hand, let~$t$ be a positive integer and let~$G$ be a graph such that~${\bigPG{\mathfrak{B}}{\InducedSubgraph}{G} \leq t}$. 
    Note that since both~$\antimatchingKI_{t+1}$ and~$\halfgraphKI_{t+1}$ contain~$\Star_{t+1} = K_{1,t+1}$ as an induced subgraph, it immediately follows that~${\bigPG{\mathfrak{A}}{\InducedSubgraph}{G} \leq t}$. 
    Hence, as seen in the proof of \cref{thm:obstructionsforcid}, ${\reduced{\omega}{G} \leq t}$. 
    But since~${\bigPG{\Star}{\InducedSubgraph}{G} = \local{\alpha}{G} \leq t}$, we obtain that~${\maxP{\local{\alpha}{},\reduced{\omega}{}}{G} \leq t}$. 

    By \cref{cor:parameterequivalence1}, all the desired equivalences follow. 
\end{proof}

Note that this corollary now finishes the proof of \cref{thm:clique-sparse}. 

\section{%
\texorpdfstring{Rankwidth versus $\boldsymbol{\alpha}$-treewidth}{Rankwidth versus alpha-treewidth}}
\label{sec:rankwidth}

In this section, we consider classes obtained by excluding some parametric graphs and how this affects the relation between rankwidth and $\alpha$-treewidth.
We start with defining the rankwidth of a graph, a concept first introduced by Oum and Seymour~\cite{OumS2006-cliquewidth-branchwidth-rankwidth}. 

A \emph{rank-decomposition} of a graph~$G$ is a tuple $\Brace{T,\delta}$, where~$T$ is a cubic tree and~$\delta$ is a bijection between the leaves of~$T$ and the vertices of~$G$. 
For every edge~$e$ of~$T$, note that the two subtrees of~${T-e}$ induce a bipartition of the leaves of~$T$. 
Let~$X_e$ denote the image of one of those sets of leaves under~$\delta$. 
The \emph{cutrank} of~$e$ is defined as the cutrank of~$X_e$, i.e.~$\cutrank{G}{X_e}$ (see \cref{sec:forbiddeninducedsubgraphs} for a definition of the cutrank of a set of vertices). 
Note that this is well-defined as~$\cutrank{G}{X_e} = \cutrank{G}{V(G) \setminus X_e}$. 
The \emph{width} of $\Brace{T,\delta}$ is defined as the maximum cutrank of one of the edges of~$T$ and the \emph{rankwidth} of~$G$, denoted~$\rankwidth{G}$, is the minimum width over all rank decompositions of~$G$. 


We observe the following. 
\begin{observation}
    \label{obs:cutrank}
    Let~$G$ be a graph. For every~${X \subseteq V(G)}$, we have~$\cutrank{G}{\bigcup \widetilde{X}} = \cutrank{\widetilde{G}}{\widetilde{X}}$. 
\end{observation}

As a first result of this section, we observe that bounding both the rankwidth and the local independence number is sufficient to bound the $\alpha$-treewidth of a graph. 


\begin{theorem}
    \label{thm:rw-vs-alpha-tw1}
    For every positive integers~$d$ and~$k$ and every graph~$G$ with~${\local{\alpha}{G} \leq d}$ and~${\rankwidth{G} \leq k}$ we have~${\ptw{\alpha}{G} \leq 3dk}$. 
\end{theorem}

\begin{proof}
    Let~$G$ be a graph with~${\local{\alpha}{G} \leq d}$ and~${\rankwidth{G} \leq k}$. 
    Let~$(T,\delta)$ be a rank-decomposition of~$G$ of width at most~$k$. 
    We define a tree-decomposition~$(T,\beta)$ of~$G$ as follows. 
    For each leaf~$t$ of~$T$, we set~${\beta(t) \coloneqq \delta(t)}$. 
    For each internal node~$t$ of~$T$, consider the sets~$X_t^1$, $X_t^2$, $X_t^3$ of vertices mapped to the leaves of the three components of~${T - t}$, and define~${\beta(t)}$ as the set of those vertices~$v$ in~$X_t^1 \cup X_t^2 \cup X_t^3$ for which there are~$i,j \in [3]$ with~${i \neq j}$ and a neighbour~${w \in N_G(v)}$ such that~${v \in X_t^i}$ and~${w \in X_t^j}$. 
    We claim that~$(T,\beta)$ is a tree-decomposition of~$G$. 
    Clearly, ${\bigcup_{t \in V(T)} \beta(t) = V(G)}$. 
    Moreover, for every edge~${vw \in E(G)}$, both~$v$ and~$w$ are contained in~$\beta(t)$ for any internal node~$t$ for which~$\delta^{-1}(v)$ and~$\delta^{-1}(w)$ are in different components of~${T - t}$. 
    Since the latter holds in particular for the neighbour~$t'$ of~$\delta^{-1}(v)$ in~$T$, we have~${vw \subseteq \beta(t')}$. 
    Lastly, suppose that~${v \in \beta(t_1) \cap \beta(t_2)}$ for two non-adjacent nodes~$t_1$ and~$t_2$ of~$T$, and let~$t_3$ be any node of~$T$ on the unique path between~$t_1$ and~$t_2$ in~$T$. 
    Consider~${(T - t_1) - t_2}$, which has five components, two adjacent to only~$t_1$, two adjacent to only~$t_2$, and one adjacent to both~$t_1$ and~$t_2$. 
    For~${i \in [2]}$, let~$Z_i$ denote the union of the components adjacent to only~$t_i$, and let~$Z_3$ denote the component adjacent to both~$t_1$ and~$t_2$, which contains~$t_3$. 
    If~$\delta^{-1}(v)$ is contained in~$Z_i$ for~${i \in [2]}$, then, since~${v \in \beta(t_{2-i})}$, there is a neighbour~$w$ of~$v$ with~${\delta^{-1}(w) \in V(Z_{2-i})}$. 
    And since both~$Z_1$ and~$Z_2$ are contained in distinct components of~${T - t_3}$, we conclude~${v \in \beta(t_3)}$. 
    So assume~$\delta^{-1}(v)$ is contained in~$Z_3$. 
    Then, since~${v \in \beta(t_1) \cap \beta(t_2)}$, there are neighbours~$w_1$ and~$w_2$ of~$v$ with~${\delta^{-1}(w_1) \in V(Z_1)}$ and~${\delta^{-1}(w_2) \in V(Z_2)}$. 
    And since both~$Z_1$ and~$Z_2$ are contained in distinct components of~${T - t_3}$, one of them is distinct to the component of~${T - t_3}$ containing~$\delta^{-1}(v)$. 
    Therefore,~${v \in \beta(t_3)}$.
    Thus we conclude that~${(T,\beta)}$ is a tree-decomposition of~$G$. 

    Finally, we prove that~${\alpha(G[\beta(t)]) \leq 3dk}$ for each node~${t \in V(T)}$. 
    Since the bags of leaves of~$T$ have size~$1$, they have independence number~$1$ as well. 
    For an internal node~$t$, again consider~$X_t^1$, $X_t^2$, $X_t^3$ as above, and let~$A$ be a maximum independent set of~$G[\beta(t)]$. 
    Suppose for a contradiction that~${\abs{A} \geq 3dk+1}$. 
    By the pigeonhole principle, there is an~${i \in [3]}$ such that~${\abs{A \cap X_t^i} \geq dk+1}$, say~${i=1}$. 
    By definition, every~${v \in X_t^1}$ has a neighbour in~${X_t^2 \cup X_t^3}$. 
    Since~${\local{\alpha}{G} \leq d}$, any vertex in~${X_t^2 \cup X_t^3}$ can have at most~$d$ vertices of~$A$ in its neighbourhood. 
    Let~${B \subseteq X_t^2 \cup X_t^3}$ be minimal such that~${A \subseteq N_G(B)}$. 
    By the observation above, ${\abs{B} \geq k+1}$. 
    But by the minimality of~$B$, each~${w \in B}$ has a neighbour in~$A$ that is not adjacent to any other~${w'\in B}$. 
    Hence, there is a matching of size~$k+1$ between~$X_t^1$ and~${X_t^2 \cup X_t^3}$. 
    But such a matching witnesses that~$\cutrank{G}{X_t^1} \geq k+1$, contradicting that the rankwidth of~$G$ is at most~$k$.
\end{proof}

The complete bipartite graph~$K_{n,n}$ is a graph of rankwidth~$1$ and $\alpha$-treewidth~$n$. 
The $(n \times n)$-grid is a graph of local-independence number~$4$ and $\alpha$-treewidth roughly~$n/2$.
To see this let $n\geq 3$ and $G_n$ be the $(n \times n)$-grid.
Notice that $G_n=\widetilde{G_n}$ since $G_n$ is a bipartite graph without true twins.
It now follows from \cref{lemma:width-comparison} that $\ptw{\alpha}{G_n}\leq \reduced{\tw{}}{G} = \tw{G} \leq 2\cdot \ptw{\theta}{G_n}$.
Moreover, since bipartite graphs are perfect, it also holds that $\theta(H)=\alpha(H)$ for all induced subgraphs $H$ of $G_n$.
Hence $\ptw{\alpha}{G_n}=\ptw{\theta}{G_n}$.
With $\tw{G_n}=n$ it follows that $n/2 \leq \ptw{\alpha}{G_n}$.
Moreover, an optimal tree-decomposition of $G_n$ can easily be observed to be of independence-number at most $\lceil n/2\rceil$, which completes the argument.

So, in general, it is necessary to bound both of these parameters, namely the rankwidth and the local independence number, in order to bound the $\alpha$-treewidth as well. 

On the other hand, for every~$n$ there is a graph of rankwidth~$n$, $\alpha$-treewidth~$2$, and local independence number~$3$, as we see below. 

As the main result of this section, we prove the following theorem. 


\begin{theorem}
    \label{thm:rw-vs-alpha-tw2}
    Let~$\mathfrak{B}$ denote the set~${\{ \matchingKI, \matchingKK, \antimatchingKK, \halfgraphKK, \Star \}}$, 
    and let~$\mathcal{F} \subseteq \bigcup \mathfrak{B}$ be a set of graphs, each of which is contained in at least one~${\mathcal{X} \in \mathfrak{B}}$. 
    The parameters~$\maxP{\local{\alpha}{},\rankwidth{}}{}$ and~$\ptw{\alpha}{}$ are equivalent on the class of $\mathcal{F}$-free graphs if and only if
    \begin{itemize}
        \item $\mathcal{F}$ contains~${\matchingKI_2 \cong P_4}$ and~$\Star_n$ for some~${n \in \N}$, or
        \item $\mathcal{F}$ contains at least one graph from each~${\mathcal{X} \in \mathfrak{B}}$. 
    \end{itemize}
\end{theorem}


We prove this theorem in two steps. 
First, we analyse the relationship between rankwidth and $\alpha$-treewidth on graphs of bounded~$\maxP{\local{\alpha}{},\reduced{\omega}{}}{}$. 

\begin{theorem}
    \label{thm:rw-vs-alpha-tw3}
    Let~$d$ be a positive integer and let~$\mathcal{G}$ be a hereditary graph class such that~${\maxP{\local{\alpha}{},\reduced{\omega}{}}{G} \leq d}$ for every~${G \in \mathcal{G}}$. 
    Then the parameters~$\ptw{\alpha{}}{}$, $\rankwidth{}$ and~$\reduced{\tw{}}{}$ are equivalent on~$\mathcal{G}$. 
\end{theorem}

\begin{proof}
    Clearly, $\ptw{\alpha}{G} \leq \tw{G}$ for every graph~$G$. 
    Oum~\cite{Oum2008-rw-bw} showed that~${\rankwidth{G} \leq \tw{G}+1}$ for every graph~$G$.  
    From \cref{lemma:width-comparison}, we know that~$\ptw{\alpha}{G} = \ptw{\alpha}{\widetilde{G}}$ for every graph~$G$. 
    Similarly, we claim that~${\rankwidth{G} = \rankwidth{\widetilde{G}}}$, unless $\widetilde{G}$ is edgeless but~$G$ is not (in which case ${\rankwidth{G} = 1}$ but ${\rankwidth{\widetilde{G}} = 0}$).
    Indeed, clearly~${\rankwidth{\widetilde{G}} \leq \rankwidth{G}}$. 
    For the other direction, consider a rank-decomposition~$(T,\delta)$ of~$\widetilde{G}$ of width~$\rankwidth{\widetilde{G}}$. 
    For a set~${X \subseteq V(G)}$, let~$T_{{X}}$ denote a subcubic tree with exactly~$\abs{X}$ leaves and exactly one node of degree~$2$. 
    For every leaf~$t$ of~$T$ with~$\delta(t) = \widetilde{v}$, we extend the rank-decomposition by identifying the degree-$2$ vertex of~$T_{\widetilde{v}}$ with~$t$ and label the new leaves with an arbitrary bijection to~$\widetilde{v}$. 
    Let~$(T',\delta')$ denote the resulting rank-decomposition of~$G$. 
    For every edge of~$T'$ that corresponds to an edge of~$T_{\widetilde{v}}$ for some~${\widetilde{v} \in V(\widetilde{G})}$, we observe that one component~${T-e}$ is mapped by~$\delta'$ to a set of true twins, and hence the cutrank of~$e$ is at most~$1$. 
    For every edge~$e'$ of~$T'$ that corresponds to an edge~$e$ of~$T$, if~$\widetilde{X}$ and~$\widetilde{Y}$ denotes the images of the bipartition of the leaves of~$T$ induced by~$e$ under $\delta$, then the image of the bipartition of the leaves of~$T'$ induced by~$e'$ under $\delta'$ are~$\bigcup \widetilde{X}$ and~$\bigcup \widetilde{Y}$. 
    Hence, the cutrank of~$e$ in~$(T,\delta)$ is equal to the cutrank of~$e'$ in~$(T',\delta')$ by \cref{obs:cutrank}, and the rankwidth of~$G$ is at most~${\max\{1,\rankwidth{\widetilde{G}}\}}$. 
    So in total, we conclude that $\ptw{\alpha}{G} \leq \reduced{\tw{}}{G}$ and~${\rankwidth{G} \leq \reduced{\tw{}}{G} + 1}$. 

    Now consider a graph~${G \in \mathcal{G}}$ and set~${w \coloneqq \ptw{\alpha}{G}}$. 
    Let~$(T,\beta)$ be a tree-decomposition of~$\widetilde{G}$ of $\alpha$-width~$w$. 
    Since~${\reduced{\omega}{\widetilde{G}[\beta(t)]} \leq \reduced{\omega}{G} \leq d}$ for every node~${t \in V(T)}$, by Ramsey's theorem we have that~$\abs{\beta(t)} \leq R(\max\{d,w\})$. 
    Hence, $\reduced{\tw{}}{G} \leq R(\max\{d,w\})$, as desired. 

    Now consider a graph~${G \in \mathcal{G}}$ and set~${k \coloneqq \rankwidth{G}}$. 
    By \cref{thm:rw-vs-alpha-tw1}, we have $\ptw{\alpha}{G} \leq 3dk$, and hence, by the deduction above, ${\reduced{\tw{}}{G} \leq R(3dk)}$. 
\end{proof}

For the second part of \cref{thm:rw-vs-alpha-tw2}, we define the following graphs. 
Let~${n \geq 1}$ and~${k \geq 2}$ be integers, let~$X^1 = \{ x_1^1, \dots x_n^1 \}, \dots, X^k = \{ x_1^k, \dots x_n^k \}$ be pairwise disjoint ordered sets, each of size~$n$, and let~$\{ y^1, \dots, y^k \}$ and~$\{ z^1, \dots, z^{k-1} \}$ be sets of size~$k$ and~$k-1$, respectively, that are disjoint to each other and to each set~$X^j$. 
We define the following graphs, see also \cref{fig:iteratedHedgehogs}. 
\begin{itemize}
    \item $Q_k(\matchingII_n) = \bigcup_{i \in [k-1]} \mathscr{M}(X^i, X^{i+1}) \cup \bigcup_{i \in [k]} K(\{y^i\}, X^i)$
    \item $Q_k(\matchingKK_n) = \bigcup_{i \in [k-1]} \mathscr{M}(X^i, X^{i+1}) \cup \bigcup_{i \in [k]} K(\{y^i\} \cup X^i)$
        \item $Q_k(\matchingKI_n) = \bigcup_{i \in [k-1]} \mathscr{M}(X^i, X^{i+1}) \cup \bigcup_{i \in [ \lceil k/2 \rceil ]} K(\{y^{2i-1}\} \cup X^{2i-1})$
    \item $Q_k(\halfgraphII_n) = \bigcup_{i \in [k-1]} \mathscr{H}(X^i, X^{i+1}) \cup \bigcup_{i \in [k]} K(\{y^i\}, X^i)$
    \item $Q_k(\halfgraphKK_n) = \bigcup_{i \in [k-1]} \mathscr{H}(X^i, X^{i+1}) \cup \bigcup_{i \in [k]} K(\{y^i\} \cup X^i)$
    \item $Q_k(\antimatchingKK_n) = \bigcup_{i \in [k-1]} \mathscr{A}(X^i, X^{i+1}) \cup \bigcup_{i \in [k]} K(\{y^i\} \cup X^i) \cup \bigcup_{i \in [k-1]} K(\{z^i\}, X^i \cup X^{i+1})$
\end{itemize}

