\end{figure}

\begin{lemma}
    \label{lem:Q_n(X)-1}
    For each integer~${n \geq 3}$ and each~${\mathcal{X} \in \{\matchingKI, \matchingKK, \antimatchingKK, \halfgraphKK \}}$, we have ${\ptw{\alpha}{Q_n(\mathcal{X}_n)} \leq 2}$ and~${\local{\alpha}{Q_n(\mathcal{X}_n)} \leq 3}$. 
\end{lemma}

\begin{proof}
    For each positive integers~$m$ and $m'$, let~${P_{m}}$ denote the path with~$m$ vertices~${t_1, \dots t_{m}}$ and edges~$t_i t_{i+1}$ for each~${i \in [m-1]}$, and let~$T_{m,m'}$ denote the tree obtained from~$P_m$ by, for each~${i \in m}$, attaching~$m'$ leaves~${t_i^1, \dots, t_i^{m'}}$ to~$t_i$. 

    For~${\mathcal{X} \in \{ \matchingKK, \antimatchingKK, \halfgraphKK \}}$, we do the following. 
    We define a path-decomposition~$(P_{n-1}, \beta)$ of~$Q_n(\mathcal{X}_n)$ by, for all~${i \in [n-1]}$, setting ${\beta(t_i) \coloneqq X^i \cup X^{i+1} \cup \{y^i, y^{i+1}, z^i\}}$ if~${\mathcal{X} =\antimatchingKK}$, and setting ${\beta(t_i) \coloneqq X^i \cup X^{i+1} \cup \{y^i, y^{i+1}\}}$, otherwise. 
    It is easy to see that~$(P_{n-1},\beta)$ is indeed a path-decomposition of~${Q_n(\mathcal{X}_n)}$. 
    And since each~$X^i \cup \{y^i\}$ induces a clique of~${Q_n(\mathcal{X}_n)}$, the independence number of each bag is at most~$2$. 
    (Indeed, $Q_n(\matchingKK_n)$ and $Q_n(\antimatchingKK_n)$ contain $C_4$ as an induced subgraph, hence are not chordal, and therefore have $\alpha$-treewidth equal to~$2$, and $Q_n(\halfgraphKK_n)$ is chordal and hence has~$\alpha$-treewidth equal to~$1$.) 

    We define a tree-decomposition~$(T_{\lfloor n/2 \rfloor, n}, \beta)$ of~$Q_n(\matchingKI_n)$ by setting ${\beta(t_i) = X^i \cup X^{i+2} \cup \{ y^i, y^{i+2} \}}$ for all positive integers~${i}$ with~${2i - 1 \in [n-1]}$, and setting~$\beta(t_i^j) = N_{Q_n(\matchingKI_n)}[x_j^{i+1}]$ for all positive integers~${i}$ with~${2i - 1 \in [n-1]}$ and all integers~${j \in [n]}$. 
    Again, it is easy to see that~$(T_{\lfloor n/2 \rfloor, n}, \beta)$ is a tree-decomposition of independence number~$2$. 
    (And since $Q_n(\matchingKI_n)$ contains~$C_6$ as an induced subgraph, it is not chordal and hence has $\alpha$-treewidth equal to~$2$.)

    Lastly, it is straight forward to observe that the neighbourhood of each vertex can be covered by at most three cliques, hence~${\local{\alpha}{Q_n(\mathcal{X}_n)} \leq 3}$ for each~${\mathcal{X}_n \in \{\matchingKI_n, \matchingKK_n, \antimatchingKK_n, \halfgraphKK_n \}}$. 
\end{proof}

To analyse the rankwidth of these graphs, we make use of the grid theorem for vertex-minors~\cite{GeelenKMW2023-vertexminorgridtheorem}. 
To state this, we first need to define vertex-minors. 

Let~$G$ be a graph and let~${v \in V(G)}$. 
We define the operation~${G \ast v}$ of \emph{local complementation at~$v$} as the graph where we complement the subgraph induced by the open neighbourhood of~$v$. 
A \emph{vertex-minor} of~$G$ is a graph obtained from~$G$ by a sequence of vertex-deletions and local completions. 
It is well-known that rankwidth is monotone under the vertex-minor containment relation~\cite{Oum2005-rw-vm}. 

\begin{lemma}[{\cite[Lemma 7.8]{GeelenKMW2023-vertexminorgridtheorem}}]
    \label{lem:pathconstellations}
    There exists a function~$f$ such that for any positive integer~$n$, 
    the graphs~$Q_{f(n)}(\matchingII_{f(n)})$ and~$Q_{f(n)}(\halfgraphII_{f(n)})$ have rankwidth at least~$n$. 
\end{lemma}

What Geelen, Kwon, McCarty, and Wollan actually show is that these graphs contain the ${n \times n}$-comparability grid\footnote{The \emph{$n \times n$-comparability grid} is the graph with vertex set~$[n]^2$ where~$(i,j)$ and~$(i',j')$ are adjacent if and only if either~${i \leq i'}$ and~${j \leq j'}$ or~${i \geq i'}$ and~${j \geq j'}$. } as a vertex-minor.
This lemma is an essential tool to prove their celebrated Vertex-Minor Grid Theorem, which states that every graph with sufficiently large rankwidth has an ${n \times n}$-comparability grid as a vertex-minor. 
We do not need the full strength of this fundamental result of the structural theory of vertex-minors, but \cref{lem:pathconstellations} suffices for our purposes.
Using this lemma, we are able to argue that each of~$Q_n(\matchingKI_n)$, $Q_n(\matchingKK_n)$, $Q_n(\antimatchingKK_n)$, and $Q_n(\halfgraphKK_n)$ have large rankwidth as we are able to find $Q_{n'}(\matchingII_{n'})$ or~$Q_{n'}(\halfgraphII_{n'})$ for some sufficiently large~$n'$ as a vertex-minor. 

\begin{lemma}
    \label{lem:Q_n(X)-2}
    There exists a function~$f$ such that for every positive integer~${n}$ and each~${\mathcal{X} \in \{\matchingKI, \matchingKK, \antimatchingKK, \halfgraphKK \}}$, we have ${\rankwidth{Q_{f(n)}(\mathcal{X}_{f(n)})} \geq n}$. 
\end{lemma}

\begin{proof}
    For each integer~${m \geq 3}$, observe that the graph obtained from~$Q_{m}(\matchingKK_m)$ by successively locally complementing at~$y^1, \dots, y^m$ is equal to~$Q_{m}(\matchingII_m)$. 
    Similarly, for each integer~${m \geq 3}$, that the graph obtained from~$Q_{m}(\halfgraphKK_m)$ by successively locally complementing at~${y^1, \dots, y^m}$ is equal to~$Q_{m}(\halfgraphII_m)$. 
    For each integer~${m \geq 3}$, consider the graph obtained from~$Q_{m}(\matchingKI_m)$ by successively locally complementing at~$y^1, y^3, \dots$. 
    Now, we locally complement at each vertex of degree~$2$ and delete it afterwards; this corresponds to suppressing each degree-$2$ vertex. 
    Lastly, we delete all degree-$1$ vertices. 
    The resulting graph is isomorphic to~$Q_{\lfloor m/2 \rfloor - 1}(\matchingII_m)$. 

    Finally, for each integer~${m \geq 3}$, observe that the graph obtained from~$Q_{m}(\antimatchingKK_m)$ by successively locally complementing at~$z^1, \dots, z^{m-1}$ and then deleting~$\{z^1, \dots, z^{m-1}\}$ is equal to~$Q_{m}(\matchingII_m)$. 
\end{proof}


Finally, we can conclude with the proof of \cref{thm:rw-vs-alpha-tw2}. 

\begin{proof}[Proof of \cref{thm:rw-vs-alpha-tw2}.]
    Let~$\mathcal{G}$ denote the class of $\mathcal{F}$-free graphs. 

    First suppose that~$\mathcal{F}$ contains a graph from each~${\mathcal{X} \in \mathfrak{B}}$. 
    Then the parameter $\maxP{\local{\alpha}{},\reduced{\omega}{}}{}$ is bounded on~$\mathcal{G}$ by \cref{cor:parameterequivalence2}. 
    Hence, by \cref{thm:rw-vs-alpha-tw3}, $\rankwidth{}$ and $\ptw{\alpha}{}$ are equivalent on~$\mathcal{G}$, and since~$\local{\alpha}{}$ is bounded on~$\mathcal{G}$, we have that~$\maxP{\local{\alpha}{}, \rankwidth{}}{}$ and~$\ptw{\alpha}{}$ are equivalent on~$\mathcal{G}$. 

    Now suppose that~${P_4 \cong \matchingKI_2 \in \mathcal{F}}$ and~$\Star_n \in \mathcal{F}$. 
    Then, in particular, each graph in~$\mathcal{G}$ is a cograph. 
    Now, cographs have rankwidth at most~$1$ \cite{Oum2005-rw-vm} and the $\alpha$-treewidth of~$\Star_n$-free cographs is less than~$n$ \cite[Theorem 1.7]{DallardKKMMW2024}. 
    Hence, both~$\maxP{\local{\alpha}{}, \rankwidth{}}{}$ and~$\ptw{\alpha}{}$ are bounded on~$\mathcal{G}$, and hence are equivalent.  

    Now suppose that~$\mathcal{F}$ does not contain~$\mathcal{X}_n$ for some~${\mathcal{X} \in \mathfrak{B}}$ and all~${n \in \N}$, and does not contain~${\matchingKI_2 \cong P_4}$. 
    Hence, $\mathcal{X}_n \in \mathcal{G}$. 
    If~${\mathcal{X} = \Star}$, then note that since~$\ptw{\alpha}{\Star_n} = 1$ and~${\local{\alpha}{\Star_n} = n}$, we conclude that~$\maxP{\local{\alpha}{},\rankwidth{}}{}$ and~$\ptw{\alpha}{}$ cannot be equivalent on~$\mathcal{G}$. 
    If, on the other hand, $\mathcal{X} \in \mathfrak{B} \setminus \{\Star\}$, 
    then~$\mathcal{F}$ contains only graphs of the form~$\mathcal{Y}_m$ for~$\mathcal{Y} \in \mathfrak{B} \setminus \{\mathcal{X}\}$ and~${m \in \N}$. 
    Since~$\matchingKI_1 = \matchingKK_1 = \antimatchingKK_1 = \halfgraphKK_1$, none of these is contained in~$\mathcal{F}$. 
    Moreover, since~$\matchingKK_2 = \antimatchingKK_2$, if~${\mathcal{X} \in \{ \matchingKK, \antimatchingKK \}}$, then~${\matchingKK_2 = \antimatchingKK_2 \notin \mathcal{F}}$. 
    Now, for each~$\mathcal{Y} \in \mathfrak{B} \setminus \{\mathcal{X}\}$ it is easy to see that~$Q_n(\mathcal{X}_n)$ does not contain~$\mathcal{Y}_m$ as an induced subgraph for any~${m \geq 3}$. 
    And since~${\matchingKI_2 \notin \mathcal{F}}$, it then follows that~$Q_n(\mathcal{X}_n) \in \mathcal{G}$ for every~${n \in \N}$. 
    Now since, by \cref{lem:Q_n(X)-2}, the rankwidth of these graphs is unbounded but, by \cref{lem:Q_n(X)-1}, the $\alpha$-treewidth (and local independence number) is bounded, we conclude that~$\maxP{\local{\alpha}{},\rankwidth{}}{}$ and~$\ptw{\alpha}{}$ cannot be equivalent on~$\mathcal{G}$.
\end{proof}


