	\centering
	% trim={<left> <lower> <right> <upper>}
	\includegraphics[trim=7.5cm 0.35cm 7.5cm 2.5cm, clip=true, scale=0.185]{avail_disp_beds.png}
	\caption{Comparison between the number of available and occupied hospital beds in Chile}
