\end{figure}

\begin{figure}[!ht]
	\centering
	\includegraphics[trim=7.5cm 0.35cm 7.5cm 2.5cm, clip=true, scale=0.185]{second_unique_doses.png}
	\caption{Percentage of the target population that is fully vaccinated in Chile}
