\hfill
\subfloat[Week 7-8: Dialogue with an LLM-enhanced robot arm.\label{fig:conversations-with-an-LLM-enhanced-robot-arm}]{\includegraphics[width=0.19\linewidth]{images-weekly-e.png}}
\caption{Weekly human-robot drawing activities.}
\label{fig:weekly-activities}
