\title{An exact approach for the multi-depot electric vehicle scheduling problem}
\author{Xenia Haslinger\textsuperscript{a} \and Elisabeth Gaar\textsuperscript{b} \and Sophie N. Parragh\textsuperscript{a} \\
\footnotesize \textsuperscript{a} Johannes Kepler University Linz, Institute of Production and Logistics Management, \\
