\title{Continuous Petri Nets Faithfully Fluidify \\ Most Permissive Boolean Networks}
\author{Stefan Haar\inst{1}\orcidlink{0000-0002-1892-2703} and Juri Kol\v{c}\'ak\inst{2}\orcidlink{0000-0002-9407-9682}} 
\institute{INRIA, France\\
\email{stefan.haar@inria.fr}\and 
