\title{Codeword-Segmentation Rate-Splitting Multiple Access and Evaluation under Suboptimal Decoding}

\author{
    \IEEEauthorblockN{
        Sibo~Zhang,~\IEEEmembership{Graduate Student Member,~IEEE}, Bruno~Clerckx,~\IEEEmembership{Fellow,~IEEE}}, David Vargas% <-this % stops a space
    \thanks{This work was supported in part by the UK Engineering and Physical Sciences Research Council, Industrial Case award number 210163.}
    \thanks{S. Zhang is with the Department of Electrical and Electronic Engineering at Imperial College London, London SW7 2AZ, UK and BBC Research and Development, The Lighthouse, White City Place, 201 Wood Lane, London, W12 7TQ, U.K. (e-mail: sibo.zhang19@imperial.ac.uk).}
