\subsection{Evaluation of RSMA and CS-RSMA}

We assume that each user applies a suboptimal decoding strategy by treating the desired signals optimally but the undesired signals as Gaussian random variables with the same variance\footnote{This decoding strategy is based on implications on soft codeword level interference cancellation for SIC receivers, and joint-demapping receivers for non-SIC receivers proposed in \cite{Sibo_TCOM}. It assumes that the decoding metrics for common and private streams are separable. The joint-demapping receiver is classified as a non-SIC receiver in \cite{Sibo_TCOM}, which effectively treats the desired signals optimally when demodulating a stream. This is not the only possible decoding strategy. For clarity, we leave the analysis for other decoding strategies for future works.}. For example, when user-$k$ decodes $s_\text{c}$, it treats $\mathbf{h}_k^H \mathbf{p}_k s_{\text{p},k}$ optimally, but treats $\{\mathbf{h}_k^H \mathbf{p}_{k'} s_{k'} \}$ as $\mathcal{CN}(0,|\mathbf{h}_k^H\mathbf{p}_{k'}|^2)$, $\forall k' \in \mathcal{K}/k$. This decoding strategy is based on the assumption that desired signals are typically stronger than unwanted signals. An implication of \cite{Sibo_FAGCI} is that treating strong interference as Gaussian random variables can lead to significant losses, whereas the impact of treating weak interference as Gaussian random variables can be negligible. Hence, we consider decoders that treat the desired signals optimally to enable high performance under limited allowance for decoding complexity.

The instantaneous achievable information rates of the common and desired private streams at user-$k$ can be measured by GMI as follows:
\begin{itemize}
    \item For the common stream:
        \begin{equation}\label{equ: common rate}
            I_{\text{c},k} = I_\text{GMI}\left(\mathbf{h}_k^H\mathbf{p}_\text{c}\mathcal{X}_\text{c},\; \mathbf{h}_k^H\mathbf{p}_k\mathcal{X}_{\text{p},k},\; \sum_{k'\neq k}\mathbf{h}_k^H\mathbf{p}_{k'}\mathcal{X}_{\text{p},k'},\; \sigma_z^2\right).
        \end{equation}
    \item For the private stream assuming SIC is applied to remove the common stream signal:
        \begin{equation}\label{equ: private rate SIC}
            I_{\text{p},k}^{\text{SIC}} = I_\text{GMI}\left(\mathbf{h}_k^H\mathbf{p}_k\mathcal{X}_{\text{p},k},\; \{0\},\; \sum_{k'\neq k}\mathbf{h}_k^H\mathbf{p}_{k'}\mathcal{X}_{\text{p},k'},\; \sigma_z^2\right).
        \end{equation}
    \item For the private stream assuming SIC-free receivers, i.e., the decoding of the private stream is under interference from the common stream:
        \begin{equation}\label{equ: private rate non-SIC}
            I_{\text{p},k}^{\text{non-SIC}} = I_\text{GMI}\left(\mathbf{h}_k^H\mathbf{p}_k\mathcal{X}_{\text{p},k},\; \mathbf{h}_k^H\mathbf{p}_\text{c}\mathcal{X}_\text{c},\; \sum_{k'\neq k}\mathbf{h}_k^H\mathbf{p}_{k'}\mathcal{X}_{\text{p},k'},\; \sigma_z^2\right).
        \end{equation}
\end{itemize}

$\forall k\in\mathcal{K}$, let $c_k$ denote the portion of $W_\text{c}$ occupied by $W_{\text{c},k}$ in conventional RSMA, or the portion of $\mathbf{s}_\text{c}$ occupied by $\mathbf{s}_{\text{c},k}$ in CS-RSMA. Therefore, $c_k\geq0$ and $\sum_{k\in\mathcal{K}} c_k= 1$. 

Under different RSMA schemes, the achievable rate for user-$k$ is expressed as follows:
\begin{itemize}
    \item Conventional RSMA with SIC:
        \begin{equation}\label{equ: rate RSMA SIC}
            I_{\text{GMI},k} = c_k\; \min_{k' \in \mathcal{K}}\; I_{\text{c},k'} + I_{\text{p},k}^{\text{SIC}}.
        \end{equation}
    \item Conventional RSMA with SIC-free receivers:
        \begin{equation}\label{equ: rate RSMA SIC-free}
            I_{\text{GMI},k} = c_k\; \min_{k' \in \mathcal{K}}\; I_{\text{c},k'} + I_{\text{p},k}^{\text{non-SIC}}.
        \end{equation}
    \item CS-RSMA:
        \begin{equation}\label{equ: rate CS-RSMA}
            I_{\text{GMI},k} = c_k I_{\text{c},k} + I_{\text{p},k}^{\text{non-SIC}}.
        \end{equation}
\end{itemize}

\begin{remark}
    The "$\min$" operator in (\ref{equ: rate RSMA SIC}) and (\ref{equ: rate RSMA SIC-free}) is due to the fact that conventional RSMA requires all users to be able to decode the common stream. For CS-RSMA, users only need to decode the codeword after combining the segments from the common and private streams, and do not need to decode the common stream. The achievable rate at user-$k$ is therefore given by a weighted average of the common stream rate and the private stream rate, with the weights determined by the ratio of symbols assigned to the two streams. Hence, the "$\min$" operator disappears in (\ref{equ: rate CS-RSMA}).
\end{remark} 

\begin{remark}
    The common stream in CS-RSMA is a combination of codeword segments from potentially all the users, and is not meant to be decodable to any of the users. Therefore, applying SIC to decode and remove the common stream is not feasible for CS-RSMA. Since the private stream is disrupted by interference from the common stream in decoding, in (\ref{equ: rate CS-RSMA}), the achievable rate contributed by the private stream is the same as in conventional SIC-free RSMA, assuming that the decoding metrics for the common and desired streams are separable.
\end{remark}

\subsection{Constrained Decoding Complexity}
Comparing communication schemes in the finite alphabet regime is more involved than in the Gaussian signaling regime. On the one hand, the achievable rate ultimately depends on the cardinality of alphabets under sufficient SNR. On the other hand, the decoding complexity is proportional to the number of observed signals and the cardinality of their alphabets, which can be observed from (\ref{equ: matched decoding metric}) and (\ref{equ: mismatched decoding metric}). Therefore, we introduce the concept of decoding complexity constraint to ensure fairness of comparison. 

\begin{definition}[Decoding Complexity]
    A decoder of complexity-$\delta$ can compute "$\exp(|\cdot|^2)$" for at most $n$ times for each received symbol.
\end{definition}

For example, for the channel model given by (\ref{equ: single-user MISO Rx}), the matched decoding, as in (\ref{equ: matched decoding metric}), is only valid if $\delta \geq |\mathcal{X}||\mathcal{I}||\mathcal{J}|$. The mismatched decoder given by (\ref{equ: mismatched decoding metric}) is valid if $\delta \geq |\mathcal{X}||\mathcal{I}|$, therefore, requires a lower decoding complexity than the matched decoding.

\begin{proposition}[Decoding Complexity of RSMA]
    For conventional RSMA (with or without SIC) and CS-RSMA, if user-$k$ treats all the undesired private streams as Gaussian noise, the decoding is feasible with at least complexity-$|\mathcal{X}_\text{c}||\mathcal{X}_{\text{p},k}|$ at user-$k$, $\forall k \in \mathcal{K}$.
\end{proposition}

\begin{IEEEproof}
For all the RSMA schemes considered, we show that, if user-$k$ treats all the undesired private streams as Gaussian random variables, it needs to compute 
\begin{equation}\label{equ: RSMA decoding element}
    d(s_\text{c},\;s_{\text{p},k},\;y_{t,k}) = \exp\left(-\frac{|y_{t,k}-\mathbf{h}_k^H\mathbf{p}_{\text{c}}s_\text{c}-\mathbf{h}_k^H\mathbf{p}_k s_{\text{p},k}|^2}{\sum_{k'\neq k}|\mathbf{h}_k^H\mathbf{p}_{k'}|^2+\sigma_z^2}\right)
\end{equation}
 $\forall s_\text{c} \in \mathcal{X}_\text{c}$, $\forall s_{\text{p},k} \in \mathcal{X}_{\text{p},k}$ and for each time instance $t$. The rest of the decoding is achieved by only summing and multiplying $d(s_\text{c},\; s_{\text{p},k},\; y_{t,k})$ with different arguments. The exact decoders in terms of $d(s_\text{c},\;s_{\text{p},k},\;y_{t,k})$ are listed as follows: 
\begin{itemize}
    \item For conventional RSMA, Let $\{\mathbf{s}_\text{c}^{(1)},\;...,\;\mathbf{s}_\text{c}^{(M_\text{c})}\}$ denote the codebook for common stream and $\{\mathbf{s}_{\text{p},k}^{(1)},\;...,\;\mathbf{s}_{\text{p},k}^{(M_{\text{p},k})}\}$ denote the codebook for the private stream intended for user-$k$, $\forall k \in \mathcal{K}$, with $M_\text{c}$ and $M_{\text{p},k}$ being the corresponding codebook sizes. Let $s_{\text{c},t}^{(q)}$ and $s_{\text{p},t,k}^{(q)}$ respectively denote the symbol of $\mathbf{s}_\text{c}^{(q)}$ and $\mathbf{s}_{\text{p},k}^{(q)}$ at time instance $t$. The decoder for the common stream can be represented as
        \begin{equation}\label{equ: RSMA SIC decoding}
        \begin{split}
            \widehat{W}_\text{c} 
            =& \arg \max_{q\in{1,\;...,\;M_\text{c}}} q^n(\mathbf{s}_\text{c}^{(q)},\;\mathbf{y}_k)\\
            =& \arg \max_{q\in{1,\;...,\;M_\text{c}}} \prod_{t=1}^n \sum_{s_{\text{p},k}\in\mathcal{X}_{\text{p},k}} d(s_{\text{c},t}^{(q)},\;s_{\text{p},k},\;y_{t,k}).
        \end{split}
        \end{equation}
    If SIC is applied, the decoder for the private stream is based on $\widehat{W}_\text{c}$ and can be represented as
        \begin{equation}\label{equ: RSMA non-SIC decoding}
        \begin{split}
            \widehat{W}_k 
            =& \arg \max_{q\in{1,\;...,\;M_{\text{p},k}}} q^n(\mathbf{s}_{\text{p},k,t}^{(q)},\;\mathbf{y}_k)\\
            =& \arg \max_{q\in{1,\;...,\;M_{\text{p},k}}} \prod_{t=1}^n \; d(s_{\text{c},t}^{(\widehat{W}_\text{c})},\;s_{\text{p},t,k}^{(q)},\;y_{t,k}).
        \end{split}
        \end{equation}  
    If SIC is not applied,
        \begin{equation}\label{equ: CS-RSMA decoding}
        \begin{split}
            \widehat{W}_k 
            =& \arg \max_{q\in{1,\;...,\;M_k}} q^n(\mathbf{s}_{\text{p},k}^{(q)},\;\mathbf{y}_k)\\
            =& \arg \max_{q\in{1,\;...,\;M_k}} \prod_{t=1}^n \sum_{s_\text{c}\in\mathcal{X}_\text{c}} d(s_\text{c},\;s_{\text{p},t,k}^{(q)},\;y_{t,k}).
        \end{split}
        \end{equation}
    \item For CS-RSMA, let $\{\mathbf{s}_k^{(1)},\;...,\;\mathbf{s}_k^{(M_k)}\}$ represent the codebook for user-$k$ with $M_k$ being the codebook size, $\forall k \in \mathcal{K}$, and $s^{(q)}_{t,k}$ represent the symbol of $q$-th codeword at time instance $t$. The decoder can be represented as
        \begin{equation}
        \begin{split}
            \widehat{W}_k
            = \arg \max_{q\in{1,\;...,\;M_k}} &q^n(\mathbf{s}_k^{(q)},\;\mathbf{y}_k)\\
            = \arg \max_{q\in{1,\;...,\;M_k}} &\prod_{t'\in \mathcal{T}_k} \sum_{s_{k}\in\mathcal{X}_{\text{p},k}} d(s_{\tau_\text{c}(t'),k}^{(q)},\;s_{k},\;y_{t,k})\\
            &\prod_{t=1}^{n} \: \sum_{s_\text{c}\in\mathcal{X}_\text{c}} d(s_\text{c},\;s_{\tau_{\text{p},k}(t),k}^{(q)},\;y_{t,k}),
        \end{split}
        \end{equation}
    where $\mathcal{T}_k$ represents the time indices where the symbols of $\mathbf{s}_\text{c}$ are generated from $\mathbf{s}_{\text{c},k}$, and $\tau_\text{c}(\cdot)$ and $\tau_{\text{p},k}(\cdot)$ respectively maps the time index into the corresponding symbol index of user-$k$'s codeword.
\end{itemize}
Hence, computing $d(s_\text{c},\;s_{\text{p},k},\;y_{t,k})$, $\forall s_\text{c} \in \mathcal{X}_\text{c}$ and $\forall s_{\text{p},k} \in \mathcal{X}_{\text{p},k}$, covers all "$\exp(|\cdot|^2)$" operations required for (\ref{equ: RSMA SIC decoding})-(\ref{equ: CS-RSMA decoding}). This proves that complexity-$\delta$ is sufficient to decode conventional RSMA and CS-RSMA. It is also necessary to compute $d(s_\text{c},\;s_{\text{p},k},\;y_{t,k})$, $\forall s_\text{c} \in \mathcal{X}_\text{c}$ and $\forall s_{\text{p},k} \in \mathcal{X}_{\text{p},k}$, as long as, at each time instance and for each stream, the probability of any symbol in the alphabet occurring is non-zero.
\end{IEEEproof}

\section{Precoder Optimization}\label{sec: Opt algo}
We propose precoder optimization algorithms for SR and MMF optimization under finite alphabets and suboptimal decoders. The alphabets are assumed to be fixed in this section, but will be allowed to adjust adaptively in Section \ref{Sec: Opt results}. To reduce computational complexity, the approximation given by (\ref{MISO GMI approx}) is utilized in the optimization, but the performance evaluation in Section \ref{Sec: Opt results} will be based on the exact GMI given by (\ref{MISO GMI}).

\subsection{Sum-Rate Optimization}

We consider a sum-rate maximization problem as follows:
\begin{equation}
\begin{split}\label{equ: SR initial formulation}
    \mathcal{P}_1: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \: \: & \sum_{k\in\mathcal{K}} I_{\text{GMI},k}\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}\\
    & \mathbf{c}^T \mathbf{1} = 1\\
    & \mathbf{c} \succcurlyeq \mathbf{0},
\end{split}
\end{equation}
where $\mathbf{c} = [c_1,\;c_2,\;...,\;c_K]^T$.

\begin{proposition}[Sum-rate maximization reformulation]\label{SR max reformulation}
    Under different RSMA schemes, $\mathcal{P}_1$ can be simplified into the following formulations:
\begin{itemize}
    \item For conventional RSMA with or without SIC,
        \begin{equation}\label{equ: SR reformulation RSMA}
        \begin{split}
            \mathcal{P}_2: \;\; \underset{\mathbf{P}}{\max} \: \: 
            & \min_{k\in\mathcal{K}}\; I_{\text{c},k} + \sum_{k\in\mathcal{K}} I_{\text{p},k}^{\text{SIC/non-SIC}}\\ 
            \text{s.t.} \: \: \: \;
            & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}.\\
        \end{split}
        \end{equation}
    \item For CS-RSMA,
        \begin{equation}\label{equ: SR reformulation CS-RSMA}
        \begin{split}
            \mathcal{P}_3: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \: \: 
            & \max_{k\in\mathcal{K}}\; I_{\text{c},k} + \sum_{k\in\mathcal{K}} I_{\text{p},k}^{\text{non-SIC}}\\ 
            \text{s.t.} \: \: \: \;
            & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}.\\
        \end{split}
        \end{equation}
\end{itemize}
\end{proposition}

\begin{IEEEproof}
    (\ref{equ: SR reformulation RSMA}) is readily seen by substituting (\ref{equ: rate RSMA SIC}) and (\ref{equ: rate RSMA SIC-free}) into (\ref{equ: SR initial formulation}). For (\ref{equ: SR reformulation CS-RSMA}), substituting (\ref{equ: rate CS-RSMA}) into (\ref{equ: SR initial formulation}) leads to the following objective function:
    \begin{equation}
        \sum_{k\in\mathcal{K}} c_k I_{\text{c},k} + \sum_{k\in\mathcal{K}} I_{\text{p},k}^{\text{non-SIC}}.
    \end{equation}
    It is trivial to see that the optimal $\mathbf{c}$ is always given by having $c_k = 1$ for $k = \arg\max_k I_{\text{c},k}$, and $c_{k'} = 0$ for $k' \neq k$. Using this optimal $\mathbf{c}$ results in (\ref{equ: SR reformulation CS-RSMA}).
\end{IEEEproof}

\begin{remark}\label{Remark: SR min to max}
    An interesting difference between $\mathcal{P}_2$ and $\mathcal{P}_3$ is that the "$\min$" operator in $\mathcal{P}_2$ is replaced by "$\max$" in $\mathcal{P}_3$. This indicates that CS-RSMA is expected to perform at least as well as conventional RSMA without SIC in SR, since its problem formulation only differs from the latter by changing the "$\min$" to a "$\max$". The ranking between CS-RSMA and conventional RSMA with SIC is difficult to reveal analytically because, although CS-RSMA is disadvantaged in the omission of SIC, its common steam is not restricted to be decodable by all the users. 
\end{remark}

\begin{remark}
    To achieve the maximum SR of CS-RSMA, if the common stream is activated, the number of codewords to split is strictly one. In contrast, in conventional RSMA, the number of messages to split can be any number between 1 and $K$, as discussed in \cite{Sibo_TWC}.
\end{remark}

We further reformulate the problems in Proposition \ref{SR max reformulation} using the logarithmic barrier \cite{boyd2004convex} to approximate $\mathcal{P}_2$ and $\mathcal{P}_3$ as the following unconstrained optimization problem:
\begin{equation}\label{SR_unconstrained_form}
\begin{split}
    \mathcal{P}_4: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \;\; 
    & \tau\:I_{\text{sum}} + \log \left(P_\text{T} - \parallel\mathbf{P}\parallel_\text{F}^2\right),\\ 
\end{split}
\end{equation}
where $I_\text{sum}$ represents the objective function of $\mathcal{P}_2$ and $\mathcal{P}_3$ depending on the RSMA scheme in use, and $\tau$ is a parameter that sets the accuracy of the approximation.

For RSMA with SIC, one subgradient of $I_\text{sum}$ w.r.t. $\mathbf{P}$ is given by
\begin{equation}\label{equ: gradient SIC}
    g(I_\text{sum}) = 
    \nabla_\mathbf{P} I_{\text{c},k'} + \sum_{k\in\mathcal{K}} \nabla_\mathbf{P} I_{\text{p},k}^{\text{SIC}},
\end{equation}
where $k'= \arg \min_k I_{\text{c},k}$. For RSMA without SIC and CS-RSMA, 
\begin{equation}\label{equ: gradient CS-RSMA/non-SIC}
    g(I_\text{sum}) = 
    \nabla_\mathbf{P} I_{\text{c},k'} + \sum_{k\in\mathcal{K}} \nabla_\mathbf{P} I_{\text{p},k}^{\text{non-SIC}},
\end{equation}
where, for RSMA without SIC, $k'= \arg \min_k I_{\text{c},k}$ and, for CS-RSMA, $k'= \arg \max_k I_{\text{c},k}$. The gradients in (\ref{equ: gradient SIC}) and (\ref{equ: gradient CS-RSMA/non-SIC}) can be computed by referring to (\ref{equ: common rate})-(\ref{equ: private rate non-SIC}) and (\ref{equ: MISO GMI approx gradient}). 

It can be noticed that the problems described by $\mathcal{P}_1-\mathcal{P}_4$ are non-convex due to the non-convexity of (\ref{MISO GMI}) and (\ref{MISO GMI approx}) w.r.t. the precoders, and non-smooth due to the "$\min$/$\max$" operators over $k$. Hence, it is difficult to obtain the global optimal solutions of them. We use the subgradient descent method to optimize $\mathcal{P}_4$. The complete algorithm is summarized in Alg. \ref{alg: GD for SR opt}, with $\Omega_\text{SR}(\mathbf{P})$ representing the objective function in $\mathcal{P}_4$. Alg. \ref{alg: GD for SR opt} is guaranteed to converge because each update on $\mathbf{P}$ leads to a non-decreasing update on the objective function, and the objective function is clearly upper-bounded.


\begin{algorithm}[!t]
    \caption{Subgradient Ascent with Barrier Method for Sum-Rate Maximization}
    \label{alg: GD for SR opt}
    \begin{algorithmic}[1]
        \REQUIRE $P_\text{T}$, $\mathcal{X}_\text{c}$, $\mathcal{X}_{\text{p},k}$, $\mathbf{h}_k$, $k\in\mathcal{K}$, $\beta$, $\epsilon$, $v_\text{max}$, $\tau_\text{max}$.
        \ENSURE $\mathbf{P}^\star$
        \STATE Initialize $\mathbf{P}^0$ and $\tau$.
        \REPEAT 
            \STATE $v:=0$.
            \REPEAT
                \STATE $\Delta\mathbf{P} := \tau\:g( I_\text{sum}) + \frac{\mathbf{P}^v}{\parallel \mathbf{P}^v \parallel_\text{F}^2 - P_\text{T}}$.
                \STATE Choose step size $\alpha$ via backtracking line search.
                \STATE Update. $\mathbf{P}^{v+1} := \mathbf{P}^v + \alpha \Delta\mathbf{P}$.
                \STATE Update. $\Omega_\text{SR}^{v+1} := \Omega_\text{SR}(\mathbf{P}^{v+1})$.
                \STATE $v:=v+1$.
            \UNTIL $\mid \Omega_\text{SR}^{v} - \Omega_\text{SR}^{v-1} \mid\; < \epsilon$ or $v \geq v_\text{max}$.
            \STATE Update $\tau := \beta \tau$.
        \UNTIL $\tau \geq \tau_\text{max}$.
        \RETURN $\mathbf{P}^\star := \mathbf{P}^{v}$.
    \end{algorithmic}
\end{algorithm}

\subsection{Minimum Rate Optimization}
We now consider a max-min fairness problem as follows:
\begin{equation}\label{Max_min}
\begin{split}
    \mathcal{P}_5: \;\; \underset{\mathbf{P},\mathbf{c}}{\max} \: \: & \min_{k\in\mathcal{K}}\: \: I_{\text{GMI},k}\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}\\
    & \mathbf{c}^T \mathbf{1} = 1\\
    & \mathbf{c} \succcurlyeq \mathbf{0}.
\end{split}
\end{equation}

$\mathcal{P}_5$ is a non-convex problem. To solve it efficiently, we decouple it into the following two sub-problems,
\begin{equation}\label{Max_min_sub_c}
\begin{split}
    \mathcal{P}_6: \;\; \underset{\mathbf{c}}{\max} \: \: & \min_{k\in\mathcal{K}}\: \: I_{\text{GMI},k}(\mathbf{c};\;\mathbf{P})\\ 
    \text{s.t.} \: \: \: \;
    & \mathbf{c}^T \mathbf{1} = 1\\
    & \mathbf{c} \succcurlyeq \mathbf{0},
\end{split}
\end{equation}
and
\begin{equation}\label{Max_min_sub_P}
\begin{split}
    \mathcal{P}_7: \;\; \underset{\mathbf{P}}{\max} \: \: & \min_{k\in\mathcal{K}}\: \: I_{\text{GMI},k}(\mathbf{P};\;\mathbf{c})\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}.
\end{split}
\end{equation}
$\mathcal{P}_6$ optimizes $\mathbf{c}$ with a fixed $\mathbf{P}$, whereas $\mathcal{P}_7$ optimizes $\mathbf{P}$ with a given $\mathbf{c}$. Note that $\mathcal{P}_6$ is a linear programming, and hence its global optimal solution can be efficiently obtained. In particular, we developed a closed-form solution as in Proposition \ref{c_opt_prop}.

\begin{proposition}\label{c_opt_prop}
    The global optimal solution of $\mathcal{P}_6$ is given in closed form by Alg. \ref{alg: c_opt}.
\end{proposition}
\begin{IEEEproof}
    See Appendix B.
\end{IEEEproof}

\begin{algorithm}[!t]
    \caption{Global Optimal Common Stream Allocation}
    \label{alg: c_opt}
    \begin{algorithmic}[1]
        \REQUIRE $I_{\text{c},k}$, $I_{\text{p},k}$, $k\in\mathcal{K}$.
        \ENSURE $\mathbf{c}^\star$
        \STATE $I_{\text{c},k}':=\min_k \;I_{\text{c},k}$ for conventional RSMA and\\ $I_{\text{c},k}':=I_{\text{c},k}$ for CS-RSMA.
        \STATE $k':=K$.
        \REPEAT 
            \STATE $\mathbf{A} := \text{diag}\{[I'_{\text{c},1},\;...,\;I'_{\text{c},k'}]\}$, $\mathbf{b} :=[I_{\text{p},1},\;...,\;I_{\text{p},k'}]^T$.
            \STATE $\xi := \frac{1+\mathbf{1}^T\mathbf{A}^{-1}\mathbf{b}}{\mathbf{1}^T\mathbf{A}^{-1}\mathbf{1}}$.
            \STATE $\mathbf{c}' := \xi\mathbf{A}^{-1}\mathbf{1} - \mathbf{A}^{-1}\mathbf{b}$.
            \STATE $k':=k'-1$.
        \UNTIL $\mathbf{c}'\succcurlyeq 0$.
        \RETURN $\mathbf{c}^\star := [\mathbf{c}'^T,\; \mathbf{0}^{1\times (K-k'-1)}]^T$.
    \end{algorithmic}
\end{algorithm}

To remove the discontinuity caused by the point-wise minimum in $\mathcal{P}_7$, we apply a log-sum-exp approximation to its objective function and consider $\mathcal{P}_8$ as follows:
\begin{equation}\label{Max_min_LSE}
\begin{split}
    \mathcal{P}_8: \;\; \underset{\mathbf{P}}{\max} \: \: & \frac{1}{\gamma}\log \sum_{k\in\mathcal{K}} \exp \: \: \left(\beta I_{\text{GMI},k}(\mathbf{P};\;\mathbf{c})\right)\\ 
    \text{s.t.} \: \: \: \;
    & \|\mathbf{P}\|_\text{F}^2 \leq P_\text{T}.
\end{split}
\end{equation}
 The gap between point-wise minimum and its log-sum-exp approximation is characterized by the following inequality \cite{Chen_2013},
 \begin{equation}
     0\leq \min_{1\leq i \leq L} f_i - \frac{1}{\gamma}\log\sum_{i=1}^L\exp(\gamma f_i) \leq \frac{1}{\gamma}\log L,\;\;\; \gamma < 0.
 \end{equation}

A subgradient of the objective function in $\mathcal{P}_8$ w.r.t. $\mathbf{P}$ is derived to be
\begin{equation}
\begin{split}
    g(I_\text{max-min}) = &\frac{1}{\gamma}\frac{\sum_{k\in\mathcal{K}} \beta\exp \: \: \left(\beta I_{\text{GMI},k}(\mathbf{P};\mathbf{c})\right) g(I_{\text{GMI},k}(\mathbf{P};\mathbf{c}))}{\sum_{k\in\mathcal{K}} \exp \: \: \left(\beta I_{\text{GMI},k}(\mathbf{P};\mathbf{c})\right)},
\end{split}
\end{equation}
with
\begin{equation}
    g(I_{\text{GMI},k}(\mathbf{P};\mathbf{c})) = c_k g(I_{\text{c}}) + \nabla_\mathbf{P} I_{\text{p},k},
\end{equation}
where $g(I_{\text{c}}) = \nabla_\mathbf{P} I_{\text{c},k'}^{\text{SIC/non-SIC}}$ with $k' = \arg\min_k I_{\text{c},k'}^{\text{SIC/non-SIC}}$ for RSMA with/without SIC, and  $g(I_{\text{c}}) = \nabla_\mathbf{P} I_{\text{c},k}^{\text{non-SIC}}$ for CS-RSMA.

Similarly to (\ref{SR_unconstrained_form}), the inequality constraint in $\mathcal{P}_8$ can be integrated into the objective function through the logarithmic barrier. This leads to
\begin{equation}\label{Max_min_unconstrained_form}
\begin{split}
    \mathcal{P}_9: \;\; \underset{\mathbf{P}}{\max} \: \: & \frac{\tau}{\gamma}\log \sum_{k\in\mathcal{K}} \exp \: \: \left(\gamma I_{\text{GMI},k}(\mathbf{c})\right) + \log \left(P_\text{T} - \parallel\mathbf{P}\parallel_\text{F}^2\right).\\ 
\end{split}
\end{equation}
$\mathcal{P}_9$ can be solved using subgradient ascent. The solution of $\mathcal{P}_5$ is obtained by solving $\mathcal{P}_6$ and $\mathcal{P}_9$ alternatively and the steps are summarized in Alg. \ref{alg: GD for Max_min opt}, with $\Omega_\text{MMF}(\mathbf{P})$ representing the objective function in $\mathcal{P}_9$. Alg. \ref{alg: GD for Max_min opt} is guaranteed to converge because each update on $\mathbf{P}$ and $\mathbf{c}$ leads to a non-decreasing update on the objective function, and the objective function is clearly upper-bounded.

\begin{algorithm}[!t]
    \caption{Subgradient Ascent with Barrier Method for Max-Min Fairness}
    \label{alg: GD for Max_min opt}
    \begin{algorithmic}[1]
        \REQUIRE $P_\text{T}$, $\mathcal{X}_\text{c}$, $\mathcal{X}_{\text{p},k}$, $\mathbf{h}_k$, $k\in\mathcal{K}$, $\beta$, $\gamma$, $\epsilon$, $v_\text{max}$, $\tau_\text{max}$.
        \ENSURE $\mathbf{P}^\star$ and $\mathbf{c}^\star$
        \STATE Initialize $\mathbf{P}^0$ and $\tau$.
        \REPEAT 
            \STATE $v:=0$.
            \REPEAT
                \STATE Update $I_{\text{c},k}$, $I_{\text{p},k}$ based on $\mathbf{P}^v$.
                \STATE Update $\mathbf{c}$ using Alg. \ref{alg: c_opt}.
                \STATE $\Delta\mathbf{P} := \tau\:g( I_\text{max-min}) + \frac{\mathbf{P}^v}{\parallel \mathbf{P}^v \parallel_\text{F}^2 - P_\text{T}}$.
                \STATE Choose step size $\alpha$ via backtracking line search.
                \STATE Update. $\mathbf{P}^{v+1} := \mathbf{P}^v + \alpha \Delta\mathbf{P}$.
                \STATE Update. $\Omega_\text{MMF}^{v+1} := \Omega_\text{MMF}(\mathbf{P}^{v+1})$.
                \STATE $v:=v+1$.
            \UNTIL $\mid \Omega_\text{MMF}^{v} - \Omega_\text{MMF}^{,v-1} \mid\; < \epsilon$ or $v \geq v_\text{max}$.
            \STATE Update $\tau := \beta \tau$.
        \UNTIL $\tau \geq \tau_\text{max}$.
        \RETURN $\mathbf{P}^\star := \mathbf{P}^{v}$ and $\mathbf{c}^\star := \mathbf{c}$.
    \end{algorithmic}
\end{algorithm}
