\section*{Appendix A --- Orthogonality relations} 

\paragraph{} This Appendix shows the orthogonality relations for the shifted Legendre polynomials which we use in the derivation of the governing equations:

\begin{equation*}
\begin{aligned}
    \int_0^L P_n \qty(\frac{x-L/2}{L/2}) P_m \qty(\frac{x-L/2}{L/2}) dx = \frac{L}{2} \int_{-1}^1 P_n(u) P_m(u) du \\
    = \frac{L}{2n+1}\delta_{nm} := \delta_P(n,m).
\end{aligned}
\end{equation*}



\section*{Appendix B --- Term calculations}

\paragraph{} This Appendix shows calculations of the terms in the discretized variational energy for thermoelastic plate bending:


\begin{equation*}
    \int u_{3,11}^2 dA = \sum_{i=0}^{N^2-1} \sum_{j=0}^{N^2-1} a_i a_j \int \int \Phi_{i,11} \Phi_{j,11} dx_1 dx_2.
\end{equation*}

\begin{equation*}
    \int u_{3,22}^2 dA = \sum_{i=0}^{N^2-1} \sum_{j=0}^{N^2-1} a_i a_j \int \int \Phi_{i,22} \Phi_{j,22} dx_1 dx_2 .
\end{equation*} 

\begin{equation*}
    \int u_{3,12}^2 dA = \sum_{i=0}^{N^2-1} \sum_{j=0}^{N^2-1} a_i a_j \int \int \Phi_{i,12} \Phi_{j,12} dx_1 dx_2.
\end{equation*} 

\begin{equation*}
    \int u_{3,11} u_{3,22} dA = \sum_{i=0}^{N^2-1} \sum_{j=0}^{N^2-1} a_i a_j \int \int \Phi_{i,11} \Phi_{j,22} dx_1 dx_2.
