\begin{equation*}
    \int \tau \Big( u_{3,11} + u_{3,22} \Big) dA = \\ \sum_{i=0}^{N^2-1} \sum_{j=0}^{N^2-1} t_i a_j \int \int \Big( \Phi_{i} \Phi_{j,11} + \Phi_{i} \Phi_{j,22} \Big) dx_1 dx_2. 
