\section*{Appendix C --- Integral calculations}

\paragraph{} This appendix shows how orthogonality can be used to expedite populating the stiffness matrix and force vector. Orthogonality of the shape functions is used so that zero entries can be recognized without carrying out the integrals. Integrals are computed over $(x_1,x_2) \in [0,L_1] \times [0,L_2]$ and the integrals factorize because the shape functions have a tensor product structure. Note that derivatives of Legendre polynomials are not themselves Legendre polynomials, thus orthogonality does not apply to them. The following manual calculations are used to expedite the numerical implementation:


\begin{equation*}
    \begin{aligned}
    \int \Phi_{i,11} \Phi_{j,11} dA = \int \frac{\partial^2}{\partial x_1^2} P_{i//N} \frac{\partial^2}{\partial x_1^2} P_{j//N} dx_1 \int P_{i\%N} P_{j\%N} dx_2 \\
    = \qty(\int \frac{\partial^2}{\partial x_1^2} P_{i//N} \frac{\partial^2}{\partial x_1^2} P_{j//N} dx_1) \delta_{P}(i\%N, j\%N) .
    \end{aligned}
\end{equation*}

\begin{equation*}
    \begin{aligned}
         \int \Phi_{i,22} \Phi_{j,22} dA = \int P_{i//N} P_{j//N} dx_1 \int \frac{\partial^2}{\partial x_1^2} P_{i\%N} \frac{\partial^2}{\partial x_1^2} P_{j\%N} dx_2 \\
         = \delta_{P}(i//N, j//N) \qty(\int \frac{\partial^2}{\partial x_1^2} P_{n\%N} \frac{\partial^2}{\partial x_1^2} P_{i\%N} dx_2).
    \end{aligned}
\end{equation*}


\begin{equation*}
     \int \Phi_{i,11} \Phi_{j,22} dA = \int \frac{\partial^2}{\partial x_1^2}P_{i//N} P_{j//N} dx_1 \int P_{i\%N} \frac{\partial^2}{\partial x_2^2} P_{j\%N} dx_2.
\end{equation*}


\begin{equation*}
    \begin{aligned}
        \int \Phi_i \Phi_j dA = \int P_{i//N} P_{j//N} dx_1 \int P_{i\%N} P_{j\%N} dx_2 \\
         = \delta_P(i//N,j//N) \delta_P(i\%N,j\%N).
    \end{aligned}
\end{equation*}


\begin{equation*}
    \begin{aligned}
        \int \Phi_i \Phi_{j,11} dA = \int P_{i//N} \frac{\partial^2}{\partial x_1^2}P_{j//N} dx_1 \int P_{i\%N} P_{j\%N} dx_2  \\
        =\qty( \int P_{i//N} \frac{\partial^2}{\partial x_1^2}P_{j//N} dx_1) \delta_P(i\%N,j\%N).
    \end{aligned}
\end{equation*}

\begin{equation*}
    \begin{aligned}
        \int \Phi_i \Phi_{j,22} dA = \int P_{i//N} P_{j//N} dx_1 \int P_{i\%N} \frac{\partial^2}{\partial x_2^2} P_{j\%N} dx_2 \\
        = \delta_P(i//N,j//N)  \qty(\int P_{i\%N} \frac{\partial^2}{\partial x_2^2} P_{j\%N} dx_2).
    \end{aligned}
\end{equation*}


\section*{Appendix D --- Thermal finite element analysis}

\paragraph{} Working with rectangular plates, it is possible to use spectral basis functions to obtain a solution. On more complicated plate geometries, it will be necessary to employ the finite element method. This raises the question of how the method we have developed can be transferred to existing thermoelastic finite element codes. To do this, we can calculate a temperature distribution that gives rise to the thermal moment associated with shot peening at a given intensity. By definition,

\begin{equation*}
    \tau = KI = \int_{-h/2}^{h/2}x_3\alpha T dx_3.
\end{equation*}

We want to find the temperature distribution $T(x_3)$ which gives rise to the known thermal moment $\tau$. The moment-intensity tests/results are used to associate the thermal moment and shot peen intensity via the constant $K$. Obviously, there isn't a unique solution as the temperature could take many forms while leaving this integral unchanged. For simplicity, we can assume that the temperature distribution is linear about the midpoint of the plate, i.e. $T(x_3)=T_0x_3$. We can then calculate the slope $T_0$:

\begin{equation*}
    \tau = \int_{-h/2}^{h/2}\alpha T_0 x_3^2 dx_3 = \frac{\alpha T_0h^3}{12} \implies T_0 = \frac{12KI}{\alpha h^3}.   
\end{equation*}

As expected, the slope of the temperature distribution increases with the shot peen intensity. Though the choice of a linear temperature distribution is arbitrary, it might be justified as a way to enforce the assumption of strain which is linearly distributed through the plate thickness as the Kirchhoff model requires. Thus, an existing thermoelastic finite element code can predict displacements from a given map of shot peen intensity by applying the appropriate temperature distribution at each point in the plate. 

\end{appendix}


