%     \item $\sigma^2$ is the stochastic process variance (Section~\ref{sub:gp}),
%     \item $R_A$ is the polynomial surrogate regression matrix (Eq.~(\ref{eq:RA})), and
%     \item $u(x) = R_A^T C^{-1} c^T(x) - r_A(x)$ where $r_A(x) = \left( L_{\alpha}(x) \right)_{\alpha \in A}$ (Sections~\ref{chap: polynomial interpolation} and \ref{chap: polynomial regression}).
