\subsubsection{Problem Transformation} 
We can rewrite ${\rm{R }}$ in (\ref{Za}) as:
\begin{equation}
\label{eq24}
\begin{split}
{\rm{R }}&=\sum\limits_{m{\rm{ = 1}}}^M {{\rm{lo}}{{\rm{g}}_{\rm{2}}}{\rm{(1 + SIN}}{{\rm{R}}_m}{\rm{)}}}  \\
 &= \sum\limits_{m{\rm{ = 1}}}^M {{{\log }_2}\left( {\frac{{\sum\limits_{i = 1}^M {{{\left| {{{\bf{f}}_m^H}{{\bf{H}}_m}{\bf{V}}{{\bf{w}}_i}} \right|}^2} + \sigma _m^2{N_r}} }}{{\sum\limits_{i = 1,i \ne m}^M {{{\left| {{{\bf{f}}_m^H}{{\bf{H}}_m}{\bf{V}}{{\bf{w}}_i}} \right|}^2} + \sigma _m^2{N_r}} }}} \right)}  \\
& = {\log _2}\left( {\frac{{\det \left( {\left( {{\bf{\Phi }}{{\bf{\Phi }}^H}} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right)}}{{\det \left\{ {\left( {{\bf{\Phi }}\left( {{{\bf{\Phi }}^H} \odot {\bf{I}}_M^ - } \right)} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right\}}}} \right)\\
& =- {\log _2}\left( {\frac{{\det \left\{ {\left( {{\bf{\Phi }}\left( {{{\bf{\Phi }}^H} \odot {\bf{I}}_M^ - } \right)} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right\}}}{{\det \left( {\left( {{\bf{\Phi }}{{\bf{\Phi }}^H}} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right)}}} \right),
\end{split}
\end{equation}
where the received signal matrix ${\bf{\Phi }}$ we introduced as an intermediate variable, which is defined as follows:
\begin{equation}
\label{eq26}
\begin{split}
{\bf{\Phi }} &= {\bf{FHVW}} \\
&  = \left[ {\begin{array}{*{20}{c}}
{{\bf{f}}_1^H{{\bf{H}}_1}{\bf{V}}{{\bf{w}}_1}}&{{\bf{f}}_1^H{{\bf{H}}_1}{\bf{V}}{{\bf{w}}_2}}& \cdots &{{\bf{f}}_1^H{{\bf{H}}_1}{\bf{V}}{{\bf{w}}_M}}\\
{{\bf{f}}_2^H{{\bf{H}}_2}{\bf{V}}{{\bf{w}}_1}}&{{\bf{f}}_2^H{{\bf{H}}_2}{\bf{V}}{{\bf{w}}_2}}& \cdots &{{\bf{f}}_2^H{{\bf{H}}_2}{\bf{V}}{{\bf{w}}_M}}\\
 \vdots & \vdots & \ddots & \vdots \\
{{\bf{f}}_M^H{{\bf{H}}_M}{\bf{V}}{{\bf{w}}_1}}&{{\bf{f}}_M^H{{\bf{H}}_M}{\bf{V}}{{\bf{w}}_2}}& \cdots &{{\bf{f}}_M^H{{\bf{H}}_M}{\bf{V}}{{\bf{w}}_M}}
\end{array}} \right],
\end{split}
\end{equation}
where the $i$-th row of ${\bf{\Phi }}$ represents the signal received from the BS by the $i$-th UE,  ${i = 1,2 \cdots M}$. ${\bf{F}} \in {\mathbb{C}^{M \times M{N_r}}}$ is a block diagonal matrix  as $
{\bf{F}} = {\rm{blkdiag}}({\bf{f}}_1^H,{\bf{f}}_2^H \cdots {\bf{f}}_M^H)$,
and ${\bf{H}} = {\left[ {{\bf{H}}_1^T,{\bf{H}}_2^T, \cdots {\bf{H}}_M^T} \right]^T} \in {\mathbb{C}^{M{N_r} \times {N_t}}}$ represents the combined channel from the BS to all users.  ${{{\bf{I}}_M}}$ represents a unit matrix of dimension $M$. ${\bf{I}}_M^ -  \in {\mathbb{C}^{M \times M}}$ represents the matrix with all diagonal elements zero and all non-diagonal elements one. 
%It can be expressed as:
%\begin{equation}
%\label{eq25}
%{\bf{I}}_M^ -  = \left[ {\begin{array}{*{20}{c}}
%{\rm{0}}&{\rm{1}}& \cdots &{\rm{1}}\\
%{\rm{1}}&{\rm{0}}& \cdots &{\rm{1}}\\
% \vdots & \vdots & \ddots & \vdots \\
%{\rm{1}}&{\rm{1}}& \cdots &{\rm{0}}
%\end{array}} \right]{\rm{.}}
%\end{equation}
${{\bf{R}}_n} = {N_r} \cdot {\rm{blkdiag}}(\sigma _1^2,\sigma _2^2 \cdots \sigma _M^2) \in {\mathbb{C}^{M \times M}}$ represents the noise variance matrix of $M$ users. At this point, when ${\bf{W}}$ is fixed, maximizing the sum rate problem can be converted to:
\begin{subequations}
\begin{align}
\label{eq27}
\mathop {\min }\limits_{{\bf{V,F}}} \quad&{g_2}{\rm{(}}{\bf{V}},{\bf{F}}{\rm{) }} \\
\mbox{s.t.}\quad
&{\rm{            }}{\bf{V}} = {\rm{blkdiag}}({{\bf{v}}_1},{{\bf{v}}_2} \cdots {{\bf{v}}_{{N_{RF}}}}), \\
&{\rm{            }}{\bf{F}} = {\rm{blkdiag}}({{\bf{f}}_1},{{\bf{f}}_2} \cdots {{\bf{f}}_M}),{\rm{ }} \\
&{\rm{            }}{{\bf{v}}_i}(j) \in {\cal V},{{\bf{f}}_i}(j) \in {\cal F},{\rm{ }}\forall i,\forall j 
\end{align}
\end{subequations}
where the objective function ${g_2}$ can be expressed as:
\begin{equation}
\label{eq28}
\begin{split}
{g_2}\left( {{\bf{V}},{\bf{F}}} \right) &= {\log _2}\det \left\{ {\left( {{\bf{\Phi }}\left( {{{\bf{\Phi }}^H} \odot {\bf{I}}_M^ - } \right)} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right\}\\
&  - {\log _2}\det \left( {\left( {{\bf{\Phi }}{{\bf{\Phi }}^H}} \right) \odot {{\bf{I}}_M} + {{\bf{R}}_n}} \right).
\end{split}
\end{equation}

In this way, we have converted the  multiuser sum rate maximization problem into a  matrix multiplication minimization problem, eliminating the summation term and facilitating the subsequent derivation calculations.

\subsubsection{Proposed PMO Algorithm} 
The function ${g_2}$ is nonconvex and the constraints on the variables ${\bf{V}}$ and ${\bf{F}}$ are both nonconvex. It is difficult to solve this problem using traditional methods. In fact, define the sets in the constraints as ${{\cal S}_1} = \left\{ {{\bf{V}}:{\bf{V}} = {\rm{blkdiag}}({{\bf{v}}_1},{{\bf{v}}_2} \cdots {{\bf{v}}_{{N_{RF}}}}),{\rm{ }}\left| {{{\bf{v}}_i}(j)} \right| = 1,\forall i,j} \right\}$ and ${{\cal S}_2} = \left\{ {{\bf{F}}:{\bf{F}} = {\rm{blkdiag}}({{\bf{f}}_1},{{\bf{f}}_2} \cdots {{\bf{f}}_{{N_{RF}}}}),{\rm{ }}\left| {{{\bf{f}}_i}(j)} \right| = 1,\forall i,j} \right\}$, they are manifolds. And define the set ${\cal S} = {{\cal S}_1} \times {{\cal S}_2}$, which is known as the product of manifolds ${{\cal S}_1}$ and ${{\cal S}_2}$ \cite{ref31,ref32}.
We can see that the constraints for the variables ${\bf{V}}$ and ${\bf{F}}$ are on the manifold space   $\left( {{\bf{V}},{\bf{F}}} \right)\in {\cal S}$ and we can solve this complex problem based on the theory of manifold optimization.
In this paper, we propose the PMO algorithm based on the Riemann conjugate gradient algorithm to optimize ${\bf{V}}$ and ${\bf{F}}$ simultaneously.
%[8] P.-A. Absil, R. Mahony, and R. Sepulchre, Optimization Algorithms on Matrix Manifolds. Princeton, NJ, USA: Princeton Univ. Press, 2009.

The main idea of the PMO algorithm is to search for a sequence of $\left( {{{\bf{V}}_k},{{\bf{F}}_k}} \right),k = 0,1, \cdots  $ in the product manifold ${\cal S}$, such that the objective function ${g_2}{\rm{(}}{\bf{V}},{\bf{F}}{\rm{)}}$ is optimized with iterations. When convergence is reached, the PMO algorithm returns a solution that is the point at which the Riemannian gradient is zero. The solution is a suboptimal solution to problem (\ref{eq27}). The main advantage of this algorithm is that it can directly deal with non-convex (without any approximation) complex problems by means of the  theory of manifold optimization \cite{ref32} and it requires lower computational complexity compared to traditional methods.
%[6] L. Zhang, Y. Wang, W. Tao, Z. Jia, T. Song, and C. Pan, “Double Intelligent Reflecting Surface for Secure Transmission with Inter-Surface Signal Reflection,”
%[8] P.-A. Absil, R. Mahony, and R. Sepulchre, Optimization Algorithms on Matrix Manifolds. Princeton, NJ, USA: Princeton Univ. Press, 2009.

We first give the tangent space of the manifold ${\cal S}$ at the point $\left( {{\bf{V}},{\bf{F}}} \right)$.  For any point ${\bf{V}} \in {{\cal S}_1}$ and ${\bf{F}} \in {{\cal S}_2}$, the tangent space passes tangentially through $\left( {{\bf{V}},{\bf{F}}} \right)$. Since manifold ${\cal S}$ is a product manifold, the corresponding tangent space ${T_{\left( {{\bf{V}},{\bf{F}}} \right)}}{\cal S}$ can be decomposed into the product of two tangent spaces, denoted by:
\begin{equation}
\label{eq29}
{T_{\left( {{\bf{V}},{\bf{F}}} \right)}}{\cal S} = {T_{\bf{V}}}{{\cal S}_1} \times {T_{\bf{F}}}{{\cal S}_2},
\end{equation}
where ${T_{\bf{V}}}{{\cal S}_1} = \left\{ {{{\bf{Z}}_1} \in {\mathbb{C}^{{N_t} \times {N_{RF}}}}\left| {{\mathop{\rm Re}\nolimits} \left\{ {{{\bf{Z}}_1} \odot {{\bf{V}}^*}} \right\} = {\bf{0}}} \right.} \right\},$ ${T_{\bf{F}}}{{\cal S}_2} = \left\{ {{{\bf{Z}}_2} \in {\mathbb{C}^{M \times M{N_r}}}\left| {{\mathop{\rm Re}\nolimits} \left\{ {{{\bf{Z}}_2} \odot {{\bf{F}}^*}} \right\} = {\bf{0}}} \right.} \right\},$ ${{\bf{Z}}_1}$ and ${{\bf{Z}}_2}$ are tangent vectors at points $\bf{V}$ and $\bf{F}$, respectively.


Under the concept of tangent space, the next key part of the PMO algorithm is to calculate the Riemannian gradient, which is the tangent direction in which the objective function decreases the fastest among all tangent vectors in the tangent space. Since ${{\cal S}_1} \in {\mathbb{C}^{{N_t} \times {N_{RF}}}}$ and ${{\cal S}_2} \in {\mathbb{C}^{M \times M{N_r}}}$ are subspaces of the Euclidean space, according to \cite{ref32}, the Riemannian  gradient can be computed as the orthogonal projection of the conventional Euclidean gradient into the Riemannian tangent space. Specifically,  it can be shown as:
\begin{equation}
\label{eq30}
gra{d_{{{\bf{V}}_k}}}{g_2} = Gra{d_{{{\bf{V}}_k}}}{g_2} - {\mathop{\rm Re}\nolimits} \left\{ {Gra{d_{{{\bf{V}}_k}}}{g_2} \odot {\bf{V}}_k^*} \right\} \odot {{\bf{V}}_k},
\end{equation}
\begin{equation}
\label{eq31}
gra{d_{{{\bf{F}}_k}}}{g_2} = Gra{d_{{{\bf{F}}_k}}}{g_2} - {\mathop{\rm Re}\nolimits} \left\{ {Gra{d_{{{\bf{F}}_k}}}{g_2} \odot {\bf{F}}_k^{\rm{*}}} \right\} \odot {{\bf{F}}_k},
\end{equation}
where $\left( {{{\bf{V}}_k},{{\bf{F}}_k}} \right)$ represents the iterative results obtained in the $k$-th search. $gra{d_{{{\bf{V}}_k}}}{g_2}$ stands for the Riemannian gradient of ${{\bf{V}}_k}$, and $Gra{d_{{{\bf{V}}_k}}}{g_2}$ is its Euclidean gradient. The same goes for ${gra{d_{{{\bf{F}}_k}}}{g_2}}$  and $ {Gra{d_{{{\bf{F}}_k}}}{g_2}}$.


Next we compute the Euclidean gradient of the objective function  $g_2$ with respect to  ${{\bf{F}}_k}$. The objective function is differentiated with respect to ${{\bf{F}}_k}$ and we can obtain the differential $d{g_2}$ as
\begin{equation}
\label{eq32}
{\rm{ }}d{g_2}{\rm{ = Tr}}\left\{ {{{\bf{A}}_k}\left( {d{{\bf{F}}_k}} \right)} \right\},
\end{equation} 
where  ${{\bf{A}}_k}$ is shown in equation (\ref{eq33}), which is calculated specifically in Appendix A. ${{\bf{F}}_k}$ is a block diagonal matrix and the Euclidean gradient can be expressed as:
\begin{equation}
\label{eq35}
Gra{d_{{{\bf{F}}_k}}}{g_2} = {\bf{A}}_k^H \odot {{\bf{P}}_1},
\end{equation}
where ${{\bf{P}}_1} = {\rm{blkdiag}}\left( {{{\left( {{\bf{p}}_1^{\left( 1 \right)}} \right)}^H},{{\left( {{\bf{p}}_1^{\left( 2 \right)}} \right)}^H} \cdots {{\left( {{\bf{p}}_1^{\left( M \right)}} \right)}^H}} \right)$ is a block diagonal matrix and has the same matrix structure as ${\bf{F}}$, and ${\bf{p}}_1^{\left( 1 \right)} = {\bf{p}}_1^{\left( 2 \right)} =  \cdots {\bf{p}}_1^{\left( M \right)} = {{\bf{1}}_{{N_r}}}$.


