\label{eq49}
 {\cal R}({\bf{X}}(i,j)) = \frac{{{\bf{X}}(i,j)}}{{\left| {{\bf{X}}(i,j)} \right|}},\forall i,j.
  \end{equation}
This ensures that each non-zero element has a unit modulus.


\begin{algorithm}[t]
	\caption{PMO Algorithm for RIMSA Configuration}\label{alg:PMO}
	\begin{algorithmic}[t]
		\REQUIRE: $\varepsilon  > 0$, $c,\tau  \in \left( {0,1} \right)$ and initial point ${{\bf{F}}_0}$ and ${{\bf{V}}_0}$
		\STATE Set $k=0$, $\mu _0^{{\bf{F}}} =\mu _0^{{\bf{V}}}= 0$, ${{\bf{\Pi }}_{{{\bf{F}}_0}}} =  - gra{d_{{{\bf{F}}_0}}}{g_2}$ and ${{\bf{\Pi }}_{{{\bf{V}}_0}}} =  - gra{d_{{{\bf{V}}_0}}}{g_2}$
		\REPEAT
		\STATE Calculate search step size ${\alpha _k}$ according to backtracking line search algorithm, and find the next point ${{\bf{F}}_{k + 1}}$ and ${{\bf{V}}_{k + 1}}$  by (\ref{eq44}) and (\ref{eq48}).  
		\STATE Find the Riemannian gradient of the new point ${gra{d_{{{\bf{F}}_{k + 1}}}}{g_2}}$ and ${gra{d_{{{\bf{V}}_{k + 1}}}}{g_2}}$ according to Eq. (\ref{eq31}) and Eq. (\ref{eq30}).
		\STATE Calculate the vector transfer factor ${T_{{{\bf{F}}_k} \to {{\bf{F}}_{k + 1}}}}\left( {{{\bf{\Pi }}_{{{\bf{F}}_k}}}} \right)$ and ${T_{{{\bf{V}}_k} \to {{\bf{V}}_{k + 1}}}}\left( {{{\bf{\Pi }}_{{{\bf{V}}_k}}}} \right)$ through Eq. (\ref{eq45}).
		\STATE Calculate Polak-Ribière parameter $\mu _{k + 1}^{{\bf{F}}}$ and $\mu _{k + 1}^{{\bf{V}}}$ according to Eq. (\ref{eq46}).
		\STATE Calculate the search direction ${{\bf{\Pi }}_{{{\bf{F}}_{k + 1}}}}$ and ${{\bf{\Pi }}_{{{\bf{V}}_{k + 1}}}}$ by Eq. (\ref{eq41}) and Eq. (\ref{eq43}).
		\STATE $k=k+1$.
		\UNTIL{${\left\| {gra{d_{{{\bf{F}}_k}}}{g_2}} \right\|_F} + {\left\| {gra{d_{{{\bf{V}}_k}}}{g_2}} \right\|_F} < \varepsilon $}
	\end{algorithmic}
	%\label{alg1}
\end{algorithm}
\begin{algorithm}[t]
	\caption{ FP-PMO Algorithm for Multi-user MISO Systems }\label{alg2}
	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\begin{algorithmic}[1]
		\REQUIRE  ${\bf{H}}$ and ${{\bf{R}}_n}$. % input 的内容
		\STATE Initialize ${{\bf{F}}_i},{{\bf{V}}_i},{{\bf{W}}_i}$, set $i=0$.
		\REPEAT
		\STATE Using the FP algorithm to calculate ${{\bf{W}}_i}$ by (\ref{eq21}). 
		\STATE Solving for ${{\bf{F}}_i}$ and ${{\bf{V}}_i}$ via Algorithm~\ref{alg:PMO}.
		\STATE $i=i+1$.
		\UNTIL{a stopping criterion triggers.}
		\ENSURE ${\bf{F}},{\bf{V}},{\bf{W}}$ % output 的内容
	\end{algorithmic}
	%\STATE \textbf{Output:} ${\bf{F}},{\bf{V}},{\bf{W}}$
	%\label{alg1}
\end{algorithm}

We summarize the proposed PMO algorithm as Algorithm \ref{alg:PMO}. In this algorithm, $c$ is the percentage decrease in the acceptable value of ${g_2}$ in the backtracking line search, $\tau $ is the parameter used to regulate the change in the step size $\alpha $, and $\varepsilon $ is used to control the accuracy of the Riemannian gradient at convergence.
When the algorithm starts with $k = 0$, we first set the initial search direction ${{\bf{\Pi }}_{{{\bf{F}}_0}}} =  - gra{d_{{{\bf{F}}_0}}}{g_2}$ and ${{\bf{\Pi }}_{{{\bf{V}}_0}}} =  - gra{d_{{{\bf{V}}_0}}}{g_2}$,  and then compute the step size of this iteration by backtracking line search. If the Riemannian gradient reaches the target accuracy $\varepsilon $, the optimization algorithm stops, otherwise the above steps are repeated until the end condition is reached.

Up to now, we have proposed solutions for all optimized variables in problem (\ref{Za}). We now summarize the AO-PMO algorithm into Algorithm \ref{alg2}. 


\subsection{Complexity Analysis}
As we can see, the main computational complexity of FP-PMO lies in computing (\ref{eq21}) and the  Euclidean gradient G$ra{d_{{{\bf{F}}_k}}}{g_2}$ and $Gra{d_{{{\bf{V}}_k}}}{g_2}$. Let ${I_{in}}$ and ${I_{out}}$ be the numbers of iterations of Algorithm~\ref{alg:PMO} and Algorithm~\ref{alg2}, respectively, and assume $M = {N_{RF}}$.
The complexity of (\ref{eq21}) is ${\cal O}\left( {{M^4}} \right)$ and the complexity of computing the  Euclidean gradient is ${\cal O}\left( {{M^2}{N_r}{N_t}} \right)$.
 So the complexity of the algorithm can be expressed as:
2${\cal O}\left( {{I_{in}}{I_{out}}{M^2}{N_r}{N_t}} \right)+{\cal O}\left( {{I_{out}}{M^4}} \right)$. 

\section{Sum Rate Optimization for MU-MIMO Systems}\label{4}
It can be seen that (\ref{a}) is a matrix determinant summation problem
and the deep coupling of the optimization variables due to multiuser rate summation and the high nonconvexity of the optimization variables under the constant mode constraints make the problem very complex and difficult to solve. 
In order to solve it, we first prove that the original optimization problem  can be equivalently converted to a WMMSE
optimization problem.
Then we fix ${\bf{V}}{\rm{,}}{\bf{W}}_{RF}^{\left( i \right)}$  and design the two digital processing matrices ${\bf{W}}_D$ and ${\bf{U}}_i,\forall i$
according to the WMMSE criterion, and they have closed-form
solutions. Subsequently, we fix the optimized ${\bf{W}}_D$ and ${\bf{U}}_i,\forall i$  and
jointly optimize ${\bf{V}}{\rm{,}}{\bf{W}}_{RF}^{\left( i \right)},\forall i$ by using
the PMO algorithm.


\subsection{Problem Transformation}
Our idea to solve  (\ref{a}) is to first transform
it into a WMMSE optimization problem. To this end, we 
define the MSE matrix for the $i$-th UE as
\begin{align}
		{\bf{E}}_i^{} &= \mathbb{E}\left[ {\left( {{{\bf{x}}_i} - {{\bf{y}}_i}} \right){{\left( {{{\bf{x}}_i} - {{\bf{y}}_i}} \right)}^H}} \right]\nonumber\\
		&= {{\bf{I}}_{{N_s}}} - {{\bf{U}}_i}{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_i} - {\bf{W}}_i^H{{\bf{V}}^H}{\bf{H}}_i^H{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)^H}{\bf{U}}_i^H \nonumber\\
		& + \sum\limits_{j = 1}^M {{{\bf{U}}_i}{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_j}{\bf{W}}_j^H{{\bf{V}}^H}{\bf{{ H}}}_i^H{{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)}^H}{\bf{U}}_i^H} \nonumber\\
		& + \sigma _n^2{{\bf{U}}_i}{\bf{W}}_{RF}^{\left( i \right)}{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)^H}{\bf{U}}_i^H.\label{eq58}
\end{align}
Let ${{\bf{\Lambda }}_i}\succeq\bf{0}$ be the weight matrix of the $i$-th user. In Appendix B, we equivalently reformulate problem (\ref{a}) to the following weighted sum-MSE minimization problem as
\begin{subequations}
	\begin{align}
		%\label{eq11}
		\mathop {\max }\limits_{{{\bf{V}}{\rm{, }}{\bf{W}}_D{\rm{,}}{\bf{W}}_{RF}^{\left( i \right)}{\rm{,}}{{\bf{U}}_i},\forall i}} \quad &\sum\limits_{i{\rm{ = 1}}}^M {\left( {{\rm{Tr}}\left( {{{\bf{\Lambda }}_i}{{\bf{E}}_i}} \right) - \log \left| {{{\bf{\Lambda }}_i}} \right|} \right)}  \label{qa}  \\
		\mbox{s.t.}\quad\quad
		&{{\rm{  Tr}}({\bf{V}}{{\bf{W}}}_D {{\bf{W}}_D^H}{\bf{V}}_{}^H) \le P},   \label{qb} \\
		&{{\bf{V}}} \in {{\cal V}_M},{\bf{W}}_{RF}^{\left( i \right)} \in {{\cal W}_M}\label{qc}
	\end{align}
\end{subequations}
where the optimal solutions of ${\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}^{\left( i \right)}}{\rm{,}}{\bf{W}}_D{\rm{,  }}{\bf{U}}_i$ in problem (\ref{qa})  and in problem (\ref{a})  are the same.  So we only need to solve the equivalence MSE minimization problem (\ref{qa}).
\subsection{Digital Precoding Design for Transceivers}


Firstly, it is easily observed that the objective function of (\ref{qa}) is convex with respect to each of the optimization variables ${\bf{W}}_i{\rm{,  }}{\bf{U}}_i$, and ${\bf{\Lambda }}_i, \forall i$, respectively. Therefore, they could be sloved by the alternation optimization (AO) principle.

Fixing the other four variables, ${{\bf{\Lambda }}_i}$ can be solved by using the block coordinate descent method, we have:
\begin{equation}
\label{eq63}
{\bf{\Lambda }}_i^{opt} = {\bf{E}}_i^{ - 1}.
\end{equation}


Fixing all optimization variables except ${\bf{U}}_i$, the well-known MMSE receiver can be derived  as
\begin{equation}
\label{eq60}
{\bf{U}}_i^{mmse} = {\left( {{\bf{J}}_i^{ - 1}{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_i}} \right)^H},
 \end{equation}
 where ${\bf{J}}_i^{} = \sum\limits_{j = 1}^M {{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_j}{\bf{W}}_j^H{{\bf{V}}^H}{\bf{H}}_i^H{{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)}^H}}  + \sigma _n^2{\bf{W}}_{RF}^{\left( i \right)}{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)^H}$ is the covariance matrix of the total received signal of the $i$-th UE. 
 %[40] Q. Shi, M. Razaviyayn, Z. Q. Luo, and C. He, “An iteratively weighted MMSE approach to distributed sum-utility maximization for a MIMO interfering broadcast channel,” IEEE Trans. Signal Process., vol. 59, no. 9,pp. 4331–4340, Sep. 2011.


For ${\bf{W}}_i,\forall i$, fixing the other four variables, the objective function is a convex function with respect to ${\bf{W}}_i,\forall i$. The digital precoder can be derived by differentiating the objective function of (\ref{qa}) and set it to be zero.
The closed-form solution of $\left\{ {{{\bf{W}}_i}} \right\}_{i = 1}^M$  can be written as:
\begin{equation}
\begin{aligned}
\label{eq65}
&{\bf{W}}_i^{opt} = \\&{\left( {\sum\limits_{j = 1}^M {{{\bf{V}}^H}{\bf{H}}_{\rm{j}}^H{{\left( {{\bf{W}}_{RF}^{\left( j \right)}} \right)}^H}{\bf{U}}_j^H{{\bf{\Lambda }}_j}{\bf{U}}_j^{}{\bf{W}}_{RF}^{\left( j \right)}{{\bf{H}}_j}{\bf{V}}}  + {\mu _k}{{\bf{I}}_{N_t^{RF}}}} \right)^{ - 1}} \\
& \times {{\bf{V}}^H}{\bf{H}}_i^H{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)^H}{\bf{U}}_i^H{{\bf{\Lambda }}_i}, 
\end{aligned}
\end{equation}
where ${\mu _k}$ should be chosen to satisfy the power constraint, just as in  (\ref{eq21}).
So this optimal value can be easily solved using one-dimensional search techniques (e.g., bisection method). Finally, by substituting ${\mu _k}$ into (\ref{eq65}), we obtain solutions for all ${\bf{W}}_i,\forall i$.

