	\label{eq69}
	{f_1}({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}}) &= \sum\limits_{i = 1}^M {{\rm{Tr}}\left[ { - {{\bf{\Lambda }}_i}{{\bf{U}}_i}{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_i}} \right]} {\rm{ + }}\sum\limits_{i = 1}^M {{\rm{Tr}}\left[ {{{\bf{\Lambda }}_i}\left( {\sum\limits_{j = 1}^M {{{\bf{U}}_i}{\bf{W}}_{RF}^{\left( i \right)}{{\bf{H}}_i}{\bf{V}}{{\bf{W}}_j}{\bf{W}}_j^H{{\bf{V}}^H}{\bf{{ H}}}_i^H{{\left( {{\bf{W}}_{RF}^{\left( i \right)}} \right)}^H}{\bf{U}}_i^H} } \right)} \right]} \\
	&= - {\rm{Tr}}\left( {{\bf{\Lambda UW}}_{RF}^{}{\bf{HVW}}_D} \right) + {\rm{Tr}}\left( {{\bf{\Lambda UW}}_{RF}^{}{\bf{HVW}}_D{\bf{W}}_D^H{{\bf{V}}^H}{\bf{{ H}}}_{}^H{\bf{W}}_{RF}^H{{\bf{U}}^H}} \right).
	\end{aligned}
	\end{equation}
