\subsection{Optimization of RIMSA Phase Shifts for Transceivers}
The digital precoder ${\bf{W}}_D$ and combiner ${\bf{U}}_i, \forall i$ have unconstrained solutions and can be derived in closed form. However, optimizing RIMSA phase shifts ${\bf{V}}$ and ${{\bf{W}}_{RF}^{\left( i \right)}}$ for transceivers with unit-modulus constraints is challenging. As was the case under the MU-MISO system, we will use the PMO algorithm to optimize ${\bf{V}}$ and ${{\bf{W}}_{RF}^{\left( i \right)}}$. With fixed ${\bf{W}}_D$, ${\bf{U}}_i$ and ${\bf{\Lambda }}_i$, the objective function of (\ref{qa}) can be transformed to (\ref{eq68}) where the second summation  holds due to ${\bf{W}}_{RF}^i{\left( {{\bf{W}}_{RF}^i} \right)^H} = K, \forall k$.



\subsubsection{Problem Transformation}
%We design the following objective function ${f_1}({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}})$ as (\ref{eq69}). 
We  define a large matrix ${{\bf{W}}_{RF}} \in {\mathbb{C}^{MN_r^{RF} \times M{N_r}}}$ representing the RIMSA receive matrix for all UEs,  which is also a block diagonal matrix as
\begin{equation}
	\label{eqm12}
	{\bf{W}}_{RF}^{} = {\rm{blkdiag}}\left( {{\bf{W}}_{RF}^{\left( 1 \right)},{\bf{W}}_{RF}^{\left( 2 \right)} \cdots {\bf{W}}_{RF}^{\left(M \right)}} \right).
\end{equation}
%We can see that the matrix ${{\bf{W}}_{RF}}$ contains configuration information for the RIMSA of all UEs. 


Similarly, we define a large matrix ${\bf{U}} \in {\mathbb{C}^{^{MNs \times MN_r^{RF}}}}$ to include the digital processing matrices for all UEs. It can be represented as stacking each digital processing matrix ${{\bf{U}}_i}$  in a block diagonal manner as
\begin{equation}
	\label{eqm13}
	{\bf{U}} = {\rm{blkdiag}}({{\bf{U}}_1},{{\bf{U}}_2} \cdots {{\bf{U}}_M}).
\end{equation}
We also define ${\rm{ }}{\bf{\Lambda }} = {\rm{blkdiag}}({{\bf{\Lambda }}_1},{{\bf{\Lambda }}_2} \cdots {{\bf{\Lambda }}_M})$, and define ${\bf{H}} = {\left[ {{\bf{H}}_1^T,{\bf{H}}_2^T, \cdots {\bf{H}}_M^T} \right]^T} \in {\mathbb{C}^{M{N_r} \times {N_t}}}$ representing the combined channel from the BS to all users. 

After removing the terms in $f({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}})$ that are uncorrelated to ${\bf{V}}$ and ${{\bf{W}}_{RF}}$, we get objective function  ${f_1}({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}})$ in (\ref{eq69}). 
And the problem  can be transformed into:
\begin{equation}
	\begin{aligned}
		\label{eq67}
		\mathop {\min }\limits_{{\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}}}\quad  &f_1({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}})     \\
		\mbox{s.t.}\quad
		&{\bf{W}}_{RF}^{} = {\rm{blkdiag}}\left( {{\bf{W}}_{RF}^{\left( 1 \right)},{\bf{W}}_{RF}^{\left( 2 \right)} \cdots {\bf{W}}_{RF}^{\left(M \right)}} \right),\\
		&{{\bf{V}}} \in {{\cal V}_M},{\bf{W}}_{RF}^{\left( i \right)} \in {{\cal W}_M},
	\end{aligned}
\end{equation}
We can see that the summation term is eliminated from the function ${f_1}({\bf{V}}{\rm{,  }}{{\bf{W}}_{RF}})$, which means that we can jointly optimize ${\bf{V}}$ and ${{\bf{W}}_{RF}}$ simultaneously. 
%When the optimal large matrix ${{\bf{W}}_{RF}}$ is obtained, each user's ${{\bf{W}}_{RF}^{\left( i \right)}}$ is a part of the block diagonal matrix ${{\bf{W}}_{RF}}$, which can be assigned one by one.


\subsubsection{Adopting PMO Algorithm} 
In the previous section, we have highlighted the theory of the PMO algorithm as well as the optimization process, so in this section we will not go into details. We only list the expressions for the Riemannian gradient of ${f_1}$ for ${\bf{V}}$ and ${{\bf{W}}_{RF}}$ as follows:
\begin{align}
	Gra{d_{{{\bf{V}}}}}{f_1} &= {\bf{C}}^H \odot {{\bf{Q}}_1}, 	\label{meq72}\\
	Gra{d_{{{{\bf{W}}_{RF}}}}}{f_1} &= {\bf{D}}^H \odot {{\bf{Q}}_2}, 	\label{meq73}
\end{align}
where ${\bf{C}} = {\bf{W}}_D{{\bf{W}}_D^H}{\bf{V}}_{}^H{\bf{{ H}}}_{}^H{\bf{W}}_{RF}^H{{\bf{U}}^H}{\bf{\Lambda UW}}_{RF}^{}{\bf{H}} - {\bf{W}}_D{\bf{\Lambda UW}}_{RF}^{}{\bf{H}}$.
 ${\bf{D}} = {\bf{HVW}}_D{{\bf{W}}_D^H}{\bf{V}}_{}^H{\bf{{ H}}}_{}^H{\bf{W}}_{RF}^H{{\bf{U}}^H}{\bf{\Lambda U}} - {\bf{HVW}}_D{\bf{\Lambda U}}$.
And ${{\bf{Q}}_1} = {\rm{blkdiag}}\left({\bf{q}}_1^{\left( 1 \right)},{\bf{q}}_1^{\left( 2 \right)} \cdots {\bf{q}}_1^{\left( {{N_t^{RF}}} \right)}\right)$ is a block diagonal matrix and has the same matrix structure as ${\bf{V}}$, and  ${\bf{q}}_1^{\left( 1 \right)} = {\bf{q}}_1^{\left( 2 \right)} =  \cdots {\bf{q}}_1^{\left( {N_t^{RF}} \right)} = {{\bf{1}}_N}$. 
 ${{\bf{Q}}_2} = {\rm{blkdiag}}\left( {{{\left( {{\bf{q}}_2^{\left( 1 \right)}} \right)}^H},{{\left( {{\bf{q}}_2^{\left( 2 \right)}} \right)}^H} \cdots {{\left( {{\bf{q}}_2^{\left( {MN_r^{RF}} \right)}} \right)}^H}} \right)$ is a block diagonal matrix with $MN_r^{RF}$ rows and has the same matrix structure as ${{\bf{W}}_{RF}}$, and ${\bf{q}}_2^{\left( 1 \right)} = {\bf{q}}_2^{\left( 2 \right)} =  \cdots {\bf{q}}_2^{\left( {N_t^{RF}} \right)} = {{\bf{1}}_K}$.
The WMMSE-PMO algorithm is summarized as Algorithm \ref{alg3}.

\subsection{Complexity Analysis}
As we can see, the main computational complexity of WMMSE-PMO lies on computing (\ref{eq63}), (\ref{eq60}), (\ref{eq65}) and the Euclidean gradient $Gra{d_{{{\bf{V}}}}}{f_1}$ and $Gra{d_{{{{\bf{W}}_{RF}}}}}{f_1}$, which are 
${\cal O}\left( {MN_t^{RF}{N_s}{N_t}} \right)$,
${\cal O}\left( {MN_t^{RF}{N_r^{RF}}{N_t}} \right)$,
${\cal O}\left( {MN_t^{RF}{N_r}{N_t}} \right)$ and
${\cal O}\left( {MN_t^{RF}{N_r}{N_t}} \right)$, respectively.
 Let ${I_{o}}$ and ${I_{i}}$ be the numbers of outer and inner iterations of Algorithm~\ref{alg3}, and the complexity of the algorithm can be expressed as:
$2{\cal O}\left( {{I_i}{I_o}MN_t^{RF}{N_r}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_r}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_s}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_r^{RF}}{N_t}} \right)$. 

	For the MU-MISO scenario, the WMMSE-PMO algorithm proposed for the general MU-MIMO case remains applicable. However, the FP-PMO algorithm specifically designed for the MU-MISO case offers lower computational complexity compared to the WMMSE-PMO algorithm. The proof is provided as follows:
	As we can see, the complexity of FP-PMO can be expressed as:
	2${\cal O}\left( {{I_{in}}{I_{out}}{M^2}{N_r}{N_t}} \right)+{\cal O}\left( {{I_{out}}{M^4}} \right)$. 
	And the complexity of the WMMSE-PMO algorithm can be expressed as:
	$2{\cal O}\left( {{I_i}{I_o}MN_t^{RF}{N_r}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_r}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_s}{N_t}} \right)+{\cal O}\left( {{I_o}MN_t^{RF}{N_r^{RF}}{N_t}} \right)$, which is higher than that of FP-PMO algorithm. This is because the WMMSE algorithm introduces additional auxiliary variables ${\bf{\Lambda }}$, which lead to increased computational complexity. 

\begin{algorithm}[t]
	\caption{ WMMSE-PMO Algorithm for Multi-user MIMO Systems }\label{alg3}
	\renewcommand{\algorithmicrequire}{\textbf{Input:}}
	\renewcommand{\algorithmicensure}{\textbf{Output:}}
	\begin{algorithmic}[1]
		\REQUIRE  ${\bf{H}}$ , $\sigma _i^2$, for $i = 1,2, \cdots M$. % input 的内容
		\STATE Initialize ${{\bf{U}}_{\left[ 0 \right]}},{\bf{W}}_{RF\left[ 0 \right]},{{\bf{V}}_{\left[0 \right]}},{{\bf{W}}_{\left[0 \right]}},{{\bf{\Lambda }}_{\left[0 \right]}}$, set $k=0$.
		\REPEAT
		\STATE Update ${{\bf{U}}_{\left[k \right]}}$ according to (\ref{eq60}) and (\ref{eqm13}). 
		\STATE Update ${{\bf{\Lambda }}_{\left[ k \right]}}$ according to (\ref{eq63}).
		\STATE Update ${{\bf{W}}_{D\left[ k \right]}}$ according to (\ref{eq65}).
		\STATE Calculate ${\bf{W}}_{RF\left[ k \right]}$ and ${{\bf{V}}_{\left[ k \right]}}$ with Algorithm~\ref{alg:PMO};

		\STATE $k=k+1$.
		\UNTIL{the objective function of (\ref{qa}) converges.}
		\ENSURE ${\bf{U}},{\bf{W}}_{RF}^{},{\bf{V}},{\bf{W}},{\bf{\Lambda }}$ % output 的内容
	\end{algorithmic}
	%\STATE \textbf{Output:} ${\bf{F}},{\bf{V}},{\bf{W}}$
	%\label{alg1}
\end{algorithm}

