\title{\texttt{PGLib-CO2}: A Power Grid Library for \\ Computing and Optimizing Carbon Emissions}
\author{\IEEEauthorblockN{Young-ho Cho, Min-Seung Ko, and Hao Zhu}
\IEEEauthorblockA{Chandra Department of Electrical and Computer Engineering \\
