                    "emissions" => "CO2e")

# 3) Embed the fuel type and intensity factor
#    as formal attributes within the generator data
carbon_casefile(net, fuel_dict)

# 4) Solve carbon-neutral OPF and analyze results
result = run_opf(net, ACPPowerModel,
                Ipopt.Optimizer)

# 5) Analyze final dispatch and emissions
println(result["solution"]["objective"])
