% \begin{array}{ll}
% \dfrac{4a^2f^2 - 4a^2f + 2a^2 - 8abf + 4ab + 2b^2}{4} & 0 \leq f \leq \dfrac{a+b}{2a} \\[10pt]
% \dfrac{a^2 + 2ab + b^2 - 4fab}{4} & \dfrac{a+b}{2a} \leq f \leq 1
% \end{array}
% \right.
% $$
% \end{proposition}

\begin{proof} 
We assume that each $\mathbf{M}_{\text{spatial}}(t,n)$ is an independent random variable $M_{tn}$. Given that $b \leq M_{tn} \leq a$, it follows that $b \leq \mathbb{E}[M_{tn}] \leq a$. Furthermore, when $X_{tnc} \neq 0$, we have:
\begin{equation}
(X_{tnc}M_{tn}-b)(a-X_{tnc}M_{tn}) \geq 0,
\end{equation}
which expands to:
\begin{equation}
-(X_{tnc}M_{tn})^2 + (a + b)(X_{tnc}M_{tn}) - ab \geq 0.
\end{equation}
Taking the expectation on both sides yields:
\begin{equation}
\mathbb{E}\left[(X_{tnc}M_{tn})^2\right] \leq (a + b) \mathbb{E}\left[X_{tnc}M_{tn}\right] - ab.
\end{equation}

Using the Law of Total Variance, we can decompose the variance of $Y_{tnc}$ as:
\begin{equation}
\text{Var}(Y_{tnc}) = \mathbb{E}[\text{Var}(Y_{tnc} | X_{tnc})] + \text{Var}(\mathbb{E}[Y_{tnc} | X_{tnc}]).
\end{equation}

For the first term, the expectation of the conditional variance can be expressed as:
\begin{equation}
\mathbb{E}[\text{Var}(Y_{tnc} | X_{tnc})] = f \cdot \text{Var}(Y_{tnc} | X_{tnc} = 1) + (1-f) \cdot \text{Var}(Y_{tnc} | X_{tnc} = 0).
\end{equation}

For the second term, the variance of the conditional expectation can be expanded as:
\begin{equation}
\text{Var}(\mathbb{E}[Y_{tnc} | X_{tnc}]) = \mathbb{E}[\mathbb{E}[Y_{tnc} | X_{tnc}]^2] - \mathbb{E}[\mathbb{E}[Y_{tnc} | X_{tnc}]]^2.
\end{equation}
By substituting the conditional probabilities, we have:
\begin{equation}
\label{cp}
\text{Var}(\mathbb{E}[Y_{tnc} | X_{tnc}]) = f \cdot \mathbb{E}[Y_{tnc} | X_{tnc} = 1]^2 - f^2 \cdot \mathbb{E}[Y_{tnc} | X_{tnc} = 1]^2.
\end{equation}

Combining the two terms, the total variance becomes:
\begin{equation}
\text{Var}(Y_{tnc}) = f \cdot \text{Var}(Y_{tnc} | X_{tnc} = 1) + (f - f^2) \cdot \mathbb{E}[Y_{tnc} | X_{tnc} = 1]^2.
\end{equation}

From Equation \ref{cp}, we define $\mathbb{E}[Y_{tnc} | X_{tnc} = 1] = \mu$. Substituting this definition, the variance can be rewritten as:
\begin{align}
\text{Var}(Y_{tnc}) &= f \cdot (\mathbb{E}[Y_{tnc}^2 | X_{tnc} = 1] - \mu^2) + (f - f^2) \cdot \mu^2.
\end{align}

Using the constraints $b \leq M_{tn} \leq a$, we have the following bound for $\text{Var}(Y_{tnc} | X_{tnc} = 1)$:
\begin{equation}
\text{Var}(Y_{tnc} | X_{tnc} = 1) \leq (a + b)\mu - ab - \mu^2.
\end{equation}

By substituting this into the total variance expression, the upper bound of $\text{Var}(Y_{tnc})$ becomes:
\begin{align}
\text{Var}(Y_{tnc}) &\leq f \cdot ((a + b)\mu - ab - \mu^2) + (f - f^2) \cdot \mu^2 \notag \\
&\leq -f^2 \cdot \left(\mu - \frac{a + b}{2f}\right)^2 + \frac{a^2 + 2ab + b^2 - 4fab}{4}.
\end{align}

Next, we will prove that this upper bound can be achieved with equality under specific conditions.

\textbf{Case 1:} When $\frac{a+b}{2a} \leq f \leq 1$, we assume that:
\begin{equation}
\mathbb{E}[Y_{tnc}|X_{tnc}=1] = \frac{a+b}{2f}, \quad M_{tn} = a \ \text{or} \ b.
\end{equation}

Here, $M_{tn}$ is a binary random variable, taking the value $a$ with probability $p$ and the value $b$ with probability $1-p$. Using this assumption, we can express the conditional expectation $\mathbb{E}[Y_{tnc}|X_{tnc}=1]$ as:
\begin{equation}
\mathbb{E}[Y_{tnc}|X_{tnc}=1] = pa + (1-p)b.
\end{equation}
Substituting $\mathbb{E}[Y_{tnc}|X_{tnc}=1] = \frac{a+b}{2f}$ into the above equation, we solve for $p$:
\begin{equation}
pa + (1-p)b = \frac{a+b}{2f} \Rightarrow p = \frac{a+b-2bf}{2f(a-b)}.
\end{equation}

The variance of $Y_{tnc}$ under this distribution is maximized when $M_{tn}$ follows this binary distribution. Substituting $p$ into the variance formula, the maximum variance is given by:
\begin{equation}
\max(\text{Var}(Y_{tnc})) = \frac{a^2 + 2ab + b^2 - 4fab}{4}.
\end{equation}

\textbf{Case 2:} When $0 \leq f \leq \frac{a+b}{2a}$, the upper bound is achieved when $M_{tn} = a$. In this scenario, $M_{tn}$ is deterministic, and therefore:
\begin{equation}
Y_{tnc} = X_{tnc}M_{tn} = X_{tnc}a, \quad \mathbb{E}[Y_{tnc}|X_{tnc}=1] = a.
\end{equation}
Substituting this into the variance formula, the maximum variance simplifies to:
\begin{equation}
\max(\text{Var}(Y_{tnc})) = a^2(f^2-f+1/2) + ab(1-2f) + \, b^2/2.
\end{equation}

The proof is now complete. 
\end{proof} 

