We observe that both SSA and QKTA exhibit significantly larger variance compared to our proposed attention mechanism. Their variances are expressed as follows:

\textbf{Variance of QKTA:}
\begin{equation}
\text{Var}(\mathrm{QKTA}) = d f_{Q}(1 - f_{Q}),
\end{equation}
where $d$ is the feature dimension, and $f_{Q}$ represents the firing rate of the query.

\textbf{Variance of SSA:}
\begin{align}
\text{Var}(\text{SSA}) = Nd \Big(& f_{Q} f_{K} f_{V} (1 - f_{Q})(1 - f_{K})(1 - f_{V}) \notag \\
&+ f_{Q} f_{K} f_{V}^2 (1 - f_{Q})(1 - f_{K}) \notag \\
&+ f_{Q} f_{K}^2 f_{V} (1 - f_{Q})(1 - f_{V}) \notag \\
&+ f_{Q}^2 f_{K} f_{V} (1 - f_{K})(1 - f_{V}) \notag \\
&+ f_{Q} f_{K}^2 f_{V}^2 (1 - f_{Q}) \notag \\
&+ f_{Q}^2 f_{K} f_{V}^2 (1 - f_{K}) \notag \\
&+ f_{Q}^2 f_{K}^2 f_{V} (1 - f_{V}) \Big),
\end{align}
where $N$ is the number of spatial locations, $d$ is the feature dimension, and $f_{Q}, f_{K}, f_{V}$ are the firing rates of the query, key, and value.

\textbf{Comparison with Our Attention Mechanism:} The variance of QKTA scales linearly with $d$. By contrast, the variance of SSA grows with both $N$ and $d$, resulting in significantly larger values compared to QKTA. Our proposed attention mechanism is particularly effective in scenarios with large spatial ($N$) and feature ($d$) dimensions. The strict upper bound on output variance ensures numerical stability, preventing vanishing during training. Additionally, this upper bound eliminates the need for traditional scaling operations (e.g., scaling factors in QK products), simplifying computations, reducing complexity, and enhancing energy efficiency.

\subsection{The mathematical properties of hyperparameters}
\label{hyper}
Next, we will analyze the expectation and variance of the PM and propose an appropriate selection of hyperparameters to ensure output stability.

\begin{lemma}
\label{lem:B.2}
if the set $\{c \in  \mathbb{N}:w_c=0\}$ is finite and  $\exists \ m,M > 0$, $\forall \ c \in \mathbb{N}$, $m \leq |w_c| \leq M$, then:
\begin{equation}
    w_c' = \lim\limits_{C \to \infty} \frac{w_c}{\sqrt{\sum_{c=1}^C w_c^2}} = 0
\end{equation}
\end{lemma}
% \begin{proof} 
% We assume that there are $k$ terms in the sequence $w_c$ that are 0.
% According to the Cauchy convergence criterion, for every $\epsilon > 0 $, we only need:
% $$C \geq \left\lceil \frac{M^2}{m^2\epsilon^2}+k \right\rceil+1$$
% \begin{equation}|w_c' - 0| = \frac{|w_c'|}{\sqrt{\sum_{c=1}^C w_c^2}} \leq \frac{M}{m\sqrt{C-k}} <   \frac{M}{m \sqrt{\frac{M^2}{m^2\epsilon^2}}}  =  \epsilon\end{equation}
% % $$\frac{w_c}{\sqrt{\sum_{c=1}^C w_c^2}} \leq \frac{M}{m \sqrt{N-K}}$$
% The proof is complete.
% \end{proof}

\begin{proof}
We begin by defining the normalized weight:
\begin{equation}
    w_c' = \frac{w_c}{\sqrt{\sum_{c=1}^C w_c^2}}.
\end{equation}

By assumption, there are $k$ terms where $w_c = 0$, and for the remaining $C - k$ terms, the weights satisfy:
\begin{equation}
    m^2 \leq w_c^2 \leq M^2 \quad \text{for all } c.
\end{equation}
Thus, the sum of squares of the weights is bounded as follows:
\begin{equation}
    (C - k)m^2 \leq \sum_{c=1}^C w_c^2 \leq (C - k)M^2.
\end{equation}
Taking the square root, we find that the denominator grows as:
\begin{equation}
    \sqrt{\sum_{c=1}^C w_c^2} \geq \sqrt{(C - k)m^2} \sim O(\sqrt{C}).
\end{equation}

Using the bound $|w_c| \leq M$, the normalized weight $w_c'$ satisfies:
\begin{equation}
    |w_c'| = \frac{|w_c|}{\sqrt{\sum_{c=1}^C w_c^2}} \leq \frac{M}{\sqrt{\sum_{c=1}^C w_c^2}} \leq \frac{M}{\sqrt{(C - k)m^2}}.
\end{equation}

To ensure $|w_c'| < \epsilon$ for a given $\epsilon > 0$, it suffices to require:
\begin{equation}
    \frac{M}{\sqrt{(C - k)m^2}} < \epsilon.
\end{equation}
Rearranging, this condition can be rewritten as:
\begin{equation}
    C \geq \frac{M^2}{m^2 \epsilon^2} + k.
\end{equation}

As $C \to \infty$, the condition $C \geq \frac{M^2}{m^2 \epsilon^2} + k$ is always satisfied. Thus, for any $\epsilon > 0$, we have $|w_c'| < \epsilon$, which implies:
\begin{equation}
    \lim_{C \to \infty} w_c' = 0.
\end{equation}
The proof is complete.
\end{proof}

\begin{lemma}
