\begin{equation}
    M_{tn} = \sum_{c=1}^C x_{tnc} w_c'.
\end{equation}
where $x \in X$, $x \sim \text{Bernoulli}(f_r)$, $f_r$ represents the firing rate (the probability of $x_{tnc} = 1$).
\end{lemma}

