\begin{proof}
To prove this lemma, we use the characteristic function method. The characteristic function of a Bernoulli random variable $x_{tnc}$ is given by:
\begin{equation}
    \Phi_{x_{tnc}}(t) = \mathbb{E}\left[e^{itx_{tnc}}\right] = f_r e^{it} + (1 - f_r).
\end{equation}

For the weighted variable $w_c' x_{tnc}$, its characteristic function is:
\begin{equation}
    \Phi_{w_c' x_{tnc}}(t) = \mathbb{E}\left[e^{it w_c' x_{tnc}}\right] = f_r e^{it w_c'} + (1 - f_r).
\end{equation}

Since the features across channels are independent, the characteristic function of $M_{tn}$ is:
\begin{equation}
    \Phi_{M_{tn}}(t) = \prod_{c=1}^C \Phi_{w_c' x_{tnc}}(t).
\end{equation}
Substituting the expression for $\Phi_{w_c' x_{tnc}}(t)$:
\begin{equation}
    \label{cfmtn}
    \Phi_{M_{tn}}(t) = \prod_{c=1}^C \left(f_r e^{it w_c'} + (1 - f_r)\right).
\end{equation}

\begin{align}
    f_r e^{it w_c'} + (1 - f_r) 
    & =  f_r \left(1 + it w_c' - \frac{1}{2} t^2 w_c'^2+ o(w_c'^2)\right) + (1 - f_r) \notag \\
    &\approx 1 + f_r (it w_c' - \frac{1}{2} t^2 w_c'^2).
\end{align}

Thus, the characteristic function becomes:
\begin{equation}
    \Phi_{M_{tn}}(t) \approx \prod_{c=1}^C \left(1 + f_r (it w_c' - \frac{1}{2} t^2 w_c'^2)\right).
\end{equation}

Taking the logarithm to simplify the product into a sum:
\begin{align}
    \ln \Phi_{M_{tn}}(t) &= \sum_{c=1}^C \ln \left(1 + f_r (it w_c' - \frac{1}{2} t^2 w_c'^2)\right) \notag \\
    &= \sum_{c=1}^C f_rit w_c' - \frac{1}{2} t^2 w_c'^2 f_r+ \frac{1}{2}t^2w_c'^2f_r^2 + O(w_c'^2),
\end{align}
where we used $\ln(1 + x) =  x-\frac{1}{2}x^2 + O(x^2)$ for small $x$.

Separating terms, we get:
\begin{align}
    \ln \Phi_{M_{tn}}(t) &\approx it \sum_{c=1}^C w_c' f_r - \frac{1}{2} t^2 \sum_{c=1}^C w_c'^2 f_r (1 - f_r).
\end{align}

Exponentiating the logarithm gives:
\begin{equation}
    \Phi_{M_{tn}}(t) = \exp\left(it \sum_{c=1}^C w_c' f_r - \frac{1}{2} t^2 \sum_{c=1}^C w_c'^2 f_r (1 - f_r)\right).
\end{equation}

This is the characteristic function of a normal distribution with:
\begin{align}
    \text{Mean: } & \quad \mu = \sum_{c=1}^C w_c' f_r, \\
    \text{Variance: } & \quad \sigma^2 = \sum_{c=1}^C w_c'^2 f_r (1 - f_r).
\end{align}

Since the characteristic function corresponds to a normal distribution, we conclude:
\begin{equation}
    M_{tn} \sim \mathcal{N}\left(\sum_{c=1}^C w_c' f_r, \sum_{c=1}^C w_c'^2 f_r (1 - f_r)\right).
\end{equation}
The proof is complete.
\end{proof}


\begin{lemma}
\label{lem:B.4}
The distributions of $X_{tnc}$ and $M_{tn}$ can be considered independent when the number of channels $C$ is large. Specifically, for all $t_1, t_2 \in \mathbb{R}$, we have:
\begin{equation}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) = \phi_{M_{tn}}(t_1) \cdot \phi_{X_{tnc}}(t_2), \quad C \to \infty,
\end{equation}
where $\phi_X(t)$ represents the characteristic function of $X$.
\end{lemma}

