\begin{proof}
The joint characteristic function of $M_{tn}$ and $X_{tnc}$ is given by:
\begin{align}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) &= \mathbb{E}\left[e^{\left(it_1 M_{tn} + it_2 X_{tnc}\right)}\right] \notag \\
    &= \mathbb{E}\left[e^{\left(it_1 \sum_{c} w_c' X_{tnc} + it_2 X_{tnc}\right)}\right].
\end{align}

Separating $X_{tnc}$ and the sum $\sum_{i \neq c} w_i' X_{tni}$, we rewrite:
\begin{align}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) &= \mathbb{E}\left[e^{\left(it_1 \sum_{i \neq c} w_i' X_{tni} + i X_{tnc}(t_2 + t_1 w_c')\right)}\right] \notag \\
    &= \mathbb{E}\left[e^{\left(it_1 \sum_{i \neq c} w_i' X_{tni}\right)}\right] \cdot \mathbb{E}\left[e^{\left(i X_{tnc} (t_2 + t_1 w_c')\right)}\right].
\end{align}

Using the independence of $X_{tni}$ across channels:
\begin{align}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) &= \prod_{i \neq c} \mathbb{E}\left[e^{\left(it_1 w_i' X_{tni}\right)}\right] \cdot \mathbb{E}\left[e^{\left(i X_{tnc} (t_2 + t_1 w_c')\right)}\right].
\end{align}

Substituting the characteristic function of Bernoulli random variables $X_{tnc} \sim \text{Bernoulli}(f)$:
\begin{align}
    \label{cfxtnc}
    \mathbb{E}\left[e^{it X_{tnc}}\right)] &= (1 - f) + f e^{it}.
\end{align}
Thus:
\begin{align}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) &= \prod_{i \neq c} \left[(1 - f) + f e^{it_1 w_i'}\right] \cdot \left[(1 - f) + f e^{i(t_2 + t_1 w_c')}\right].
\end{align}

Using Lemma \ref{lem:B.3}, for small $w_{c}'$, we apply the Taylor expansion to approximate each term:
\begin{align}
    (1 - f) + f e^{it_1 w_i'} &\approx 1 + f (it_1 w_i'), \\
    (1 - f) + f e^{i(t_2 + t_1 w_c')} &\approx (1 - f) + f e^{it_2}.
\end{align}

Substituting back:
\begin{align}
    \phi_{M_{tn}, X_{tnc}}(t_1, t_2) &\approx \prod_{i \neq c} \left(1 + f it_1 w_i'\right) \cdot \left[(1 - f) + f e^{it_2}\right].
\end{align}

Using Equation \ref{cfmtn}, Equation \ref{cfxtnc} and Taylor expansion, the product of the characteristic functions for the two distributions is:
\begin{align}
\phi_{X_{tnc}}(t_2)\phi_{M_{tn}}(t_1) 
  &= (1-f + fe^{it_{2}})\prod_{i=1}^{C}(1-f+fe^{it_{1}w_{i}'}) \notag \\
  &= (1-f + fe^{it_{2}})\prod_{i=1}^{C}(1+fit_{1}w_{i}') \notag \\
  &= (1-f + fe^{it_{2}})(1+fit_{1}w_{c}')\prod_{i\neq c}(1+fit_{1}w_{i}') \notag \\
  &= (1-f + fe^{it_{2}})\prod_{i\neq c}(1+fit_{1}w_{i}') \notag \\
  &= \phi_{M_{tn},X_{tnc}}(t_{1},t_{2})  % 只这行编号
\end{align}
Thus, the joint characteristic function factorizes into the product of the marginal characteristic functions, which demonstrates that $M_{tn}$ and $X_{tnc}$ are asymptotically independent as $C \to \infty$.
\end{proof}

\begin{proposition}
If \( b \approx 0 \), \( a \geq 1 \), and the firing rate \( f \) is relatively small value, the PM output \( Y_{tnc} \) satisfies:
\begin{align}
\mathbb{E}(Y_{tnc}) &\approx \sqrt{\frac{f(1-f)}{2\pi}} \, \mathbb{E}(X_{tnc}) \label{eq:expectation} \\
\text{Var}(Y_{tnc}) &\approx \frac{f(\pi - f)}{2\pi} \, \text{Var}(X_{tnc}) \label{eq:variance}
\end{align}
\end{proposition}

\begin{proof}
For convenience, we denote:
\begin{align}
\mu = \sum_{c=1}^C w_{c}' f, \quad \sigma^2 = \sum_{c=1}^{C} w_{c}'^2 f (1 - f) = f(1-f), \quad M'_{tn} = \text{clamp}(M_{tn}, b, a).
\end{align}

According to Lemma \ref{lem:B.3}, the input distribution satisfies:
\begin{align}
M_{tn} \sim \mathcal{N}(\mu, \sigma^2).
\end{align}
The expectation of the clamped variable $M'_{tnc}$ is:
\begin{align}
\mathbb{E}(M'_{tn}) &= \int_{-\infty}^{\infty} x f(x) dx \notag \\
&= \frac{1}{\sqrt{2\pi\sigma^2}} \int_{0}^{a} x \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx 
+ \frac{a}{\sqrt{2\pi\sigma^2}} \int_{a}^{\infty} \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx. 
\end{align}

For the first term, let $t = (x - \mu)^2$, if $\mu \approx 0$, then:
% \begin{align}
% \frac{1}{\sqrt{2\pi\sigma^2}}\int_{0}^{a} x \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx 
% &= \frac{1}{2\sqrt{ 2\pi\sigma^2}}\int_{\mu^2}^{(a-\mu)^2} \exp\left(-\frac{t}{2\sigma^2}\right) dt 
% + \frac{\mu}{\sqrt{2\pi\sigma^2}} \int_{0}^{a} \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dt\\
% &= \frac{-\sigma}{\sqrt{2\pi\sigma}}\left[ \exp(-\frac{t}{2\sigma^2})\right]_{\mu^2}^{(a-\mu)^2} + \mu \left(\Phi(\frac{a-\mu}{\sigma}) - \Phi(\frac{-\mu}{\sigma})\right) \\ 
% &\approx \frac{\sigma}{\sqrt{2\pi}} \left(1- \exp(\frac{-a^2}{2\sigma^2})\right)
% \end{align}
\begin{align}
&\frac{1}{\sqrt{2\pi\sigma^2}}\int_{0}^{a} x \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx \notag\\
&= \frac{1}{2\sqrt{2\pi\sigma^2}} \int_{\mu^2}^{(a-\mu)^2} \exp\left(-\frac{t}{2\sigma^2}\right) dt 
+ \frac{\mu}{\sqrt{2\pi\sigma^2}} \int_{0}^{a} \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx \notag\\
&= \frac{-\sigma}{\sqrt{2\pi\sigma}} \left[ \exp\left(-\frac{t}{2\sigma^2}\right)\right]_{\mu^2}^{(a-\mu)^2} 
+ \mu \left(\Phi\left(\frac{a-\mu}{\sigma}\right) - \Phi\left(\frac{-\mu}{\sigma}\right)\right) \notag\\
&\approx \frac{\sigma}{\sqrt{2\pi}} \left(1 - \exp\left(-\frac{a^2}{2\sigma^2}\right)\right).
\end{align}
where $ \Phi(x) $ is the CDF of the standard normal distribution. The second term in the expectation is straightforward:
\begin{align}
\frac{a}{\sqrt{2\pi\sigma^2}}\int_{a}^{\infty} \exp\left(-\frac{(x-\mu)^2}{2\sigma^2}\right) dx 
&= \frac{a}{\sqrt{2\pi\sigma^2}}\int_{a - \mu}^{\infty} \exp\left(-\frac{t^2}{2\sigma^2}\right) dt,
\end{align}
Using the cumulative distribution function (CDF) again:
\begin{align}
\frac{a}{\sqrt{2\pi\sigma^2}}\int_{a - \mu}^{\infty} \exp\left(-\frac{t^2}{2\sigma^2}\right) dt 
&= a \left(1 - \Phi\left(\frac{a - \mu}{\sigma}\right)\right) \notag\\
&\approx a \left(1 - \Phi\left(\frac{a}{\sigma}\right)\right)
\end{align}
The $\Phi(\frac{a}{\sigma})$ and $\exp(-\frac{a^2}{2\sigma^2})$ function decay rapidly as $\sigma$ decreases. Now, combining the results from the two integrals, we have:
\begin{align}
\mathbb{E}(M'_{tn}) &= \frac{\sigma}{\sqrt{2\pi}} - \frac{\sigma}{\sqrt{2\pi}} \exp\left(-\frac{a^2}{2\sigma^2}\right) 
+ a \left(1 - \Phi\left(\frac{a - \mu}{\sigma}\right)\right) \notag\\
&\approx \frac{\sigma}{\sqrt{2\pi}}
\end{align}

Based on \ref{lem:B.4}, we calculate the expectation and variance of $M'^2_{tn}$:
\begin{align}
\mathbb{E}(M'^2_{tn}) &= \int_{-\infty}^\infty x^2 f(x) dx \notag \\
&= \frac{1}{\sqrt{2\pi\sigma^2}} \int_{0}^{a} x^2 \exp\left(-\frac{x^2}{2\sigma^2}\right) dx 
+ a^2 \cdot \int_{a}^\infty f(x) dx. \label{eq:expectation_m2}
\end{align}

We calculate the first term using integration by parts. Let:
\begin{align}
u = x, \quad dv = x \exp\left(-\frac{x^2}{2\sigma^2}\right) dx, \quad du = dx, \quad v = -\sigma^2 \exp\left(-\frac{x^2}{2\sigma^2}\right).
\end{align}
Then:
\begin{align}
&\frac{1}{\sqrt{2\pi\sigma^2}}\int_{0}^{a} x^2 \exp\left(-\frac{x^2}{2\sigma^2}\right) dx \notag \\
&= \frac{1}{\sqrt{2\pi\sigma^2}} 
\left( 
\left[ -\sigma^2 x \exp\left(-\frac{x^2}{2\sigma^2}\right) \right]_{0}^{a} 
+ \sigma^2 \int_{0}^{a} \exp\left(-\frac{x^2}{2\sigma^2}\right) dx \right)
\notag \\
&= \frac{1}{\sqrt{2\pi\sigma^2}}\left( -\sigma^2 a \exp\left(-\frac{a^2}{2\sigma^2}\right) + \sigma^2 \int_{0}^{a} \exp\left(-\frac{x^2}{2\sigma^2}\right) dx \right).\label{eq:first_term}
\end{align}

The remaining integral is a standard normal distribution integral:
\begin{align}
\frac{\sigma^2}{\sqrt{2\pi\sigma^2}}\int_{0}^{a} \exp\left(-\frac{x^2}{2\sigma^2}\right) dx =  \sigma^2 \left( \Phi\left(\frac{a}{\sigma}\right) - \frac{1}{2} \right), \label{eq:normal_cdf}
\end{align}
where $ \Phi(x) $ is the CDF of the standard normal distribution.

Substituting \eqref{eq:normal_cdf} into \eqref{eq:first_term}:
\begin{align}
\frac{1}{\sqrt{2\pi\sigma^2}}\int_{0}^{a} x^2 \exp\left(-\frac{x^2}{2\sigma^2}\right) dx 
 = \frac{-a\sigma}{\sqrt{2\pi}}  \exp\left(-\frac{a^2}{2\sigma^2}\right) + \sigma^2 \left( \Phi\left(\frac{a}{\sigma}\right) - \frac{1}{2} \right). \label{eq:final_first_term}
\end{align}

The second term is the tail of the normal distribution:
\begin{align}
\int_{a}^\infty f(x) dx =  \Phi\left(-\frac{a}{\sigma}\right),
\end{align}
we have:
\begin{align}
a^2 \cdot \int_{a}^\infty f(x) dx =  a^2 \Phi\left(-\frac{a}{\sigma}\right). \label{eq:tail_term}
\end{align}

Combining \eqref{eq:final_first_term} and \eqref{eq:tail_term} into \eqref{eq:expectation_m2}, we get:
\begin{align}
\mathbb{E}(M'^2_{tn}) 
&= \frac{-a\sigma}{\sqrt{2\pi}}  \exp\left(-\frac{a^2}{2\sigma^2}\right) 
+ \sigma^2 \left( \Phi\left(\frac{a}{\sigma}\right) - \frac{1}{2} \right)
+ a^2 \Phi\left(-\frac{a}{\sigma}\right) \notag\\ 
&\approx \frac{\sigma^2}{2}. \label{eq:final_expectation_m2}
\end{align}
Since $ \Phi\left(-\frac{a}{\sigma}\right) $ is exponentially small for moderate $ a $, the term $ a^2 \Phi\left(-\frac{a}{\sigma}\right) $ is negligible compared to leading terms and is often omitted for simplicity.

Using $\text{Var}(M'_{tn}) = \mathbb{E}(M'^2_{tn}) - \mathbb{E}(M'_{tn})^2$, we calculate:
\begin{align}
\text{Var}(M'_{tn}) 
&\approx \frac{\sigma^2}{2} 
- \left[\frac{\sigma}{\sqrt{2\pi}} \left(1 - \exp\left(-\frac{a^2}{2\sigma^2}\right)\right)\right]^2 \notag \\
&\approx \frac{\pi - 1}{2\pi} \sigma^2 \notag \\
&= \frac{\pi - 1}{2\pi} f(1-f).
\end{align}

Given that $Y_{tnc} = M'_{tnc} \cdot X_{tnc}$, and based on Lemma \ref{lem:B.4} that the distributions of $X_{tnc}$and $M'_{tn}$can be considered independent, the expectation of $Y_{tnc}$ is:
\begin{align}
\mathbb{E}(Y_{tnc}) &= \mathbb{E}(M'_{tn}) \cdot \mathbb{E}(X_{tnc}) \notag \\
&\approx \sqrt{\frac{f(1-f)}{2\pi}} \mathbb{E}(X_{tnc}).
\end{align}

The variance of $Y_{tnc}$ is computed as:
\begin{align}
\text{Var}(Y_{tnc}) &= \text{Var}(M'_{tn}) \cdot \text{Var}(X_{tnc}) 
+ \text{Var}(M'_{tn}) \cdot \mathbb{E}(X_{tnc})^2 
+ \text{Var}(X_{tnc}) \cdot \mathbb{E}[M'_{tn}]^2 \notag \\
&= \frac{f(\pi-f)}{2\pi} f (1 - f) \notag \\
&\approx \frac{f(\pi - f)}{2\pi} \text{Var}(X_{tnc}).
\end{align}

Thus, the proposition is proven:
\begin{align}
\mathbb{E}(Y_{tnc}) \approx \sqrt{\frac{f(1-f)}{2\pi}} \mathbb{E}(X_{tnc}), \quad
\text{Var}(Y_{tnc}) \approx \frac{f(\pi-f)}{2\pi} \text{Var}(X_{tnc}).
\end{align}
\end{proof}
In practice, we recommend setting the hyperparameters as follows: $ b = 0 $ and $ a \in [1, 2] $. Setting $ b = 0 $ allows the processing module to completely eliminate certain features in the spatial domain. Furthermore, selecting \( a \in [1, 2] \) enables the processing module to selectively enhance specific spatial features. This also ensures that both the mean and variance do not become too large or too small, maintaining the numerical stability.



