\subsection{Gradient Analysis}
\label{Gradient}
This section on the derivation of the traditional SNN network is mainly referenced from \cite{meng2022training, wu2019direct, ding2025rethinking}.
First, we derive the temporal gradient of the traditional SNN network, where the temporal gradient is primarily backpropagated through the membrane potential. Taking the vanilla LIF neuron as an example, we use the following form to analyze the gradient problem:
\begin{align}
\mathbf{H}^{l}(t+1)=\left(1-\frac{1}{\tau}\right)\left(\mathbf{H}^{l}(t)-\vartheta \mathbf{S}^{l}(t)\right)+\mathbf{W}^{l} \mathbf{S}^{l-1}(t+1), 
\end{align}
The derivative of the loss with respect to the weights $W_l$ is: 
\begin{align}
\nabla_{\mathbf{W}^{l}} \mathcal{L}=\sum_{t=0}^{T-1}{\frac{\partial \mathcal{L}}{\partial \mathbf{H}^{l}(t)}}^{\top} \mathbf{S}^{l-1}[t]^{\top}, l=L, L-1, \cdots, 1, 
\end{align}
The gradient expression can be written as:
\begin{align}
\frac{\partial \mathcal{L}}{\partial \mathbf{H}^{l}(t)} = &\underbrace{\frac{\partial \mathcal{L}}{\partial \mathbf{H}^{l+1}(t)} \frac{\partial \mathbf{H}^{l+1}(t)}{\partial \mathbf{S}^{l}(t)} \frac{\partial \mathbf{S}^{l}(t)}{\partial \mathbf{H}^{l}(t)}}_{Spatial\hspace{0.5em}Gradient}+ \notag \\ &\underbrace{\sum_{t^{\prime}=t+1}^{T-1} \frac{\partial \mathcal{L}}{\partial \mathbf{H}^{l+1}\left(t^{\prime}\right)} \frac{\partial \mathbf{H}^{l+1}\left(t^{\prime}\right)}{\partial \mathbf{S}^{l}\left(t^{\prime}\right)} \frac{\partial \mathbf{S}^{l}\left(t^{\prime}\right)}{\partial \mathbf{H}^{l}\left(t^{\prime}\right)} \prod_{t^{\prime \prime}=1}^{t^{\prime}-t} \epsilon^{L}\left(t^{\prime}-t^{\prime \prime}\right)}_{Temporal\hspace{0.5em}Gradient}, l<L,
\end{align}
\begin{align}
    \frac{\partial \mathcal{L}}{\partial \mathbf{H}^{l}(t)}
=\underbrace{\frac{\partial \mathcal{L}}{\partial \mathbf{S}^{l}(t)} \frac{\partial \mathbf{S}^{l}(t)}{\partial \mathbf{H}^{l}(t)}}_{Spatial \hspace{0.5em}Gradient }
+\underbrace{\sum_{t^{\prime}=t+1}^{T-1} \frac{\partial \mathcal{L}}{\partial \mathbf{S}^{l}\left(t^{\prime}\right)} \frac{\partial \mathbf{S}^{l}\left(t^{\prime}\right)}{\partial \mathbf{H}^{l}\left(t^{\prime}\right)} \prod_{t^{\prime \prime}=1}^{t^{\prime}-t} \epsilon^{L}\left(t^{\prime}-t^{\prime \prime}\right)}_{Temporal\hspace{0.5em}Gradient}, l=L,
\end{align}
$\epsilon^L$is defined as the sensitivity of the membrane potential $H^l(t+1)$ with respect to $H^l(t)$ between adjacent timesteps.
\begin{align}
\epsilon^{l}(t) \equiv\frac{\partial \mathbf{H}^{l}(t+1)}{\partial \mathbf{H}^{l}(t)}+\frac{\partial \mathbf{H}^{l}(t+1)}{\partial \mathbf{S}^{l}(t)} \frac{\partial \mathbf{S}^{l}(t)}{\partial \mathbf{H}^{l}(t)}.
\end{align}
If we use a simple rectangular function as a surrogate for the gradient.
\begin{align}
\epsilon^{l}(t)_{jj}=\left\{\begin{array}{l}
0, \quad \frac{1}{2} \vartheta<H_{j}^{l}(t)< \frac{3}{2} \vartheta, \\
1-\frac{1}{\tau}, \quad \text { otherwise } .
\end{array}\right.    
\end{align}
From the above equation, it can be concluded that if the membrane potential approaches the threshold at any given timestep, the temporal gradient 
 $\prod_{t^{\prime \prime}=1}^{t^{\prime}-t} \epsilon^{L}\left(t^{\prime}-t^{\prime \prime}\right)$ will vanish. This highlights a common issue with temporal gradients in the vanilla LIF model, which remains a problem even with short timesteps.

Next, we perform gradient analysis on neurons with a feedback structure. Assume the structure of the feedback is $\varphi$, which includes PM and CM.
\begin{align}
   \mathbf{H}^{l}(t+1)=\left(1-\frac{1}{\tau}\right)\left(\mathbf{H}^{l}(t)-\vartheta \mathbf{S}^{l}(t)\right)+\mathbf{W}^{l} \mathbf{S}^{l-1}(t+1)+\varphi_\theta  ( \mathbf{S}^{l}(t)) 
\end{align}
Following the above derivation, we similarly define the variable $\epsilon$:
\begin{align}
    \epsilon^{l}(t)\equiv \frac{\partial \mathbf{H}^{l}(t+1)}{\partial \mathbf{H}^{l}(t)}
+\frac{\partial \mathbf{H}^{l}(t+1)}{\partial \mathbf{S}^{l}(t)} \frac{\partial \mathbf{S}^{l}(t)}{\partial \mathbf{H}^{l}(t)} 
+ \underbrace{\frac{\partial{\mathbf{H}^l}(t+1)}{\partial{\varphi_\theta(\mathbf{S}^l(t))}} \frac{\partial{\varphi_\theta(\mathbf{S}^l(t))}}{\partial{\mathbf{S}^l(t)}} \frac{{\partial{\mathbf{S}^l(t)}}}{\partial{\mathbf{H}^l(t)}}}_{Feedback\hspace{1em}gradient}
\end{align}
\begin{align}   
\epsilon^{l}(t) = \left(1-\frac{1}{\tau}\right)-\left(1-\frac{1}{\tau}\right) \vartheta \cdot \frac{\partial \mathbf{S}^{l}(t)}{\partial \mathbf{H}^{l}(t)}+
\frac{\partial{\varphi_\theta(\mathbf{S}^l(t))}}{\partial{\mathbf{S}^l(t)}} \frac{{\partial{\mathbf{S}^l(t)}}}{\partial{\mathbf{H}^l(t)}}
\end{align}
Similarly we have:
\begin{align}
   \epsilon^{l}(t)_{jj}=\left\{\begin{array}{l}
\frac{\partial{\varphi_\theta(\mathbf{S}^l(t))}}{\partial{\mathbf{S}^l(t)}}, \quad \frac{1}{2} \vartheta<H_{j}^{l}(t)< \frac{3}{2} \vartheta, \\
1-\frac{1}{\tau}, \quad \text { otherwise } .
\end{array}\right. 
\end{align}
Then, in training, 
$\frac{\partial{\varphi_\theta(\mathbf{S}^l(t))}}{\partial{\mathbf{S}^l(t)}}$ is not possible to be zero.

