\section{Main Results}
To solve the non-convex Problem~\eqref{eq:opt_main}, we suggest reformulating it in terms of the reordered state $x_{R,t}=C_{R,t} x$ introduced in Section~\ref{subsec:obs}. 
Specifically, we consider the Seeker's best estimate of $x_{R,t}$ at time $t$ prior to receiving $ \bm{y}_{B,t} =y_{B,t}$ by $\hat{\bm{x}}^+_{R,t} $ with $\mathbb{E}[\hat{\bm{x}}^+_{r,t}]= \hat{x}^+_{R,t} = C_{R,t} \hat{x}_{t}^+$ and 
$ \mathbb{V}[\hat{\bm{x}}^+_{R,t}] = P^+_{R,t} = C_{R,t} \hat{P}_{t}^+ C_{R,t}^\top$, and after receiving $ \bm{y}_{B,t} =y_{B,t}$ by $\hat{\bm{x}}_{R,t+1} $ with $ \mathbb{E}[\hat{\bm{x}}_{R,t+1}] = \hat{x}_{R,t+1} = C_{R,t} \hat{x}_{t+1}$ and $ \mathbb{V}[\hat{\bm{x}}_{R,t+1}]=  P_{R,t+1} = C_{R,t} \hat{x}_{t+1} C_{R,t}^\top$, respectively. 
We decompose the error covariances to
\begin{align*}
    P_{R,t}^+= \begin{bmatrix}
        P_{BB,t}^+ & P_{BO,t}^+\\
        P_{OB,t}^+ & P_{OO,t}^+
    \end{bmatrix}, \ 
    P_{R,t+1}= \begin{bmatrix}
        P_{BB,t+1} & P_{BO,t+1}\\
        P_{DO,t+1} & P_{OO,t+1}
    \end{bmatrix},
\end{align*} 
where 
$P^{+}_{BB,t}=C_{B,t} P^+_{t} C_{B,t}^\top$,
$P^{+}_{OO,t} = C_{O,t} P^+_{t} C_{O,t}^\top$, 
and $P^{+}_{BO,t} = (P^{+}_{DO,t})^\top = C_{O,t} P^+_{t} C_{D,t}^\top$. The elements of $P_{R,t+1}$ are defined similarly. 
We accordingly define the diagonal matrix $W_{R,t}\triangleq C_{R,t} W_t C_{R,t}^\top$, which can be broken into $W_{R,t} = \mathrm{diag}(W_{BB,t}, W_{OO,t})$.

\begin{theorem}
 \label{theo:one}
 The following claims hold.
 \begin{enumerate}[label=\roman*)]
     \item $P_{BB,t+1}$ and $P_{OO,t+1}$ can be computed as
    \begin{align} \label{eq:p_bb}
        P_{BB,t+1} &= ((P_{BB,t}^{+})^{-1}\!+ \Theta_t^\top N_{t}^{-1} \Theta_t)^{-1},\\ \label{eq:p_dd}
         P_{OO,t+1} &= S_{t}+ Q_{t} P_{BB,t+1} Q_{t}^\top,
    \end{align}
    where $Q_{t} \triangleq P_{OB,t}^+ (P_{BB,t}^+)^{-1}$, and $S_{t} \triangleq P_{OO,t}^{+}- Q_{t} P_{BB,t}^{+} Q_{t}^\top$.
    \item The utility  
    $\mathrm{tr}(W_t P_{t+1})$ can be computed as
    \begin{align} \nonumber
        \mathrm{tr}(&W_t P_{t+1}) = \mathrm{tr}(W_{R,t} P_{R,t+1})\\ \label{eq:trace}
        &=\mathrm{tr}(\tilde{W}_{BB,t} P_{BB,t+1}) + \mathrm{tr}(W_{OO,t}S_{t}),
        \end{align} 
        where $\tilde{W}_{BB,t} \triangleq W_{BB,t} + Q_{t}^\top W_{OO,t} Q_{t}$.
    \item The bit-rate $I(\bm{o}^G_{B,t} ; \bm{y}^G_{B,t})$ can be computed as 
     \begin{align*}
       \hspace{-0.3cm} I(\bm{o}^G_{B,t} ; \bm{y}^G_{B,t}) \!=\! \frac{1}{2} \log\!\det( P_{BB,t}^+)\!-\!\frac{1}{2} \log\!\det( P_{BB,t+1}).
    \end{align*}
 \end{enumerate}
\end{theorem}
\begin{proof}
    See Appendix~\ref{appendix_one}.
\end{proof}

Using the results of Theorem~\ref{theo:one}, we may rewrite \eqref{eq:opt_main} in terms of the variables $P_{BB,t+1}$, $\Theta_t$, $N_{t}$ and $d_{\Theta_t}$ as
\begin{subequations}
\label{eq:opt_pbb}
    \begin{align}\label{eq:opt_pbb_a}
    \min \ \ &\mathrm{tr}(\tilde{W}_{BB,t} P_{BB,t+1})\!-\!\frac{\alpha}{2} \!\log\!\det(P_{BB,t+1}),\\ \label{eq:opt_pbb_b}
    \text{s.t.,} \ \  & P_{BB,t+1}\! =\! ((P_{BB,t}^{+})^{-1}\!+  \Theta_t^\top N_{t}^{-1} \Theta_t)^{-1},
\end{align}
\end{subequations}
where the constants 
$\mathrm{tr}(W_{OO,t}S_{t})$ and 
$\frac{\alpha}{2} \log \det( P^+_{BB,t})$ are omitted from the objective function \eqref{eq:opt_pbb_a}.
A mathematically similar problem to \eqref{eq:opt_pbb} appeared in the seminal paper \cite{tanaka2016semidefinite}. 
Following the method proposed in \cite{tanaka2016semidefinite}, we transform \eqref{eq:opt_pbb} into an optimization problem in terms of $P_{BB,t+1}$ only.  
This reformulation is achieved by replacing the nonlinear equality constraint \eqref{eq:opt_pbb_b} with a linear inequality constraint $ P_{BB,t} \preceq P_{BB,t-1}^+$. 
This replacement eliminates all the variables $\Theta_t$, $N_{t}$ and $d_{\Theta_t}$ from \eqref{eq:opt_pbb} yielding
\begin{subequations}
\label{eq:opt_convex}
    \begin{align}
    \min_{P_{BB,t+1}} \ \  &\mathrm{tr}(\tilde{W}_{BB,t} P_{BB,t+1})\!-\!\frac{\alpha}{2}\! \log\!\det(P_{BB,t+1}),\\ \label{eq:opt_con_cons}
    \text{s.t.,} \quad &P_{BB,t+1} \preceq P^+_{BB,t}.
\end{align}
\end{subequations}
Equations \eqref{eq:opt_pbb} and \eqref{eq:opt_convex} are mathematically equivalent, since eliminated variables can be constructed from any $P_{BB,t+1}$ satisfying \eqref{eq:opt_pbb_b} through
\begin{align}
\label{eq:theta_calc}
\Theta_t^\top  N_{t}^{-1} \Theta_t = P_{BB,t+1}^{-1} - (P^+_{BB,t})^{-1},
\end{align}
as follows. First, we compute the eigenvalue decomposition of the RHS of \eqref{eq:theta_calc} as $V_t^\top \Lambda_t V_t$. Due to the constraint \eqref{eq:opt_con_cons}, all eigenvalues are non-negative. Then, we decompose the diagonal matrix $\Lambda_t$ into two parts based on the strictly positive eigenvalues and zero eigenvalues as $\Lambda_t=\textup{blkdiag}(\Lambda_{t,+}\!\succ 0, 0)$, and, accordingly, decompose $V_t$ as $V_t=[V_{t,+}, V_{t, \mathrm{zero}}]$. It can be shown that $\Theta_t=V_{t,+}$, $\Sigma_{N,t}= \Lambda_{t,+}^{-1}$, and $d_{\Theta_t}= \mathrm{rank}(\Lambda_{t,+})$ (i.e., the number of strictly positive eigenvalues of $\Lambda_t$) satisfy \eqref{eq:theta_calc} and constitute feasible solutions for \eqref{eq:opt_pbb}.  To summarize this process, we define the reduced singular decomposition operator for any symmetric positive semi-definite matrix $A$ as $\textup{RSD}(A)= (V_{+}, \Lambda_{+})$, where $A=V^\top \Lambda V$, and $V_{+}$ and $\lambda_{+}$ retain only the components associated with strictly positive eigenvalues.  Then, Equation \eqref{eq:theta_calc} yields 
\begin{align*}
   (\Theta_t^\top,  N_{t}^{-1})  = \textup{RSD} (P_{BB,t+1}^{-1} - (P^+_{BB,t})^{-1}),
\end{align*}
with $d_{\Theta_t}= \mathrm{rank}(N_t)$. 

Problem \eqref{eq:opt_convex} is a determinant maximization problem subject to linear matrix inequality constraints.
As shown by \cite{vandenberghe1998determinant},  such problems are convex and can be efficiently solved using off-the-shelf semi-definite programming solvers. After finding $P_{BB,t+1}^*$, the minimizer of \eqref{eq:opt_convex}, the optimal compression $\Theta_t^*$ and optimal quantization $N_{t}^*$ can be constructed as explained above. It is worth noting that the optimal solutions are not unique. For instance, for any nonzero scalar $s$, the pair $(\Theta'_t=s\Theta_t^*, N'_{t}=s^2 N_{t}^*)$ is also optimal because it satisfies
\[
\Theta'^\top (N'_{t})^{-1} \Theta'= {\Theta_t^*}^\top (N_{t}^*)^{-1} \Theta_t^*.
\]
This non-uniqueness is intuitive, as the measurement $ \bm{y}_{B,t} = \Theta_t o_{B,t} +\bm{n}_t= y_{B,t}$ contains the same information as the scaled version $\bm{y}'_{B,t} = s\Theta_t o_{B,t} +s\bm{n}_t= y'_{B,t} = s y_{B,t}$.
Likewise, for any unitary matrix $U \in \mathbb{R}^{d_{\Theta_t} \times d_{\Theta_t}}$, the pair $(\Theta''_t = U \Theta_t^*, N''_{t}=U N_{t}^* U^\top)$ is also optimal. 

Although Problem~\eqref{eq:opt_convex} is convex and can, in principle, be solved efficiently, its high-dimensional nature, due to the size of the local map, may lead to computational inefficiencies in practice. Notably,
Problem \eqref{eq:opt_convex} is an instance of the standard Gaussian rate-distortion problem \cite{cover1999elements}.
It is well-known that this problem recovers the \textit{reverse water-filling} solution as explained in the following theorem.  

\begin{theorem}
\label{theo:two}
Denote the eigen-decomposition of $\tilde{W}_{BB,t}^{1/2}$ $P^+_{BB,t} \tilde{W}_{BB,t}^{1/2}$ by $U_t^\top D_t U_t$, where $D_t =\mathrm{diag}_{1\leq i\leq d_B}( \sigma_{i,t}^2)$ and $U_t$ is an unitary matrix $U_t U_t^\top = U_t^\top U_t=I$.
Then, the optimizer of \eqref{eq:opt_convex} is
 \begin{align} \label{eq:P_opt}
    P_{BB,t+1}^* 
   &= \tilde{W}_{BB,t}^{-1/2} U_t^\top \Phi_t  U_t \tilde{W}_{BB,t}^{-1/2},
\end{align} 
where,
\begin{align*}
    \Phi_t=\mathrm{diag}_{1\leq i \leq d_B} (\min\{ \frac{\alpha}{2}, \sigma_{i,t}^2\}).
\end{align*}
Moreover,
\begin{align} \label{eq:M_def}
   \!\!M_t &\!\triangleq\! {(P_{BB,t+1}^*)}^{-1}\!\!\!-\! (P^+_{BB,t})^{-1}  
   \!\!=\!\!\tilde{W}_{BB,t}^{1/2} U_t^\top \Sigma_t  U_t \tilde{W}_{BB,t}^{1/2},
\end{align}
where,
\begin{align}
\label{eq:sigma_opt}
 \Sigma_t = \operatorname*{diag}_{1 \leq i \leq d_{B}}(\max\{0, \frac{2}{\alpha}- \frac{1}{\sigma_{i,t}^2}\}).
\end{align}
The optimum compression and quantization levels can be computed as 
\begin{align} \label{eq:opt_theta}
    (\Theta_t^*, (N_{t}^*)^{-1}) 
   &=  \textup{RSD}(M_t).
   % \textup{RSD}( \tilde{W}_{BB,t}^{1/2} U_t^\top \Sigma_t  U_t \tilde{W}_{BB,t}^{1/2}).
\end{align} 

\end{theorem}
\begin{proof}
    The proof is provided in \cite[Subsection~IV.D]{tanaka2016semidefinite}. For completeness, the proof is summarized in Appendix~\ref{appendix_two} .
\end{proof}

By defining the set of indices of strictly positive diagonal elements of $\Sigma_t$ by $J_t \triangleq \{1\leq i \leq d_B: \alpha <  2\sigma_{i,t} ^2\}$, equations \eqref{eq:opt_theta} and \eqref{eq:sigma_opt} imply that $d_{\Theta_t^*}=$ dim$(\bm{y}^*_{B,t})= |J_t|$. 
This implication shows that the proposed formulation admits a low-dimensional solution, which is in full agreement with our intuition about compression. 
Moreover,  $d_{\Theta^*_t}$ monotonically decreases as the weight on the bit-rate, i.e., $\alpha$ in Equation \eqref{eq:alpha_def}, increases. 
Hence, the proposed bit-rate metric acts as an approximation of the cardinality of the used compressed representation. 

Using the closed-form expression \eqref{eq:opt_theta}, one may not need to solve the optimization problem \eqref{eq:opt_pbb}, and the optimal compression and quantization can be obtained from the strictly positive eigenvalues of the RHS of \eqref{eq:opt_theta} and the associated eigenvectors. We emphasize that not all elements of $N^*_{t}$ are equal.   
This non-uniformity highlights the flexibility of our formulation, wherein the bit-rate is optimally allocated across the components of the compression: more important components are preserved with higher precision, while less critical ones are compressed more aggressively.

\subsection{Noise in Supporter's Observation}
\label{subsec:noisy}
In this section, we consider the case where the Supporter's observation contains Gaussian noise as
\begin{align} \label{eq:noisy_obs}
\bm{o}_{B,t}= C_{B,t} x + \bm{\mu}_t, \quad \bm{\mu_t} \sim \mathcal{N}(0, V_t \succ 0).
% \sigma_{\mu}^2 I_{d_B}). 
\end{align}
Under this condition, the Seeker receives a measurement of $\bm{y}_{B,t}= \Theta_t C_{B,t} x + \Theta_t \bm{\mu}_t+ \bm{n_t}$.
All the results derived for the noise-less measurement case in Theorem~\ref{theo:one} can be repeated for the noisy measurement case by replacing $\bm{n}_t$ with 
% $\tilde{\bm{n}}_t \triangleq
$\Theta_t \bm{\mu}_t+ \bm{n_t}$, and, consequently, $N_{t}$ by 
% $\tilde{N}_t \triangleq$
$\Theta_t V_t \Theta_t^\top +N_{t}$. However, the optimal compression design problem \eqref{eq:opt_pbb}  becomes
\begin{subequations}
\label{eq:opt_noisy}
    \begin{align}
    \min \ \ &\mathrm{tr}(\tilde{W}_{BB,t} P_{BB,t+1})\!-\!\frac{\alpha}{2} \!\log\!\det(P_{BB,t+1}),\\ 
    % \label{eq:opt_noisy_b}
    \nonumber
    \text{s.t.,} \ \  & P_{BB,t+1}\! =\! ((P_{BB,t}^{+})^{-1} +\\ \label{eq:opt_noisy_c}
    & \qquad \qquad \quad \Theta_t^\top ( \Theta_t V_t \Theta_t^\top +N_{t}) ^{-1}\Theta_t)^{-1},
\end{align}
\end{subequations}
where the variables are $P_{t+1} \in \mathbb{S}_{+}^{d}, N_{t} \in \mathbb{D}_{d_{\Theta_t}}$, $\Theta_t \in \mathbb{R}^{d_{\Theta_t}\times d_{B}}$, and $d_{\Theta_t} \in \{0, 1, \dots, d_B\}$. 
Problem \eqref{eq:opt_noisy} cannot be transformed to Problem \eqref{eq:opt_convex}, in general.
The following proposition provides a condition under which \eqref{eq:opt_noisy_c} can be relaxed to \eqref{eq:opt_con_cons}, thereby enabling the transformation to \eqref{eq:opt_convex}.

\begin{proposition}
    Let $P_{BB,t+1}^*$ be the optimizer of \eqref{eq:opt_convex} as given in \eqref{eq:P_opt} in Theorem~\ref{theo:two}, and let $M_t$ be defined accordingly as \eqref{eq:M_def}. Let
    \begin{align} \label{eq:condition}
        M_t \prec V_t^{-1}. 
    \end{align}
     Then, $P_{BB, t+1}^*$ is the optimizer of \eqref{eq:opt_noisy}, and the corresponding compression and quantization parameters are given by
     \[ (\Theta_t^*, (N_{t}^*)^{-1}) 
   =  \textup{RSD}((V_t - V_t M_t V_t)^{-1}-V_t^{-1}).
\] 
\end{proposition}
\begin{proof}
    From \eqref{eq:opt_noisy_c}, we have $M_t = \Theta_t^\top ( \Theta_t V_t \Theta_t^\top +N_{t}) ^{-1}\Theta_t$. By pre- and post-multiplying both sides with $V_t$, we obtain
    \begin{align*}
        V_t M_t V_t &= V_t \Theta_t^\top ( \Theta_t V_t \Theta_t^\top +N_{t}) ^{-1}\Theta_t V_t \\
        &= V_t - (V_t^{-1} + \Theta_t^\top N^{-1} \Theta_t)^{-1},
    \end{align*}
    where we have used the Woodbury matrix inversion Lemma \cite{woodbury1950inverting}. Rearranging terms under the condition $V_t\succ V_t M_t V_t$ (or, equivalently, $M_t \prec V_t^{-1}$), gives
    \begin{align*}
        \Theta_t^\top N^{-1} \Theta_t= (V_t - V_t M_t V_t)^{-1}-V_t^{-1},
    \end{align*}
    which completes the proof.
\end{proof}

The matrix $V_t^{-1}$ represents the information content of the original observation model \eqref{eq:noisy_obs}, and thus characterizes the maximum information that can be extracted by any compression \eqref{eq:noisy_obs}. Hence, if $M_t$, which quantifies the information content of the optimally compressed signal obtained from the noise-free formulation (i.e., Problem~\eqref{eq:opt_convex}), satisfies condition \eqref{eq:condition}, then it is achievable under the noisy model, and $M_t$ is a valid optimizer of Problem~\eqref{eq:opt_noisy}.  



\subsection{Planning based on Estimated Values}
As discussed in Section~\ref{sect:planner}, path-planning is performed based on the estimated occupancy values $\hat{x}_t$ projected on the interval $[0, 1]$. However, planning based on these estimates can be problematic when the utilized compression $\bm{y} = \Theta x_B + \bm{n}$ with $\bm{n} \sim \mathcal{N}(0, N)$ has low signal-to-noise ratio (SNR) components. We define the SNR matrix as $\textup{SNR} \triangleq {\Theta}^{\top} {N}^{-1} \Theta$, where small eigenvalues correspond to low-SNR components. 


