\section{Proof of Proposition~\ref{prop}}
\label{appendix_zero}
For $I(\bm{o}_{B,t} ; \bm{y}_{B,t})$, it follows that
\begin{align}
\nonumber
    &I(\bm{o}_{B,t} ; \bm{y}_{B,t}) 
   = h(\bm{y}_{B,t}) - h(\bm{y}_{B,t} | \bm{o}_{B,t}) \\
   \nonumber
   &= h(\bm{y}_{B,t}) - h(\bm{o}_{B,t} + \bm{n}_{t} | \bm{o}_{B,t}) = h(\bm{y}_{B,t})-  h(\bm{n}_{t}),
\end{align}
where the last equality follows from the fact that $\bm{n}_{t}$ and $\bm{o}_{B,t}$ are independent. A similar result can be established for $I(\bm{o}^G_{B,t} ; \bm{y}^G_{B,t})$. Thus, it follows that
\begin{align}
\nonumber
\hspace{-0.6em}
    I(\bm{o}_{B,t} ; \bm{y}_{B,t}) 
   &\!-\! I(\bm{o}^G_{B,t} ; \bm{y}^G_{B,t})\\ \label{eq:I_diff}
   &\!=\!(h(\bm{n}^G_t)\!-\! h(\bm{n}_t)) \!-\! (h(\bm{y}^G_t)\!-\! h(\bm{y}_t)).
\end{align}
On the other hand, for a Gaussian random variable  $\bm{x}^G$ and any other random variable $\bm{x}$ with
the same mean and covariance matrix, we have that 
$\mathrm{KL}(\bm{x}_{t} \| \bm{x}^G_{t})= h(\bm{x}^G_t)- h(\bm{x}_t)$ \cite[Fact~C.4]{silva2009unified}. Using this relation to simplify \eqref{eq:I_diff} establishes \eqref{eq:KL_diff}. Furthermore,
\begin{align*}
    &\mathrm{KL}(\bm{n}_{t} \| \bm{n}^G_{t}) \!=\! h(\bm{n}^G_t)\!-\! h(\bm{n}_t) \!=\! \textstyle\sum_{i=1}^ {d_{\Theta_t}} h([\bm{n}^G_t]_i)\!-\! h([\bm{n}_t]_i)\\
    &=\textstyle\sum_{i=1}^ {d_{\Theta_t}} 
     \frac{1}{2} \log(\frac{2\pi e \ \Delta_{i,t}^2}{12}) -  \log(\Delta_{i,t})\!\!=\! \frac{d_{\Theta_t}}{2} \log \frac{2\pi e}{12},
\end{align*}
where we used the fact that elements of $\bm{n}_t$ (similarly, $\bm{n}^G_t$) are mutually independent.

\section{Proof of Theorem~\ref{theo:one}}
\label{appendix_one}
    \subsection*{Proof of claim~i)}
    Let us define the joint random variable $\bm{z}_t \triangleq [\hat{\bm{x}}_{B,t}^{+\top},
    \hat{\bm{x}}_{O,t}^{+\top}, \bm{y}_{B,t}^\top]^\top\!\!$. It is easy to verify that $\bm{z}_t$ has mean  $\mathbb{E}[\bm{z}_t] = [\hat{x}_{B,t}^{+\top}, \hat{x}_{O,t}^{+\top}, (\Theta_{t} \hat{x}^+_{B,t})^\top]^\top$ and covariance 
    \begin{align*}
        &\mathbb{V}[\bm{z}_t] =\begin{bmatrix}
        P_{BB,t}^+ & P_{BO,t}^+ & P_{BB,t}^+ \Theta_{t}^\top\\
        P_{OB,t}^+ & P_{OO,t}^+ & P_{OB,t}^+ \Theta_{t}^\top\\
        \Theta_{t} P_{BB,t}^+ & \Theta_{t}  P_{BO,t}^+  & \Theta_{t} P_{BB,t}^+ \Theta_{t}^\top + N_{t}
        \end{bmatrix}
        .
    \end{align*}
The LMVE is mathematically equivalent to the marginalization of the jointly Gaussian distribution. Therefore, one may compute the conditional covariance $P_{BB,t+1} = \mathbb{V}[\hat{\bm{x}}^+_{B,t}| \bm{y}_{B,t}]$ as
\begin{align}
    \nonumber
        P_{BB,t+1}&\!=\!P_{BB,t}^{+}\!\!-\!\!P_{BB,t}^{+}
        \Theta_{t}^\top\!(\Theta_{t} P_{BB,t}^+ \Theta_{t}^ \top\!\!+ \!N_{t})^{-1} 
        \Theta_{t} P_{BB,t}^+\\ \label{eq:bb_iter}
        &\!=\!((P_{BB,t}^{+})^{-1}\!+ \Theta_t^\top N_{t} ^{-1}\Theta_t)^{-1},
\end{align}
where in the last inequality we have used the Woodbury matrix inversion Lemma \cite{woodbury1950inverting}.
Similarly, we compute $P_{OO,t+1} = \mathbb{V}[\hat{\bm{x}}^+_{O,t}| \bm{y}_{B,t}]$ as
\begin{align} \nonumber
        &P_{OO,t+1} = \\ \label{eq:dd_iter}
        & P_{OO,t}^{+}\!\!-\!\!P_{OB,t}^{+}
        \Theta_{t}^\top\!
        (\Theta_{t} P_{BB,t} \Theta_{t}^ \top\!\!+\!N_{t}\!)^{-1}  \Theta_{t} P_{BO,t}^+. 
\end{align}
From \eqref{eq:bb_iter}, we have $\Theta_{t}^\top\!
        (\Theta_{t} P_{BB,t} \Theta_{t}^ \top\!\!+\! N_{t})^{-1}  \Theta_{t} = (P_{BB,t}^+)^{-1} (P_{BB,t}^+- P_{BB,t+1}
        )(P_{BB,t}^+)^{-1}$. 
        Substituting this expression in \eqref{eq:dd_iter} yields
\begin{align*}
    P_{OO,t+1} = S_{t}+ Q_{t} P_{BB,t+1} Q_{t}^\top,
\end{align*}
where $Q_{t}\!\triangleq\! P_{OB,t}^+ (P_{BB,t}^+)^{-1}\!$, and $S_{t}\! \triangleq \!P_{OO,t}^{+}\!-Q_{t} P_{BB,t}^{+} Q_{t}$.

\subsection*{Proof of claim~ii)}
The first equality in \eqref{eq:trace} is established as follows:
\begin{align*}
    &\mathrm{tr}(W_{R,t} P_{R,t+1})= \mathrm{tr}(C_{R,t} W_t C_{R,t}^\top C_{R,t} P_{t+1}C_{R,t}^\top)\\
    & =\mathrm{tr}(C_{R,t} W_t P_{t+1}C_{R,t}^\top) = \mathrm{tr}(W_t P_{t+1}C_{R,t}^\top C_{R,t})\\
    &=\mathrm{tr}(W_t P_{t+1}),
\end{align*}
where we have used the fact that $C_{R,t}$ is a unitary matrix and that the trace of a product of matrices is invariant under cyclic permutations. Using the fact that $W_{R,t}$ is diagonal, we have
\begin{align} 
    \label{eq:trace_1}
    &W_{R,t} P_{R,t+1}= \begin{bmatrix}
        W_{BB} P_{BB} & W_{BB} P_{BO}\\
        W_{OO} P_{OB}   &  W_{OO} P_{OO}
    \end{bmatrix}.
\end{align}
Applying the trace operator on both sides of \eqref{eq:trace_1} yields
\begin{align*}
    &\mathrm{tr}(W_{R,t} P_{R,t+1}) =\\
    &\mathrm{tr}(W_{BB,t} P_{BB,t+1}) + \mathrm{tr}(W_{OO,t} P_{OO,t+1})=\\ 
    &\mathrm{tr}(W_{BB,t} P_{BB,t+1}) + \mathrm{tr}(W_{OO,t} S_{t}) 
    \\ & \qquad \qquad \qquad \qquad \  +\mathrm{tr}(W_{OO,t} Q_{t} P_{BB,t+1} Q_{t}^\top),
\end{align*}
where we plugged the value $P_{OO,t}$ from \eqref{eq:p_dd}.
Finally, defining $\tilde{W}_{BB,t} \triangleq W_{BB,t} + Q_{t}^\top W_{OO,t} Q_{t}$ completes the proof.

\subsection*{Proof of claim iii)}
Substituting $P_{BB,t}=C_{B,t} P_t^+ C_{B,t}^\top$ in \eqref{eq:mutal_first}, we have
$ I(\bm{o}^G_{B,t};\bm{y}^G_{B,t})\!=\!
    \frac{1}{2} \log\!\det(\Theta_t P_{BB,t}^+ \Theta_t^\top+ N_{t})-\frac{1}{2} \log\!\det(N_{t})$. 
    Using the matrix determinant Lemma \cite{harville1998matrix}, we have that $\det(\Theta_t P_{BB,t}^+ \Theta_t^\top+N_{t})\!=\! \det(P_{BB,t}^+) \det(N_{t})\\ \det((P_{BB,t}^+)^{-1}+ \Theta_t^\top N_t^{-1} \Theta_t)$. Thus,
    \begin{align*}
I(\bm{o}^G_{B,t};\bm{y}^G_{B,t})\!=& \frac{1}{2} \log\!\det(P_{BB,t}^+)\\ 
&+\frac{1}{2}
\log\!\det((P_{BB,t}^+)^{-1}+ \Theta_t^\top N_{t}^{-1} \Theta_t) \\
=& \frac{1}{2}\log\!\det(P_{BB,t}^+)- \frac{1}{2}\log\!\det(P_{BB,t+1}),
\end{align*}
where we used \eqref{eq:p_bb} in the last equality.

