\section{Proof of Theorem~\ref{theo:two}}
\label{appendix_two}
Let $\tilde{W}_{BB,t}^{1/2} P^+_{BB,t} \tilde{W}_{BB,t}^{1/2}$ have the eigen-decomposition as $U_t^\top D U_t$, where $D_t= \mathrm{diag}_{1\leq i \leq d_i}( \sigma_{i,t}^2)$ and $U_t$ is a unitary matrix $U_tU_t^\top=U_t^\top U_t=I$. 
By defining the new variable $Q\triangleq U_t \tilde{W}_{BB,t}^{1/2} P_{BB,t+1} \tilde{W}_{BB,t}^{1/2} U_t^\top$, we may verify that $\mathrm{tr}(Q) = \mathrm{tr}(\tilde{W}_{BB,t} P_{BB,t+1})$ and also $\log\!\det(Q) =\log\!\det(P_{BB,t+1}) +\log\!\det(\tilde{W}_{BB,t})$. For $\tilde{W}_{BB,t}^{1/2} \succ 0$, we have that $P_{BB,t+1} \preceq P^+_{BB,t}$ if and only if
\begin{align*}
\tilde{W}_{BB,t}^{1/2} P_{BB,t+1} \tilde{W}_{BB,t}^{1/2} \preceq \tilde{W}_{BB,t}^{1/2} P^+_{BB,t} \tilde{W}_{BB,t}^{1/2},
\end{align*}
which, after conjugation by the unitary matrix $U_t$, is equivalent to $Q \preceq D$. 

By ignoring the constant term $ \log\!\det(\tilde{W}_{BB,t})$, Problem \eqref{eq:opt_convex} can be cast as the following problem in terms of $Q$.
\begin{subequations}
\label{eq:hadamard}
    \begin{align}
    \min_{Q} \quad&  \mathrm{tr}(Q)- \frac{\alpha}{2} \log\!\det(Q),\\
    \text{s.t.,} \quad 
    & Q \preceq D = \mathrm{diag}_{1\leq i \leq d_B}(\sigma_{i,t}^2) .
\end{align}
\end{subequations}
For any positive definite matrix $Q$, Hadamard's inequality states that $\det (Q) \leq \Pi_i Q_{ii}$  and the equality holds if and only if the matrix is diagonal. 
Hence, if the diagonal elements of $Q$ are fixed, $\det(Q)$ is maximized by setting all off-diagonal entries to zero. 
Thus, the optimal solution to \eqref{eq:hadamard} is diagonal.


Writing $Q = \mathrm{diag}_{1\leq i \leq d_B}(q_i)$, the problem is decomposed as $d_B$ independent optimization problems, each of which minimizes $q_i-(\alpha/2) \log q_i$ subject to $0\leq q_i\leq \sigma_{i,t}^2$. 
Direct calculation yields that the optimal solution is $q^*_i=\min(\alpha/2, \sigma_{i,t}^2)$, and thus \[Q^*=\operatorname*{diag}_{1\leq i \leq d_B} (\min\{ \frac{\alpha}{2}, \sigma_{i,t}^2\}).
\]
To compute $\Theta_t^*$, we first need to compute $(P_{BB,t+1}^*)^{-1}$. From the definition of $Q$, we have 
\begin{align*}
(Q^*)^{-1} &= \operatorname*{diag}_{1\leq i \leq d_B} (\max \{ \frac{2}{\alpha}, \frac{1}{\sigma_{i,t}^2}\}) \\
&= U_t \tilde{W}_{BB,t}^{-1/2} (P_{BB,t+1})^{-1} \tilde{W}_{BB,t}^{-1/2} U_t^\top.
\end{align*}
Therefore, 
\begin{align*}
(P_{BB,t+1}^*)^{-1}\!=\!\tilde{W}_{BB,t}^{1/2} U_t^\top & \!\!\!\operatorname*{diag}_{1\leq i \leq d_B}(\max \{\frac{2}{\alpha}, \frac{1}{\sigma_{i,t}^2}\}) U_t \tilde{W}_{BB,t}^{1/2}.
\end{align*}
From the definition of $D_t$, we have \[(P_{BB,t}^+)^{-1} = \tilde{W}_{BB,t}^{1/2} U_t^\top \!\!\!\operatorname*{diag}_{1\leq i \leq d_B}(\frac{1}{\sigma_{i,t}^2})  U_t \tilde{W}_{BB,t}^{1/2}.
\]
 Substituting these values in \eqref{eq:theta_calc}, the optimal compression $\Theta_t^*$ and quantization $N_{t}^{*}$ satisfy
\begin{align*}
   &{\Theta_t^*}^\top (N_{t}^{*})^{-1} \Theta_t^* =  {(P_{BB,t+1}^*)}^{-1} - (P^+_{BB,t})^{-1} \\
   &= \tilde{W}_{BB,t}^{1/2} U_t^\top \! \operatorname*{diag}_{1\leq i \leq d_B}(\max\{0, \frac{2}{\alpha}\!-\! \frac{1}{\sigma_{i,t}^2}\}) \  U_t \tilde{W}_{BB,t}^{1/2}. 
\end{align*}
Letting $\displaystyle
 \Sigma_t \!\triangleq\!\!\!\!\operatorname*{diag}_{1 \leq i \leq d_{B}}\!\!(\max\{0, \frac{2}{\alpha}\!-\!\frac{1}{\sigma_{i,t}^2}\})$ completes the proof. 



